check_ctx_contract.c.text:
/* Regression for CONTESTED-PREMISES.md §17. Exercise the real C dispatchers at
 * their VM boundary; no TMM or assembly required. The stand-in program checks
 * the complete verifier-visible region, then overwrites it. Repeated calls
 * must get fresh zeros, and program writes must not change the saved registers
 * or exit shadow frame. Run with ASan too: passing a length of 96 alone is not
 * proof that the caller actually allocated 96 bytes.
 */
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "ls_arm.h"
#include "ls_fexit.h"
#include "check_snapshot_stubs.h"
#include "ls_vm.h"

/* The C exit dispatcher only needs this symbol's address, never executes it. */
char ls_fexit_stub[1];

static const uint64_t args[6] = {0xA1, 0xB2, 0xC3, 0xD4, 0xE5, 0xF6};
static int exit_context;
static enum ls_verdict verdict;
static unsigned calls;

uint64_t ls_vm_safe_value(int slot)
{
    assert(slot == 3);
    return 2;
}

enum ls_verdict ls_vm_call(int slot, void *ctx, size_t n)
{
    const unsigned char *bytes = ctx;
    uint64_t ret;
    size_t payload = exit_context ? 48 : 40;

    assert(slot == 3);
    assert(ctx != NULL);
    /* Independent literal: shrinking a shared constant must not shrink the test. */
    assert(n == 96);
    assert(memcmp(ctx, args, 40) == 0);
    if (exit_context) {
        memcpy(&ret, bytes + 40, sizeof ret);
        assert(ret == 0xBEEF);
    }
    for (size_t i = payload; i < 96; i++)
        assert(bytes[i] == 0);

    /* Includes bytes 88..95, the read accepted by the pinned verifier. */
    memset(ctx, 0xA5, 96);
    calls++;
    return verdict;
}

int main(void)
{
    struct ls_regs regs = {
        .r11 = 0x11, .r10 = 0x10, .rax = 0xAA,
        .r9 = 0xF6, .r8 = 0xE5, .rcx = 0xD4,
        .rdx = 0xC3, .rsi = 0xB2, .rdi = 0xA1,
    };
    const struct ls_regs original = regs;

    for (unsigned i = 0; i < 32; i++) {
        verdict = i % 2 ? LS_SAFE_RETURN : LS_FALLTHROUGH;
        struct ls_tramp_result r = ls_tramp_dispatch(3, &regs);
        assert(r.verdict == (int)verdict);
        assert(r.safe_value == (verdict == LS_SAFE_RETURN ? 2 : 0));
        assert(memcmp(&regs, &original, sizeof regs) == 0);
    }
    assert(calls == 32);
    struct ls_tramp_result r = ls_tramp_dispatch(3, NULL);
    assert(r.verdict == LS_FALLTHROUGH && r.safe_value == 0);
    assert(calls == 32);

    exit_context = 1;
    verdict = LS_SAFE_RETURN;       /* must be ignored by the exit path */
    ls_fexit_reset();
    for (unsigned i = 0; i < 32; i++) {
        uint64_t return_slot = 0x12345678;
        ls_fexit_enter(3, &return_slot, args);
        assert(return_slot == (uint64_t)(void *)ls_fexit_stub);
        uint64_t target = ls_fexit_leave((uint64_t)(void *)(&return_slot + 1), 0xBEEF);
        assert(target == 0x12345678);
        assert(g_ls_fexit_log[i].retval == 0xBEEF);
        assert(memcmp(g_ls_fexit_log[i].args, args, sizeof args) == 0);
    }
    assert(calls == 64);
    assert(g_ls_fexit_exits == 32 && g_ls_fexit_desync == 0);
    puts("ok    context contract: entry + exit, 96 bytes, zero tails, isolated writes, repeated calls");
    return 0;
}

check_fexit.c.text:
/*
 * check_fexit.c --- proves the function-EXIT trampoline on real x86-64 hardware.
 *
 * Arms four stand-ins (fexit_victims.S) whose entry pads call ls_fexit_entry, and
 * asserts the properties an exit hook must have:
 *
 *   A  the caller still receives the true return value  (the stub is transparent)
 *      and the exit program is handed that value AND the entry arguments;
 *   B  a nested armed call unwinds its exits LIFO (inner before outer);
 *   C  deep recursion stays synced --- n+1 exits, deepest returns first;
 *   D  a return SKIPPED by a longjmp is reclaimed, and the next exit is correct.
 *
 * D is the one the whole shadow-stack-keyed-by-SP design exists for. Each stand-in
 * is armed at a per-slot exit trampoline (ls_fexit_slot<n>, folded into
 * trampoline_x86_64.S). Build:
 *   gcc -O2 -fcf-protection=branch -o check_fexit \
 *       check_fexit.c ls_fexit.c ls_tramp.c trampoline_x86_64.S fexit_victims.S
 */

#include <stdint.h>
#include <stdio.h>
#include <setjmp.h>

#include "ls_fexit.h"
#include "check_snapshot_stubs.h"

/* The exit program's stand-in. ls_fexit_leave now RUNS the program (step #2) via
 * ls_vm_call, handing it struct ls_ctx_exit; in TMM this is the real VM. Here it
 * records exactly what it was handed, so the test can assert the program receives
 * the right slot and exit context (entry args + return value). It also satisfies
 * the linker for the ENTRY slots' ls_tramp_dispatch, which never runs here. */
struct { int slot; uint64_t ret; uint64_t arg[5]; unsigned calls; } g_vm;
enum ls_verdict ls_vm_call(int slot, void *ctx, size_t n)
{
    const struct ls_ctx_exit *c = ctx;
    if (n >= sizeof *c) {
        g_vm.slot = slot;
        g_vm.ret  = c->ret;
        for (int i = 0; i < 5; i++) g_vm.arg[i] = c->arg[i];
        g_vm.calls++;
    }
    return 0;   /* verdict ignored at exit */
}
uint64_t ls_vm_safe_value(int slot) { (void)slot; return 2; }

extern uint64_t xv_leaf(uint64_t, uint64_t, uint64_t, uint64_t, uint64_t);
extern uint64_t xv_mid (uint64_t, uint64_t, uint64_t, uint64_t, uint64_t);
extern uint64_t xv_rec (uint64_t);
extern uint64_t xv_jumps(void *);
extern uint64_t xv_outer(void);

static jmp_buf g_jb2;
static volatile uint64_t g_sink;

/* Deeper than the setjmp in mid_setjmp, so the skipped xv_jumps frame is ON TOP
 * of the shadow stack when xv_outer's exit later fires. noinline + using the
 * result keep it from being tail-called (which would reuse the return slot). */
static __attribute__((noinline)) void inner_chain(void)
{
    g_sink += xv_jumps(g_jb2);      /* armed; longjmps back to mid_setjmp; never returns */
}

/* Called from xv_outer's asm body (hence external linkage). setjmp sits BELOW
 * xv_outer and ABOVE xv_jumps; the longjmp returns control here, then normally up
 * into xv_outer, whose exit then fires with the stale inner frame on top. */
void mid_setjmp(void)
{
    if (setjmp(g_jb2) == 0)
        inner_chain();
}

static int fails;
#define CHECK(cond, msg) do { \
    if (!(cond)) { printf("  FAIL %s\n", (msg)); fails++; } \
    else         { printf("  ok   %s\n", (msg)); } \
} while (0)

int
main(void)
{
    uint64_t r;

    puts("A --- leaf: return capture + transparency + entry args + exit program runs");
    ls_fexit_reset();
    g_vm.calls = 0;
    r = xv_leaf(0xA1, 0xB2, 0xC3, 0xD4, 0xE5);
    printf("    ret=%#llx exits=%llu reclaimed=%llu desync=%llu\n",
           (unsigned long long)r, (unsigned long long)g_ls_fexit_exits,
           (unsigned long long)g_ls_fexit_reclaimed, (unsigned long long)g_ls_fexit_desync);
    CHECK(r == 0x1EAF, "A caller receives the real return value (stub transparent)");
    CHECK(g_ls_fexit_exits == 1 && g_ls_fexit_log_n == 1, "A exactly one exit observed");
    CHECK(g_ls_fexit_log[0].retval == 0x1EAF, "A exit program sees the return value");
    CHECK(g_ls_fexit_log[0].args[0] == 0xA1 && g_ls_fexit_log[0].args[4] == 0xE5,
          "A entry arguments captured and carried to the exit");
    CHECK(g_ls_fexit_log[0].slot == 1, "A the exit-program slot is carried (leaf armed at 1)");
    CHECK(g_ls_fexit_reclaimed == 0 && g_ls_fexit_desync == 0, "A no reclaim, no desync");
    CHECK(g_vm.calls == 1, "A the exit PROGRAM ran once (ls_vm_call)");
    CHECK(g_vm.slot == 1 && g_vm.ret == 0x1EAF, "A program got the right slot + return value");
    CHECK(g_vm.arg[0] == 0xA1 && g_vm.arg[4] == 0xE5, "A program got the entry args in the exit ctx");

    puts("B --- nested: xv_mid calls xv_leaf, both armed");
    ls_fexit_reset();
    r = xv_mid(0x11, 0x22, 0x33, 0x44, 0x55);
    printf("    ret=%#llx exits=%llu\n", (unsigned long long)r,
           (unsigned long long)g_ls_fexit_exits);
    CHECK(r == 0x1FAF, "B nested return propagates (mid = leaf + 0x100)");
    CHECK(g_ls_fexit_exits == 2, "B two exits");
    CHECK(g_ls_fexit_log[0].seq == 2 && g_ls_fexit_log[0].retval == 0x1EAF,
          "B inner (leaf) exits FIRST --- LIFO");
    CHECK(g_ls_fexit_log[0].slot == 1 && g_ls_fexit_log[1].slot == 0,
          "B each exit carries its own slot (leaf=1, mid=0)");
    CHECK(g_ls_fexit_log[1].seq == 1 && g_ls_fexit_log[1].retval == 0x1FAF,
          "B outer (mid) exits second");
    CHECK(g_ls_fexit_desync == 0, "B no desync");

    puts("C --- recursion: xv_rec(7), every level armed");
    ls_fexit_reset();
    r = xv_rec(7);
    printf("    ret=%llu exits=%llu reclaimed=%llu\n", (unsigned long long)r,
           (unsigned long long)g_ls_fexit_exits, (unsigned long long)g_ls_fexit_reclaimed);
    CHECK(r == 7, "C recursion returns n");
    CHECK(g_ls_fexit_exits == 8, "C n+1 exits");
    CHECK(g_ls_fexit_log[0].retval == 0 && g_ls_fexit_log[0].seq == 8, "C deepest returns first");
    CHECK(g_ls_fexit_log[7].retval == 7 && g_ls_fexit_log[7].seq == 1, "C shallowest returns last");
    CHECK(g_ls_fexit_reclaimed == 0 && g_ls_fexit_desync == 0, "C clean nesting, no reclaim");

    puts("D --- reclaim: a longjmp skips an inner exit; the outer exit must reclaim it");
    ls_fexit_reset();
    r = xv_outer();                 /* inner armed chain longjmps back into xv_outer's body */
    printf("    ret=%#llx exits=%llu reclaimed=%llu desync=%llu\n",
           (unsigned long long)r, (unsigned long long)g_ls_fexit_exits,
           (unsigned long long)g_ls_fexit_reclaimed, (unsigned long long)g_ls_fexit_desync);
    CHECK(r == 0x0117, "D outer returns correctly after a longjmp back into its body");
    CHECK(g_ls_fexit_exits == 1, "D only the outer exit fired (inner was skipped)");
    CHECK(g_ls_fexit_reclaimed == 1, "D the skipped inner frame was reclaimed (SP-keyed)");
    CHECK(g_ls_fexit_log[0].retval == 0x0117, "D the outer exit sees its own return value");
    CHECK(g_ls_fexit_desync == 0, "D reclaim resynced without desync");

    printf("\n  %s\n", fails
        ? "FAILURES --- exit trampoline NOT validated"
        : "exit trampoline validated: capture, transparency, nesting, recursion, reclaim");
    return fails ? 1 : 0;
}

check_snapshot.bpf.c.text:
/* Verified test program. Only the output receiver is replaced in the host test. */
#include "check_snapshot_abi.h"
#ifndef OWNER
#define OWNER 1
#endif
struct map_def { unsigned type, key_size, value_size, entries, flags; };
struct map_def snapshot_test_events
    __attribute__((section("maps"), used)) = {4, 4, 4, 1, 0};
static long (*read_mem)(void *, __UINT64_TYPE__, __UINT64_TYPE__)
    = (void *)4;
static long (*emit)(void *, void *, __UINT64_TYPE__, void *, __UINT64_TYPE__)
    = (void *)25;

__attribute__((section("fexit/snapshot/snapshot_victim"), used))
__UINT64_TYPE__ snapshot_probe(struct ls_snapshot_ctx *ctx)
{
    if (ctx->phase == LS_SNAPSHOT_ENTRY) {
        unsigned disabled = 0;
        if (ctx->arg[2] == 9)
            return 0; /* Intentional omitted capture. */
        if (ctx->arg[0] && read_mem(&disabled, 4, ctx->arg[0]))
            return 0;
        ctx->state[0] = 1;
        ctx->state[1] = ctx->arg[0] && ctx->arg[1] == 57 && !disabled;
        ctx->state[2] = ctx->arg[4];
        ctx->state[3] = OWNER;
        if (ctx->arg[2] == 11) {
            ctx->arg[0] = ctx->arg[1] = ctx->arg[2] = ~0ull;
            ctx->arg[3] = ctx->arg[4] = ctx->no_return = ~0ull;
            ctx->phase = ctx->flags = ~0u;
            ctx->sequence = ~0ull;
        }
    } else if (ctx->phase == LS_SNAPSHOT_RETURN) {
        struct snapshot_observation out = {0};
        out.sequence = ctx->sequence; out.serial = ctx->arg[4];
        out.owner = OWNER; out.no_return = ctx->no_return;
        out.node = ctx->arg[0]; out.event = ctx->arg[1];
        out.phase = ctx->phase; out.flags = ctx->flags;
        if (ctx->flags == LS_SNAPSHOT_CAPTURED) {
            out.known = ctx->state[0]; out.eligible = ctx->state[1];
            out.marker = ctx->state[3];
        }
        emit(ctx, &snapshot_test_events, 0, &out, sizeof out);
        /* Writes must not change the saved return address or caller state. */
        ctx->arg[0] = ctx->no_return = ctx->sequence = ~0ull;
    }
    return 1; /* Both phases must ignore a SAFE_RETURN selection. */
}

check_snapshot.c.text:
/* Production VM + production return frames. Authored target and output sink. */
#define LS_MAP_GLUE_IMPL
#include "ls_vm.c"
#include "ls_fexit.h"
#include "check_snapshot_abi.h"
#include <assert.h>
#include <setjmp.h>

enum { INIT = 57, DEPTH = 512, MAX_EVENTS = 1024 };
enum action { PLAIN, DISABLE, ENABLE, NEST, RECURSE, PROTECT, SKIP,
              OUTER_SKIP, RELOAD, OMIT, BAD_READ, SMASH, PAUSE, RESTORE,
              RESTORE_FUEL };
struct object { unsigned disabled, initialized; };
static struct snapshot_observation observations[MAX_EVENTS];
static unsigned count, writes, reads;
static size_t page_size, replacement_len;
static void *replacement;
static jmp_buf jump;
uint64_t cv_return_noise;
extern int g_ls_fexit_top;
extern uint64_t g_ls_fexit_seq;
extern void cv_target(struct object *, uint64_t, uint64_t, uint64_t, uint64_t);

int ls_tp_publish_raw(int slot, const void *record, unsigned long length)
{
    assert(slot == 1 && length == sizeof observations[0]);
    assert(count < MAX_EVENTS);
    memcpy(&observations[count++], record, length);
    return 0;
}

int ls_tp_emit_shield(int slot, unsigned gen, unsigned mode, unsigned verdict,
                      const void *ctx, unsigned long length)
{
    (void)slot; (void)gen; (void)mode; (void)verdict; (void)ctx; (void)length;
    assert(!"completion mode emitted a shield verdict");
    return -1;
}

static uint64_t tracked_read(uint64_t dst, uint64_t size, uint64_t src,
                              uint64_t a4, uint64_t a5)
{
    reads++;
    return ls_h_probe_read(dst, size, src, a4, a5);
}

static void load(void *blob, size_t length)
{
    g_ls_config.loading = ls_config_new_instance(&g_ls_config, 1);
    assert(g_ls_config.loading != 0);
    assert(ls_vm_reload(1, blob, length, "fexit/snapshot/snapshot_victim",
                        "snapshot_probe", LS_MODE_MONITOR) == 1);
    g_ls_config.loading = 0;
    assert(!ubpf_register(g_slots[1].vm, 4, "tracked_read", tracked_read));
    assert((g_slots[1].jit_fn != NULL) == g_cfg.jit);
}

void cv_body(struct object *o, uint64_t event, uint64_t action,
              uint64_t depth, uint64_t serial)
{
    if (action != BAD_READ && o && !o->disabled && event == INIT) {
        memset(o, 0, sizeof *o);
        o->initialized = 1;
        writes++;
    }
    switch (action) {
    case DISABLE: o->disabled = 1; break;
    case ENABLE: o->disabled = 0; break;
    case NEST:
        o->disabled = !o->disabled;
        cv_target(o, event, PLAIN, 0, serial + 1);
        break;
    case RECURSE:
        if (depth) cv_target(o, event, RECURSE, depth - 1, serial + 1);
        break;
    case PROTECT:
        assert(o->initialized == 1);
        assert(!mprotect(o, page_size, PROT_NONE));
        break;
    case SKIP: longjmp(jump, 1);
    case OUTER_SKIP:
        if (!setjmp(jump)) cv_target(o, event, SKIP, 0, serial + 1);
        break;
    case RELOAD: load(replacement, replacement_len); break;
    case PAUSE:
        ls_vm_set_mode(1, LS_MODE_DISABLE);
        ls_vm_set_mode(1, LS_MODE_MONITOR);
        break;
    case RESTORE: g_slots[1].armed = true; break;
    case RESTORE_FUEL:
        ubpf_set_instruction_limit(g_slots[1].vm, 10000, NULL);
        break;
    default: break;
    }
}

static void reset(void)
{
    assert(g_ls_fexit_top == 0);
    ls_fexit_reset();
    memset(observations, 0, sizeof observations);
    count = writes = reads = 0;
}

static void check(unsigned index, uint64_t serial, unsigned known,
                   unsigned eligible, unsigned owner)
{
    assert(index < count);
    const struct snapshot_observation *o = &observations[index];
    assert(o->serial == serial && o->known == known);
    assert(o->eligible == eligible && o->owner == owner);
    assert(o->phase == LS_SNAPSHOT_RETURN && o->no_return == 0);
    assert(o->sequence != 0 && o->sequence != UINT64_MAX);
    assert(!known || (o->marker == owner && o->flags == LS_SNAPSHOT_CAPTURED));
}

static void *read_object(const char *path, size_t *length)
{
    FILE *file = fopen(path, "rb");
    assert(file && !fseek(file, 0, SEEK_END));
    long size = ftell(file);
    assert(size > 0 && !fseek(file, 0, SEEK_SET));
    void *data = malloc((size_t)size);
    assert(data && fread(data, 1, (size_t)size, file) == (size_t)size);
    assert(!fclose(file));
    *length = (size_t)size;
    return data;
}

int main(int argc, char **argv)
{
    assert(argc == 3);
    size_t initial_len = 0;
    void *initial = read_object(argv[1], &initial_len);
    replacement = read_object(argv[2], &replacement_len);
    page_size = (size_t)sysconf(_SC_PAGESIZE);
    assert(ls_vm_init());
    for (unsigned noise = 0; noise < 2; noise++) {
        struct object o = {0};
        load(initial, initial_len);
        cv_return_noise = noise ? UINT64_C(0xfedcba9876543210) : 0;
        reset(); cv_target(&o, INIT, PLAIN, 0, 1);
        check(0, 1, 1, 1, 1); assert(count == 1 && writes == 1 && reads == 1);

        reset(); o = (struct object){1, 0};
        cv_target(&o, INIT, ENABLE, 0, 2);
        check(0, 2, 1, 0, 1); assert(count == 1 && writes == 0);
        reset(); o = (struct object){0};
        cv_target(&o, INIT, DISABLE, 0, 3);
        check(0, 3, 1, 1, 1); assert(count == 1 && writes == 1);
        reset(); cv_target(NULL, INIT, PLAIN, 0, 4);
        check(0, 4, 1, 0, 1); assert(count == 1 && writes == 0 && reads == 0);
        reset(); o = (struct object){0};
        cv_target(&o, 2, PLAIN, 0, 5);
        check(0, 5, 1, 0, 1); assert(count == 1 && writes == 0);

        reset(); o = (struct object){0};
        cv_target(&o, INIT, NEST, 0, 6);
        check(0, 7, 1, 0, 1); check(1, 6, 1, 1, 1);
        assert(count == 2 && writes == 1 && reads == 2);
        assert(observations[0].sequence > observations[1].sequence);
        reset(); o = (struct object){0};
        cv_target(&o, INIT, RECURSE, 7, 8);
        assert(count == 8 && writes == 8 && reads == 8);
        for (unsigned i = 0; i < count; i++) check(i, 15 - i, 1, 1, 1);

        reset(); o = (struct object){0};
        for (unsigned i = 0; i < 20; i++) {
            o.disabled = i & 1;
            cv_target(&o, INIT, PLAIN, 0, i);
            check(i, i, 1, !(i & 1), 1);
        }
        assert(count == 20 && writes == 10 && reads == 20);
        reset();
        struct object *page = mmap(NULL, page_size, PROT_READ | PROT_WRITE,
                                   MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        assert(page != MAP_FAILED);
        cv_target(page, INIT, PROTECT, 0, 20);
        check(0, 20, 1, 1, 1); assert(count == 1 && reads == 1);
        assert(!munmap(page, page_size));

        reset(); o = (struct object){0};
        cv_target(&o, INIT, OUTER_SKIP, 0, 21);
        check(0, 21, 1, 1, 1);
        assert(count == 1 && writes == 2 && g_ls_fexit_reclaimed == 1);
        reset(); o = (struct object){0};
        cv_target(&o, INIT, RECURSE, DEPTH + 1, 22);
        assert(count == DEPTH && writes == DEPTH + 2 && reads == DEPTH);
        assert(g_ls_fexit_overflow == 2 && g_ls_fexit_desync == 0);
        for (unsigned i = 0; i < count; i++) check(i, 22 + DEPTH - 1 - i, 1, 1, 1);

        reset(); o = (struct object){0};
        cv_target(&o, INIT, OMIT, 0, 23);
        check(0, 23, 0, 0, 1); assert(count == 1 && writes == 1);
        reset(); cv_target((void *)1, INIT, BAD_READ, 0, 24);
        check(0, 24, 0, 0, 1); assert(count == 1 && writes == 0 && reads == 1);
        reset(); o = (struct object){0};
        cv_target(&o, INIT, SMASH, 0, 25);
        check(0, 25, 1, 1, 1);
        assert(observations[0].node == (uintptr_t)&o && observations[0].event == INIT);
        assert(writes == 1 && count == 1);

        reset(); o = (struct object){0};
        uint64_t rejected = g_slots[1].snapshot_return_errors;
        cv_target(&o, INIT, PAUSE, 0, 26);
        assert(count == 0 && writes == 1);
        assert(g_slots[1].snapshot_return_errors == rejected + 1);
        reset(); o = (struct object){0};
        uint64_t failed = g_slots[1].snapshot_entry_errors;
        g_slots[1].armed = false; /* Inject a missing VM at entry only. */
        cv_target(&o, INIT, RESTORE, 0, 27);
        check(0, 27, 0, 0, 1); assert(observations[0].flags == 0);
        assert(count == 1 && g_slots[1].snapshot_entry_errors == failed + 1);

        reset(); o = (struct object){0};
        rejected = g_slots[1].snapshot_return_errors;
        cv_target(&o, INIT, RELOAD, 0, 28);
        assert(count == 0 && writes == 1);
        assert(g_slots[1].snapshot_return_errors == rejected + 1);
        cv_target(&o, INIT, PLAIN, 0, 29);
        check(0, 29, 1, 1, 2); assert(count == 1);

        reset(); o = (struct object){0};
        g_ls_fexit_seq = UINT64_MAX;
        cv_target(&o, INIT, PLAIN, 0, 30);
        assert(count == 0 && writes == 1 && g_ls_fexit_overflow == 1);
        reset(); o = (struct object){0};
        g_slots[1].snapshot_id.epoch = UINT64_MAX;
        cv_target(&o, INIT, PLAIN, 0, 31);
        assert(count == 0 && writes == 1);
        load(initial, initial_len);
        if (!g_cfg.jit) {
            reset(); o = (struct object){0};
            failed = g_slots[1].snapshot_entry_errors;
            ubpf_set_instruction_limit(g_slots[1].vm, 8, NULL);
            cv_target(&o, INIT, RESTORE_FUEL, 0, 32);
            check(0, 32, 0, 0, 1); assert(observations[0].flags == 0);
            assert(count == 1 && g_slots[1].snapshot_entry_errors == failed + 1);
        }
        assert(g_ls_fexit_top == 0 && g_ls_fexit_desync == 0);
        assert(g_slots[1].safe_returns == 0);
        printf("PASS snapshot jit=%d noise=%u cases=%u\n",
               g_cfg.jit, noise, g_cfg.jit ? 19 : 20);
    }
    ls_vm_fini();
    free(initial); free(replacement);
    return 0;
}

