exit_admit.py.text:
#!/usr/bin/env python3
"""exit_admit.py --- the admission gate for a function-EXIT (fexit) hook.

Arming an exit hook does two things an entry hook does not: it READS the return
value, and it HIJACKS the return address. Each imposes a requirement on the target
function, and both are checkable offline from the build's own binary --- so they
are gates, not hopes. This tool answers, for one function on one build:

  #5  Is the return type rax-representable?  The exit stub captures rax(:rdx). A
      float/double is returned in xmm0, and a by-value struct via a hidden pointer
      (or in memory) --- in neither case is rax "the value", so a program reading
      c->ret would get garbage. Admit only integer/enum/pointer/bool returns
      (rdx:rax for a <=16-byte integer pair). Refuse float, by-value struct/union,
      and void (nothing to read).

  #4  Can a non-local exit unwind THROUGH the frame?  The return-address hijack
      corrupts a stack unwind that walks the frame. TMM initiates no unwind ---
      P8, verified on the build box: zero _Unwind_* / __cxa_* imports --- so no TMM
      frame can sit on a completed throw->catch chain. This RE-CHECKS that property
      against the actual runtime binary. If it ever fails (TMM gains C++ exception
      handling), exit hooks are refused wholesale, because the empty-exclusion-set
      argument no longer holds and a real per-target reachability analysis is owed.

Usage:
    exit_admit.py <debug-binary> <runtime-binary> <function>

Exit status: 0 = ADMIT, 1 = REFUSE (reasons on stderr), 2 = could not decide
(missing tool / symbol) --- which is also a refusal, because an exit hook admitted
on an undecided target is exactly the failure this gate exists to prevent.
"""
import re
import subprocess
import sys

UNWIND_INITIATORS = (
    "_Unwind_RaiseException", "_Unwind_ForcedUnwind", "_Unwind_Resume",
    "__cxa_throw", "__cxa_begin_catch", "__cxa_rethrow",
)

DWARFDUMP = ("llvm-dwarfdump", "/usr/lib/llvm-18/bin/llvm-dwarfdump", "llvm-dwarfdump-18")


class _Miss:
    returncode = 127
    stdout = ""
    stderr = ""


def sh(*argv):
    """Run a command; a missing executable is a non-zero result, not an exception."""
    try:
        return subprocess.run(argv, capture_output=True, text=True)
    except (FileNotFoundError, OSError):
        return _Miss()


def which_dwarfdump():
    for d in DWARFDUMP:
        if sh(d, "--version").returncode == 0:
            return d
    return None


def func_addr(debug_bin, fn):
    """The function's load address, from the (unstripped) debug companion's symtab."""
    r = sh("nm", debug_bin)
    for line in r.stdout.splitlines():
        p = line.split()
        if len(p) == 3 and p[2] == fn and p[1] in ("T", "t", "W", "w"):
            try:
                return int(p[0], 16)
            except ValueError:
                return None
    return None


def frame_has_lsda(runtime_bin, addr):
    """(has_lsda, decided) --- does the .eh_frame FDE covering `addr` carry a C++
    exception LSDA (a cleanup/landing-pad site the unwinder would process)? An
    unwind through such a frame is exactly what the return-address hijack corrupts.
    Only a handful of frames have one (the C++ TUs); a plain C data-path function
    does not. `decided` is False if the tool is unavailable."""
    dd = which_dwarfdump()
    if dd is None or addr is None:
        return (False, False)
    r = sh(dd, "--eh-frame", runtime_bin)
    lo = hi = None
    cur_lsda = False
    fde = re.compile(r"FDE .*pc=([0-9a-f]+)\.\.\.([0-9a-f]+)")
    for line in r.stdout.splitlines():
        m = fde.search(line)
        if m:
            if lo is not None and lo <= addr < hi:
                return (cur_lsda, True)          # the FDE that covers addr closed
            lo, hi = int(m.group(1), 16), int(m.group(2), 16)
            cur_lsda = False
        elif "LSDA Address" in line:
            cur_lsda = True
    if lo is not None and lo <= addr < hi:
        return (cur_lsda, True)
    return (False, True)   # no FDE covers addr -> no unwind info -> nothing to traverse


def return_type(debug_bin, fn):
    """The function's declared return type, via the build's DWARF. Returns the
    type string, or None if gdb or the symbol is unavailable."""
    r = sh("gdb", "-q", "-batch", "-ex", "ptype %s" % fn, debug_bin)
    for line in r.stdout.splitlines():
        line = line.strip()
        if not line.startswith("type = "):
            continue
        body = line[len("type = "):]
        # "type = <ret> (<params>)"  --- the parameter list is the LAST top-level
        # "(...)"; everything before it is the return type. enum {...} and struct
        # names carry no parens, so rsplit on the last " (" is safe here.
        if " (" in body:
            body = body.rsplit(" (", 1)[0]
        return body.strip()
    return None


def classify_return(t):
    """(safe: bool, reason: str) for a return-type string."""
    if t is None:
        return False, "return type could not be read from DWARF"
    ts = t.strip()
    if ts.endswith("*"):
        return True, "pointer (in rax)"
    if ts == "void":
        return False, "void return --- there is no value for the exit program to read"
    if ts.startswith(("float", "double", "long double", "_Float", "__float")):
        return False, "floating-point return (xmm0, NOT rax) --- c->ret would be garbage"
    if ts.startswith(("struct ", "union ", "class ")):
        return False, ("by-value %s return (hidden pointer / memory, NOT the value) --- "
                       "refused conservatively" % ts.split()[0])
    # integer family, enums, bool
    if ts.startswith(("enum", "int", "unsigned", "char", "short", "long",
                      "signed", "_Bool", "bool", "uint", "u_int", "size_t",
                      "ssize_t", "int8", "int16", "int32", "int64",
                      "uint8", "uint16", "uint32", "uint64")):
        return True, "%s (rax)" % (ts if len(ts) < 40 else ts[:37] + "...")
    return False, "unrecognised return type %r --- refused conservatively" % ts


def unwind_clear(runtime_bin):
    """(clear: bool, found: list) --- P8: the binary must import no unwind
    initiator. Reads .dynsym for UND symbols."""
    r = sh("readelf", "--dyn-syms", runtime_bin)
    found = []
    for line in r.stdout.splitlines():
        if " UND " not in line:
            continue
        for s in UNWIND_INITIATORS:
            # match the bare symbol (may carry an @GLIBC version suffix)
            if re.search(r"\b%s\b" % re.escape(s), line):
                found.append(s)
    return (len(found) == 0), sorted(set(found))


def main(argv):
    if len(argv) != 4:
        sys.stderr.write(__doc__)
        return 2
    debug_bin, runtime_bin, fn = argv[1], argv[2], argv[3]

    rt = return_type(debug_bin, fn)
    safe_ret, why_ret = classify_return(rt)

    clear, found = unwind_clear(runtime_bin)                       # #4a binary-wide (P8)
    addr = func_addr(debug_bin, fn)
    lsda, lsda_decided = frame_has_lsda(runtime_bin, addr)         # #4b per-target

    print("exit-admit: %s" % fn)
    print("  #5 return type : %s --- %s" % (rt if rt else "?", why_ret))
    if clear:
        print("  #4a unwind     : clear --- TMM imports no unwind initiator (P8 holds)")
    else:
        print("  #4a unwind     : VIOLATED --- binary imports %s" % ", ".join(found))
    if not lsda_decided:
        print("  #4b frame      : UNCHECKED --- no llvm-dwarfdump; per-target LSDA not verified")
    elif lsda:
        print("  #4b frame      : has a C++ exception LSDA --- an unwind would process this frame")
    else:
        print("  #4b frame      : no LSDA --- plain frame, nothing for an unwind to process here")

    safe_unwind = clear and not lsda
    ok = safe_ret and safe_unwind
    if ok:
        print("  VERDICT        : ADMIT")
        return 0

    if not safe_ret:
        sys.stderr.write("*** REFUSE %s: %s\n" % (fn, why_ret))
    if not clear:
        sys.stderr.write("*** REFUSE %s: TMM now initiates unwinds (%s); the empty-exclusion-set\n"
                         "    argument (P8) no longer holds. A per-target unwind-reachability\n"
                         "    analysis is owed before any exit hook is admitted.\n"
                         % ", ".join(found))
    if lsda:
        sys.stderr.write("*** REFUSE %s: the target frame carries a C++ exception landing pad\n"
                         "    (LSDA); a stack unwind would process it, and the return-address\n"
                         "    hijack corrupts an unwind that walks the frame.\n" % fn)
    print("  VERDICT        : REFUSE")
    return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))

ls_arm.h.text:
/* ls_arm.h --- patched-entry hooking: arm/disarm a LIVE function.
 *
 * Live-SURFACE mechanics. `ls_` is the live surface embedded in the data
 * plane; these primitives are used by ANY consumer of it (CVE shielding is
 * consumer #1, with observability, steering and self-tuning as peers), which
 * is why this header is not named for the shield.
 *
 * The point of this mechanism is that arming happens while TMM is RUNNING and
 * traffic is flowing --- no rebuild, no restart. That is what makes a shield
 * "live". Arming at startup would need a restart and would defeat the purpose,
 * so the write goes through ls_swap_write5(), the kernel-proven text_poke_bp
 * protocol, which is safe against other cores executing the same bytes.
 */
#ifndef LS_ARM_H
#define LS_ARM_H
#include <stdint.h>

struct ls_tramp_result { int verdict; uint64_t safe_value; };

/*
 * The hooked function's saved argument registers, as the trampoline pushed them.
 *
 * ORDER IS THE STACK'S, NOT THE ABI'S. The trampoline pushes rdi,rsi,rdx,rcx,r8,r9
 * then rax,r10,r11, so in memory they appear in REVERSE: r11 lowest, rdi highest.
 * The layout below matches the stack exactly and the asm passes a pointer to it;
 * getting this backwards does not crash, it silently swaps arguments, which the
 * trampoline's own comments record as having happened once already.
 *
 * A POINTER RATHER THAN SIX VALUES, deliberately. rdi carries the slot, leaving five
 * registers for arguments, so a sixth would have landed on the stack --- and
 * rst_cause is the sixth. Passing the block means all six arrive and no future
 * signature change touches the assembly again.
 */
struct ls_regs {
    uint64_t r11;               /* +0   scratch, saved for safety           */
    uint64_t r10;               /* +8   scratch, saved for safety           */
    uint64_t rax;               /* +16  varargs vector count; unused here   */
    uint64_t r9;                /* +24  arg5  <-- rst_cause lives here      */
    uint64_t r8;                /* +32  arg4                                */
    uint64_t rcx;               /* +40  arg3                                */
    uint64_t rdx;               /* +48  arg2                                */
    uint64_t rsi;               /* +56  arg1                                */
    uint64_t rdi;               /* +64  arg0                                */
};

/* Named accessors, so no call site indexes the block by ABI position and gets the
 * reversal wrong. */
#define LS_ARG0(r) ((r)->rdi)
#define LS_ARG1(r) ((r)->rsi)
#define LS_ARG2(r) ((r)->rdx)
#define LS_ARG3(r) ((r)->rcx)
#define LS_ARG4(r) ((r)->r8)
#define LS_ARG5(r) ((r)->r9)

struct ls_tramp_result ls_tramp_dispatch(int slot, const struct ls_regs *regs);

/* single-writer forms (no concurrent executor; used only off the live path) */
int ls_arm(void *fn, void *trampoline);
int ls_disarm(void *fn);

/* LIVE forms --- safe while other cores are executing the target */
int ls_arm_live(void *fn, void *trampoline, int slot, int is_exit);
int ls_disarm_live(void *fn);

/* the safe swap: rewrite 5 bytes of executed code under contention */
int  ls_swap_write5(uint8_t *pad, const uint8_t bytes[5]);
void ls_swap_trap_install(void);
#endif

ls_build_gate.h.text:
/* ls_build_gate.h --- refuse a program signed for a different build.
 *
 * WHY THIS EXISTS. `struct shield_binding` has carried build_min, build_max and
 * expires_with since the ABI was written. They are covered by the signature ---
 * check_sig.c asserts a flipped bit in each IS detected --- and they are written
 * into every audit record. And until this file, nothing compared them to
 * anything. `grep -rn 'build_min' *.c *.h` outside shield_abi.h returned two
 * tests and the logger. See CONTESTED-PREMISES.md 15.
 *
 * That is the most expensive shape a gap can take: three separate trails (the
 * signed structure, a passing tamper test, the audit record) all read as
 * "enforced". SIGNING A FIELD IS NOT CHECKING IT, and a test that a field is
 * signed is not a test that it is honoured.
 *
 * WHY IT MATTERS MORE NOW. Removing the embedded `.BTF` (02-RESEARCH-PARAMETERS.md
 * P9) means field offsets get baked on the build box instead of resolved on-box
 * against the running binary's own type information. That deletes the property
 * which currently makes a stale offset structurally impossible. Baked offsets
 * plus an unenforced build range is silently-wrong reads with nothing able to
 * notice --- so this gate lands BEFORE that change, not after.
 *
 * THE ENCODING, DEFINED HERE BECAUSE IT WAS NEVER DEFINED ANYWHERE.
 * shield_abi.h called the field an "encoded build id" and no file said what the
 * encoding was. It is the FIRST FOUR BYTES of the GNU build id read as a
 * big-endian uint32 --- so build 269b5d25ad5d... is 0x269b5d25, which is the
 * convention already used by hand on the command line.
 *
 * AND WHY A "RANGE" IS ALMOST ALWAYS WRONG. A GNU build id is a SHA-1. A hash has
 * no ordering, so "builds 0x100 through 0x200" is not a statement about builds ---
 * it is an accident that admits roughly 2^-32 of all builds for no stated reason.
 * Only two forms mean anything, and everything else is refused rather than
 * silently accepted:
 *
 *   min == max                 this build, and no other
 *   0 .. 0xffffffff            ANY build --- the explicit wildcard
 *
 * The wildcard is accepted and logged LOUDLY. It has to be: sign_shield.py has
 * defaulted to it since it was written and bnk-build-programs.sh passes no range
 * at all, so every program ever signed by the pipeline carries it. Refusing it
 * would brick every existing artifact to prove a point. It is not an attacker
 * escape --- the range is inside the signature, so only our own key can assert
 * it --- it is us vouching too broadly, which is a pipeline fix (pass the range)
 * rather than a loader fix.
 *
 * expires_with IS DELIBERATELY NOT CHECKED HERE. Its semantics were never
 * defined either, and unlike build_min/build_max there is no reading that is
 * obviously right: "expires with build X" cannot be evaluated on a box that does
 * not know which build superseded X, and a uint32 epoch would be a different
 * field. Inventing a meaning and then enforcing it is worse than a documented
 * gap, so it stays a gap, logged, with the decision pre-registered in P9.
 *
 * Header-only and free of every TMM dependency on purpose: the decision is a pure
 * function of three integers and a string, so check_build_gate.c can assert every
 * branch of it off-TMM without a socket, a thread or a binary.
 */
#ifndef LS_BUILD_GATE_H
#define LS_BUILD_GATE_H

#include <stdint.h>

enum ls_build_verdict {
    LS_BUILD_OK = 0,       /* min == max and it matches the running build       */
    LS_BUILD_WILDCARD,     /* 0..0xffffffff --- accepted, must be logged loudly */
    LS_BUILD_UNDECLARED,   /* 0..0 --- the field was never set; see below       */
    LS_BUILD_MISMATCH,     /* signed for exactly one build, and not this one    */
    LS_BUILD_BAD_RANGE,    /* a range over a hash: meaningless, so refused      */
    LS_BUILD_NO_ID         /* the running build id is unreadable --- fail closed */
};

/* AN ALL-ZERO RANGE IS "UNDECLARED", NOT "BUILD ZERO", AND GETTING THIS WRONG
 * WOULD HAVE BRICKED THE LOADER. ls_client.py builds its message as
 * `bytearray(HDR)` and sets only op, epoch, mode, prog_len and hook --- so every
 * request from the real client carries build_min = build_max = 0. Read literally
 * that is min == max, which is the "exactly one build" form, and it mismatches
 * every real build id. The first version of this header did read it literally and
 * would have refused every load, arm, status and disarm the moment it shipped.
 *
 * It is the same transition case ls_vm_load.c already handles for
 * ctx_abi_version == 0, for the same reason and with the same remedy: accept, log
 * so the silence is visible, and remove the acceptance once every client sets the
 * field. A build id of exactly 0x00000000 is not a real risk to distinguish ---
 * it is one value out of 2^32 in a SHA-1 prefix --- and if it ever occurs the
 * program is admitted rather than refused, which is the safe direction for a
 * transition measure.
 *   TODO(f5): make 0..0 a refusal once ls_client.py sets the range. */

#define LS_BUILD_WILDCARD_MIN 0x00000000u
#define LS_BUILD_WILDCARD_MAX 0xffffffffu

static inline const char *
ls_build_strerror(enum ls_build_verdict v)
{
    switch (v) {
    case LS_BUILD_OK:        return "signed for this build";
    case LS_BUILD_WILDCARD:  return "signed for ANY build";
    case LS_BUILD_UNDECLARED:return "no build range declared";
    case LS_BUILD_MISMATCH:  return "signed for a different build";
    case LS_BUILD_BAD_RANGE: return "build range spans a hash and cannot be honoured";
    case LS_BUILD_NO_ID:     return "this binary's build id is unreadable";
    }
    return "unknown";
}

/* First four bytes of a lowercase-hex GNU build id, big-endian.
 * Returns 0 on any malformed input and sets *ok = 0 --- a build id shorter than
 * 8 hex digits, or carrying a non-hex character, is not a build id, and guessing
 * at one is how a gate ends up admitting whatever it could not parse. */
static inline uint32_t
ls_build_prefix(const char *hex, int *ok)
{
    uint32_t v = 0;
    if (ok) *ok = 0;
    if (hex == 0)
        return 0;
    for (int i = 0; i < 8; i++) {
        char c = hex[i];
        uint32_t d;
        if      (c >= '0' && c <= '9') d = (uint32_t)(c - '0');
        else if (c >= 'a' && c <= 'f') d = (uint32_t)(c - 'a' + 10);
        else if (c >= 'A' && c <= 'F') d = (uint32_t)(c - 'A' + 10);
        else return 0;                       /* short or non-hex: refuse */
        v = (v << 4) | d;
    }
    if (ok) *ok = 1;
    return v;
}

/* THE DECISION. `running_hex` is this binary's build id as hex (ls_audit_build_id()).
 * On a non-NULL `running_out` the parsed prefix is stored for logging, whatever the
 * verdict --- a refusal that cannot say which build it is running is hard to act on. */
static inline enum ls_build_verdict
ls_build_gate(const char *running_hex, uint32_t bmin, uint32_t bmax,
              uint32_t *running_out)
{
    int ok = 0;
    uint32_t running = ls_build_prefix(running_hex, &ok);
    if (running_out) *running_out = running;

    /* The wildcard is decided BEFORE the id is required. A program vouched for on
     * any build does not become invalid because this binary's note is unreadable,
     * and ordering it the other way would have made the gate's arrival break loads
     * on any binary whose build id we cannot parse. */
    if (bmin == LS_BUILD_WILDCARD_MIN && bmax == LS_BUILD_WILDCARD_MAX)
        return LS_BUILD_WILDCARD;
    if (bmin == 0u && bmax == 0u)
        return LS_BUILD_UNDECLARED;      /* every ls_client.py message --- see above */

    if (!ok)
        return LS_BUILD_NO_ID;               /* fail closed once a range is asserted */
    if (bmin != bmax)
        return LS_BUILD_BAD_RANGE;
    return (running == bmin) ? LS_BUILD_OK : LS_BUILD_MISMATCH;
}

/* ---- EXPIRY -----------------------------------------------------------------
 *
 * Same family as the build gate and in the same header for that reason: both are
 * pure decisions about the signed binding, and both were fields that existed,
 * were signed, were logged, and were read by nothing.
 *
 * WHY IT FAILS **OPEN** ON A CLOCK IT CANNOT TRUST, which is the opposite of the
 * build gate and is a deliberate asymmetry. A shield exists to stop a crash. If
 * the box's clock is wrong, refusing the shield converts a clock problem into an
 * outage, and the thing it was protecting against happens instead. A wrong build
 * is a correctness error and must refuse; a wrong clock is an environment error
 * and must not. So an implausible clock is accepted and logged loudly.
 *
 * "Implausible" is anything before LS_EPOCH_SANE --- 2020-01-01. A container that
 * starts before NTP has run reads 1970, and that is the case this exists for.
 */
enum ls_expiry_verdict {
    LS_EXPIRY_OK = 0,      /* a deadline is set and has not been reached        */
    LS_EXPIRY_NEVER,       /* 0 or ~0 --- no deadline was declared             */
    LS_EXPIRY_UNKNOWN,     /* the clock is implausible --- accepted, logged     */
    LS_EXPIRY_EXPIRED      /* the deadline has passed --- REFUSE               */
};

#define LS_EPOCH_SANE 1577836800u   /* 2020-01-01T00:00:00Z */

static inline const char *
ls_expiry_strerror(enum ls_expiry_verdict v)
{
    switch (v) {
    case LS_EXPIRY_OK:      return "within its validity window";
    case LS_EXPIRY_NEVER:   return "no expiry declared";
    case LS_EXPIRY_UNKNOWN: return "this box's clock is implausible, so expiry could not be judged";
    case LS_EXPIRY_EXPIRED: return "this program has expired";
    }
    return "unknown";
}

/* `now` is seconds since the Unix epoch, UTC --- time(NULL) at the call site, passed
 * in rather than read here so the decision stays pure and testable. */
static inline enum ls_expiry_verdict
ls_expiry_gate(uint32_t expires_with, uint64_t now)
{
    if (expires_with == 0u || expires_with == 0xffffffffu)
        return LS_EXPIRY_NEVER;
    if (now < (uint64_t)LS_EPOCH_SANE)
        return LS_EXPIRY_UNKNOWN;
    return (now >= (uint64_t)expires_with) ? LS_EXPIRY_EXPIRED : LS_EXPIRY_OK;
}

#endif /* LS_BUILD_GATE_H */

ls_config.h.text:
/* ls_config.h -- bounded controller input, independent of mutable hash maps.
 * Single serialized control writer; readers make ONE attempt, never spin.
 * Atomic payload words are essential: a seqlock around ordinary memcpy would
 * still be a C data race. Sequential consistency gives the copy/check protocol
 * one total order. This is deliberately conservative until measured on TMM.
 */
#ifndef LS_CONFIG_H
#define LS_CONFIG_H
#include <stdatomic.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#if __BYTE_ORDER__ != __ORDER_LITTLE_ENDIAN__
#error "configuration wire ABI v1 requires a little-endian host"
#endif

#define LS_CONFIG_ABI 1u
#define LS_CONFIG_SLOTS 64u
#define LS_CONFIG_ROWS 16u
#define LS_CONFIG_VALUE_SIZE 32u
#define LS_CONFIG_MAP_NAME "ls_config_v1"
#define LS_CONFIG_MAP_FLAG 128u /* BPF_F_RDONLY_PROG; host image never exposed */
#define LS_CONFIG_HANDLE_BIT (UINT64_C(1) << 63)

struct ls_config_meta {
    uint64_t revision;
    uint64_t instance;
    uint32_t schema;
    uint32_t entries;
    uint64_t reserved;
};
struct ls_config_image {
    struct ls_config_meta meta; /* array index 0; data occupy indices 1..entries */
    uint8_t rows[LS_CONFIG_ROWS][LS_CONFIG_VALUE_SIZE];
};
#define LS_CONFIG_WORDS (sizeof(struct ls_config_image) / sizeof(uint64_t))
_Static_assert(sizeof(struct ls_config_meta) == 32, "config metadata ABI");
_Static_assert(sizeof(struct ls_config_image) == 544, "config image ABI");
_Static_assert(ATOMIC_LLONG_LOCK_FREE == 2, "config requires lock-free 64-bit atomics");

/* Little-endian wire body in shield_msg.prog, CONFIG_PUBLISH only. */
struct ls_config_request {
    uint32_t abi, schema;
    uint64_t session, instance, expected_revision, revision;
    uint32_t entries, reserved;
    uint8_t program_sha256[32];
    uint8_t rows[LS_CONFIG_ROWS][LS_CONFIG_VALUE_SIZE];
};
#define LS_CONFIG_REQUEST_HEADER 80u
_Static_assert(offsetof(struct ls_config_request, rows) == LS_CONFIG_REQUEST_HEADER,
               "config request ABI");

struct ls_config_slot {
    _Atomic uint64_t sequence;
    _Atomic uint64_t words[LS_CONFIG_WORDS];
    /* Control-plane only. Never read by a program or a data-path thread. */
    struct ls_config_meta current;
    uint8_t program_sha256[32];
};
struct ls_config_store {
    uint64_t session, next_instance; /* serialized load/publish control path */
    uint64_t loading;               /* relocation cookie for VM being prepared */
    int load_error;
    struct ls_config_slot slots[LS_CONFIG_SLOTS];
};
struct ls_config_view {
    int active, attempted, available;
    unsigned slot;
    uint64_t handle;
    struct ls_config_image image; /* program-writable, invocation-private copy */
};

static inline uint64_t
ls_config_new_instance(struct ls_config_store *s, unsigned slot)
{
    if (slot >= LS_CONFIG_SLOTS || s->next_instance >= (LS_CONFIG_HANDLE_BIT >> 6) - 1)
        return 0;
    return LS_CONFIG_HANDLE_BIT | (++s->next_instance << 6) | slot;
}

static inline int
ls_config_write(struct ls_config_slot *s, const struct ls_config_image *image)
{
    uint64_t seq = atomic_load(&s->sequence);
    if ((seq & 1) || seq > UINT64_MAX - 2)
        return -1;
    atomic_store(&s->sequence, seq + 1);
    for (size_t i = 0; i < LS_CONFIG_WORDS; i++) {
        uint64_t word;
        memcpy(&word, (const uint8_t *)image + i * 8, 8);
        atomic_store(&s->words[i], word);
    }
    atomic_store(&s->sequence, seq + 2);
    s->current = image->meta;
    return 0;
}

/* Called after successful load; token was embedded in that VM's map relocation.
 * In-flight old bytecode retains its old token, so cannot read the new image. */
static inline int
ls_config_bind(struct ls_config_store *s, unsigned slot, uint64_t instance,
               const uint8_t sha[32])
{
    struct ls_config_image empty = {0};
    if (slot >= LS_CONFIG_SLOTS || !(instance & LS_CONFIG_HANDLE_BIT) ||
        (instance & 63) != slot)
        return -1;
    empty.meta.instance = instance;
    if (ls_config_write(&s->slots[slot], &empty) != 0)
        return -1;
    memcpy(s->slots[slot].program_sha256, sha, 32);
    return 0;
}

static inline int
ls_config_revoke(struct ls_config_store *s, unsigned slot)
{
    struct ls_config_image empty = {0};
    if (slot >= LS_CONFIG_SLOTS)
        return -1;
    return ls_config_write(&s->slots[slot], &empty);
}

/* NULL means published. Errors never modify the previous image. A zero-row
 * publication is an explicit empty configuration, not a reset of revision. */
static inline const char *
ls_config_publish(struct ls_config_store *s, unsigned slot, const void *body, size_t len)
{
    struct ls_config_request r = {0};
    struct ls_config_image image = {0};
    if (slot >= LS_CONFIG_SLOTS || !body || len < LS_CONFIG_REQUEST_HEADER || len > sizeof r)
        return "config length or slot";
    memcpy(&r, body, len);
    if (r.abi != LS_CONFIG_ABI || r.reserved || !r.schema || r.entries > LS_CONFIG_ROWS ||
        len != LS_CONFIG_REQUEST_HEADER + r.entries * LS_CONFIG_VALUE_SIZE)
        return "config ABI, schema, reserved, or shape";
    struct ls_config_slot *dst = &s->slots[slot];
    if (!s->session || r.session != s->session)
        return "config session mismatch";
    if (!dst->current.instance || r.instance != dst->current.instance ||
        memcmp(r.program_sha256, dst->program_sha256, 32))
        return "config program instance/hash mismatch";
    if (r.expected_revision != dst->current.revision || r.revision <= r.expected_revision)
        return "config revision conflict";
    image.meta.instance = r.instance;
    image.meta.revision = r.revision;
    image.meta.schema = r.schema;
    image.meta.entries = r.entries;
    memcpy(image.rows, r.rows, r.entries * LS_CONFIG_VALUE_SIZE);
    return ls_config_write(dst, &image) == 0 ? NULL : "config sequence exhausted";
}

static inline void
ls_config_begin(struct ls_config_view *v, unsigned slot)
{
    v->active = 1;
    v->slot = slot;
    v->attempted = v->available = 0;
    v->handle = 0;
}

static inline void *
ls_config_lookup(struct ls_config_store *s, struct ls_config_view *v,
                 uint64_t handle, uint32_t key)
{
    if (!v->active || !(handle & LS_CONFIG_HANDLE_BIT) ||
        v->slot >= LS_CONFIG_SLOTS || (handle & 63) != v->slot || key > LS_CONFIG_ROWS)
        return NULL;
    if (!v->attempted) {
        v->attempted = 1;
        v->handle = handle;
        struct ls_config_slot *src = &s->slots[v->slot];
        uint64_t before = atomic_load(&src->sequence);
        if (before & 1)
            return NULL;
        for (size_t i = 0; i < LS_CONFIG_WORDS; i++) {
            uint64_t word = atomic_load(&src->words[i]);
            memcpy((uint8_t *)&v->image + i * 8, &word, 8);
        }
        if (before != atomic_load(&src->sequence) || v->image.meta.instance != handle ||
            !v->image.meta.revision)
            return NULL;
        v->available = 1;
    }
    if (!v->available || handle != v->handle || key > v->image.meta.entries)
        return NULL;
    return (uint8_t *)&v->image + key * LS_CONFIG_VALUE_SIZE;
}

static inline int
ls_config_addr_ok(const struct ls_config_view *v, uint64_t addr, uint64_t size)
{
    uint64_t base = (uint64_t)(uintptr_t)&v->image;
    /* Use the fixed allocation bound, not program-writable metadata. */
    return v->active && v->available && addr >= base && addr - base < sizeof v->image &&
           size <= LS_CONFIG_VALUE_SIZE - ((addr - base) % LS_CONFIG_VALUE_SIZE);
}
#endif

ls_core_relo.c.text:
/* ls_core_relo.c --- CO-RE field-offset relocation, no libbpf/kernel deps.
 *
 * A portable program names TMM fields by struct+field NAME and carries .BTF +
 * .BTF.ext relocation records. ls_core_relocate() resolves each field's byte
 * offset against THIS build's BTF and patches the instruction immediate, so one
 * bytecode runs on any build with no baked offsets and no rebuild.
 *
 * Scope: kind=0 FIELD_BYTE_OFFSET, the only kind our compiler emits for
 * preserve_access_index field reads. Every other kind is rejected (fail-dark):
 * the caller MUST refuse to load on a non-zero return.
 *
 * ALL input here is untrusted-ish (a program handed over a socket, in a security
 * appliance), so every ELF/BTF/.BTF.ext offset is bounds-checked against the
 * buffer before use. Reads are byte-assembled (RD16/32/64) --- no unaligned casts.
 *
 * BTF and .BTF.ext binary layout per kernel Documentation/bpf/btf.rst.
 */
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include "ls_core_relo.h"

/* ---- BTF on-disk ---- */
enum { BTF_MAGIC = 0xeB9F };
enum { KIND_INT=1,KIND_PTR=2,KIND_ARRAY=3,KIND_STRUCT=4,KIND_UNION=5,KIND_ENUM=6,
       KIND_FWD=7,KIND_TYPEDEF=8,KIND_VOLATILE=9,KIND_CONST=10,KIND_RESTRICT=11,
       KIND_FUNC=12,KIND_FUNC_PROTO=13,KIND_VAR=14,KIND_DATASEC=15,KIND_FLOAT=16,
       KIND_DECL_TAG=17,KIND_TYPE_TAG=18,KIND_ENUM64=19 };

struct btf_hdr { uint16_t magic; uint8_t version; uint8_t flags; uint32_t hdr_len;
                 uint32_t type_off, type_len, str_off, str_len; };
struct btf_type { uint32_t name_off; uint32_t info; uint32_t size_or_type; };
struct btf_member { uint32_t name_off; uint32_t type; uint32_t offset; };

#define KIND(t)      (((t)->info >> 24) & 0x1f)
#define VLEN(t)      ((t)->info & 0xffff)
#define KFLAG(t)     (((t)->info >> 31) & 1)

/* little-endian byte-assembled reads (BTF/ELF are LE) --- alignment-safe */
static uint16_t rd16(const uint8_t *p){ return (uint16_t)(p[0]|(p[1]<<8)); }
static uint32_t rd32(const uint8_t *p){ return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24); }
static uint64_t rd64(const uint8_t *p){ return (uint64_t)rd32(p)|((uint64_t)rd32(p+4)<<32); }

static const char *btf_str(const struct btf *b, uint32_t off) {
    return off < b->strs_len ? b->strs + off : "";
}
static const struct btf_type *btf_type_by_id(const struct btf *b, uint32_t id) {
    if (id == 0 || id >= b->nids) return NULL;
    return (const struct btf_type *)(b->types + b->idx[id]);
}
/* bytes of kind-specific trailing data after the 12-byte btf_type header */
static uint32_t btf_trailing(const struct btf_type *t) {
    switch (KIND(t)) {
    case KIND_INT: case KIND_VAR: case KIND_DECL_TAG: return 4;
    case KIND_ARRAY: return 12;
    case KIND_STRUCT: case KIND_UNION: return VLEN(t) * 12;
    case KIND_ENUM:      return VLEN(t) * 8;
    case KIND_ENUM64:    return VLEN(t) * 12;
    case KIND_FUNC_PROTO:return VLEN(t) * 8;
    case KIND_DATASEC:   return VLEN(t) * 12;
    default: return 0;
    }
}
/* build the id->offset index by walking the type section once, bounded by types_len */
static int btf_index(struct btf *b) {
    uint32_t cap = 1024, n = 1, off = 0;   /* id 0 reserved for void */
    b->idx = malloc(cap * sizeof(uint32_t));
    if (!b->idx) return -1;
    b->idx[0] = 0;
    while (off + sizeof(struct btf_type) <= b->types_len) {
        const struct btf_type *t = (const struct btf_type *)(b->types + off);
        uint32_t trail = btf_trailing(t);
        if (off + sizeof(struct btf_type) + trail > b->types_len) break;  /* truncated tail */
        if (n == cap) {
            uint32_t ncap = cap * 2;
            uint32_t *ni = realloc(b->idx, ncap * sizeof(uint32_t));
            if (!ni) return -1;
            b->idx = ni; cap = ncap;
        }
        b->idx[n++] = off;
        off += sizeof(struct btf_type) + trail;
    }
    b->nids = n;
    return 0;
}
int ls_core_btf_open(struct btf *b, const uint8_t *blob, uint32_t len) {
    memset(b, 0, sizeof *b);
    if (len < sizeof(struct btf_hdr)) return -1;
    uint16_t magic = rd16(blob);
    uint32_t hdr_len  = rd32(blob + 4);
    uint32_t type_off = rd32(blob + 8),  type_len = rd32(blob + 12);
    uint32_t str_off  = rd32(blob + 16), str_len  = rd32(blob + 20);
    if (magic != BTF_MAGIC) return -1;
    /* every span must lie wholly inside the blob (guard against overflow too) */
    if (hdr_len > len) return -1;
    if ((uint64_t)hdr_len + type_off + type_len > len) return -1;
    if ((uint64_t)hdr_len + str_off  + str_len  > len) return -1;
    b->types = blob + hdr_len + type_off; b->types_len = type_len;
    b->strs  = (const char *)(blob + hdr_len + str_off); b->strs_len = str_len;
    return btf_index(b);
}
void ls_core_btf_free(struct btf *b) { if (b && b->idx) { free(b->idx); b->idx = NULL; b->nids = 0; } }

/* Find the `.BTF` ELF section span, bounds-checked against elf_len. */
int ls_core_btf_find_in_elf(const uint8_t *elf, uint32_t elf_len,
                            const uint8_t **btf, uint32_t *btf_sz) {
    if (elf_len < 64) return -1;
    uint64_t shoff = rd64(elf + 0x28);
    uint16_t shentsize = rd16(elf + 0x3a), shnum = rd16(elf + 0x3c), shstrndx = rd16(elf + 0x3e);
    if (shentsize < 64 || shnum == 0 || shstrndx >= shnum) return -1;
    if (shoff > elf_len || (uint64_t)shnum * shentsize > elf_len - shoff) return -1;
    const uint8_t *she = elf + shoff + (uint64_t)shstrndx * shentsize;
    uint64_t str_off = rd64(she + 0x18), str_size = rd64(she + 0x20);
    if (str_off > elf_len || str_size > elf_len - str_off) return -1;
    const char *shstr = (const char *)(elf + str_off);
    for (uint16_t i = 0; i < shnum; i++) {
        const uint8_t *e = elf + shoff + (uint64_t)i * shentsize;
        uint32_t nameo = rd32(e);
        if (nameo >= str_size) continue;
        if (strcmp(shstr + nameo, ".BTF")) continue;   /* only the section we want --- do */
        uint64_t off = rd64(e + 0x18), sz = rd64(e + 0x20); /* NOT bounds-abort on NOBITS */
        if (off > elf_len || sz > elf_len - off) return -1; /* sections like .bss */
        *btf = elf + off; *btf_sz = (uint32_t)sz; return 0;
    }
    return -1;   /* no .BTF section */
}

/* Does this program object carry CO-RE relocation records at all?
 *
 * WHY IT IS A SEPARATE, CHEAP QUESTION. Once field offsets are resolved at sign
 * time (02-RESEARCH-PARAMETERS.md P9) the shipped program has its `.BTF` and
 * `.BTF.ext` sections STRIPPED, and the appliance no longer needs type information
 * of its own. But a program built the old way still needs relocating, and the two
 * must be told apart BEFORE the target BTF is demanded --- otherwise the loader
 * refuses an already-relocated program for lacking something it does not use.
 * That ordering is the whole point: it lets the embedded `.BTF` be removed without
 * the loader's refusal logic changing again.
 *
 * Returns 1 if `.BTF.ext` is present, 0 if it is absent, and -1 if the ELF cannot
 * be walked. FAIL-DARK on -1: the caller must treat "cannot tell" as "needs
 * relocation" rather than as "nothing to do", because guessing the second on a
 * malformed object runs a program against unresolved placeholder offsets.
 */
int ls_core_elf_has_relos(const uint8_t *elf, uint32_t elf_len) {
    if (elf_len < 64) return -1;
    uint64_t shoff = rd64(elf + 0x28);
    uint16_t shentsize = rd16(elf + 0x3a), shnum = rd16(elf + 0x3c), shstrndx = rd16(elf + 0x3e);
    if (shentsize < 64 || shnum == 0 || shstrndx >= shnum) return -1;
    if (shoff > elf_len || (uint64_t)shnum * shentsize > elf_len - shoff) return -1;
    const uint8_t *she = elf + shoff + (uint64_t)shstrndx * shentsize;
    uint64_t str_off = rd64(she + 0x18), str_size = rd64(she + 0x20);
    if (str_off > elf_len || str_size > elf_len - str_off) return -1;
    const char *shstr = (const char *)(elf + str_off);
    for (uint16_t i = 0; i < shnum; i++) {
        const uint8_t *e = elf + shoff + (uint64_t)i * shentsize;
        uint32_t nameo = rd32(e);
        if (nameo >= str_size) continue;
        if (strcmp(shstr + nameo, ".BTF.ext") == 0) {
            uint64_t sz = rd64(e + 0x20);
            return sz > 0 ? 1 : 0;      /* an empty section relocates nothing */
        }
    }
    return 0;
}

/* skip const/volatile/restrict/typedef/type_tag qualifiers to the real type */
static const struct btf_type *btf_skip_mods(const struct btf *b, uint32_t *id) {
    const struct btf_type *t = btf_type_by_id(b, *id);
    int guard = 0;
    while (t && guard++ < 64) {
        int k = KIND(t);
        if (k==KIND_CONST||k==KIND_VOLATILE||k==KIND_RESTRICT||k==KIND_TYPEDEF||k==KIND_TYPE_TAG) {
            *id = t->size_or_type; t = btf_type_by_id(b, *id);
        } else break;
    }
    return t;
}
/* find a STRUCT/UNION of the given name in target BTF; returns id (0 = not found) */
static uint32_t btf_find_struct(const struct btf *b, const char *name) {
    for (uint32_t id = 1; id < b->nids; id++) {
        const struct btf_type *t = btf_type_by_id(b, id);
        int k = KIND(t);
        if ((k==KIND_STRUCT||k==KIND_UNION) && strcmp(btf_str(b,t->name_off),name)==0)
            return id;
    }
    return 0;
}
/* in target struct `st`, find member `name`; out: bit offset and member type id */
static int btf_find_member(const struct btf *b, const struct btf_type *st,
                           const char *name, uint32_t *bit_off, uint32_t *mtype) {
    const struct btf_member *m = (const struct btf_member *)(st + 1);
    for (uint32_t i = 0; i < VLEN(st); i++) {
        const char *mn = btf_str(b, m[i].name_off);
        if (mn[0] && strcmp(mn, name)==0) {
            uint32_t o = m[i].offset;
            *bit_off = KFLAG(st) ? (o & 0xffffff) : o;   /* bitfield-aware */
            *mtype = m[i].type;
            return 0;
        }
    }
    return -1;
}

/* Resolve one FIELD_BYTE_OFFSET relo.
 * local_id: type in the PROGRAM's BTF (gives per-level member NAMES).
 * access:   e.g. "0:2" --- arr[0] is the array index of the base, rest are member idxs.
 * Returns target byte offset, or -1 on any unsupported shape. */
static long core_field_offset(const struct btf *L, uint32_t local_id,
                              const char *access, const struct btf *T) {
    uint32_t acc[16]; int nacc = 0;
    for (const char *p = access; *p && nacc < 16; ) {
        acc[nacc++] = (uint32_t)strtoul(p, (char**)&p, 10);
        if (*p == ':') p++;
    }
    if (nacc < 1 || acc[0] != 0) return -1;   /* non-zero base array index: out of scope */

    uint32_t lid = local_id;
    const struct btf_type *lt = btf_skip_mods(L, &lid);
    if (!lt || (KIND(lt)!=KIND_STRUCT && KIND(lt)!=KIND_UNION)) return -1;

    const char *sname = btf_str(L, lt->name_off);
    if (!sname[0]) return -1;   /* anonymous root: out of scope */
    uint32_t tid = btf_find_struct(T, sname);
    if (!tid) return -1;
    const struct btf_type *tt = btf_type_by_id(T, tid);

    uint64_t bit_off = 0;
    for (int i = 1; i < nacc; i++) {
        uint32_t midx = acc[i];
        if (!lt || (KIND(lt)!=KIND_STRUCT && KIND(lt)!=KIND_UNION) || midx >= VLEN(lt)) return -1;
        if (!tt || (KIND(tt)!=KIND_STRUCT && KIND(tt)!=KIND_UNION)) return -1;
        const struct btf_member *lm = (const struct btf_member *)(lt + 1) + midx;
        const char *mname = btf_str(L, lm->name_off);
        uint32_t tbit, tmtype;
        if (btf_find_member(T, tt, mname, &tbit, &tmtype) < 0) return -1;
        bit_off += tbit;
        uint32_t nlid = lm->type; lt = btf_skip_mods(L, &nlid);
        uint32_t ntid = tmtype;   tt = btf_skip_mods(T, &ntid);
    }
    if (bit_off % 8) return -1;   /* sub-byte bitfield offset: not a byte offset */
    return (long)(bit_off / 8);
}

/* ---- the library entry point ---- */

/* Patch the s32 immediate (bytes 4..7) of the 8-byte insn at `insn_off` in the
 * program section, after bounds-checking.
 *
 * SCOPE BOUND (verified against docs.kernel.org/bpf/llvm_reloc.html, cached
 * kernel-llvm_reloc.html): a FIELD_BYTE_OFFSET relocation patches EITHER an
 * immediate (ALU/LD ops) OR an instruction's offset field (LDX/STX/ST). We patch
 * the IMMEDIATE only. That is correct for our programs because a verified program
 * cannot directly load `p->field` (PREVAIL refuses chasing the pointer); it must
 * use bpf_probe_read(&p->field), and `&p->field` compiles to an ALU add with the
 * offset as an immediate. The LDX/STX offset-field form does not arise for the
 * probe_read'd target fields we relocate. Supporting it would mean dispatching on
 * the insn opcode class here. */
static int patch_imm(uint8_t *sec, uint64_t sec_size, uint32_t insn_off, int32_t val) {
    if ((uint64_t)insn_off + 8 > sec_size) return -1;
    uint8_t *insn = sec + insn_off;
    insn[4] = (uint8_t)(val); insn[5] = (uint8_t)(val >> 8);
    insn[6] = (uint8_t)(val >> 16); insn[7] = (uint8_t)(val >> 24);
    return 0;
}

int ls_core_relocate(void *elf_v, uint32_t elf_len, const struct btf *target,
                     unsigned *n_out) {
    uint8_t *elf = elf_v;
    if (n_out) *n_out = 0;
    /* ELF64 header */
    if (elf_len < 64) return -LS_RELO_EBADELF;
    uint64_t shoff = rd64(elf + 0x28);
    uint16_t shentsize = rd16(elf + 0x3a), shnum = rd16(elf + 0x3c), shstrndx = rd16(elf + 0x3e);
    if (shentsize < 64 || shnum == 0 || shstrndx >= shnum) return -LS_RELO_EBADELF;
    if (shoff > elf_len || (uint64_t)shnum * shentsize > elf_len - shoff) return -LS_RELO_EBADELF;

    /* section-name string table */
    const uint8_t *she = elf + shoff + (uint64_t)shstrndx * shentsize;
    uint64_t shstr_off = rd64(she + 0x18), shstr_size = rd64(she + 0x20);
    if (shstr_off > elf_len || shstr_size > elf_len - shstr_off) return -LS_RELO_EBADELF;
    const char *shstr = (const char *)(elf + shstr_off);

    /* locate .BTF, .BTF.ext, and remember each section's data span */
    const uint8_t *btf_d = NULL, *ext_d = NULL; uint64_t btf_sz = 0, ext_sz = 0;
    for (uint16_t i = 0; i < shnum; i++) {
        const uint8_t *e = elf + shoff + (uint64_t)i * shentsize;
        uint32_t nameo = rd32(e);
        if (nameo >= shstr_size) continue;
        const char *nm = shstr + nameo;
        int isbtf = !strcmp(nm, ".BTF"), isext = !strcmp(nm, ".BTF.ext");
        if (!isbtf && !isext) continue;   /* skip; do NOT bounds-abort on NOBITS (.bss) */
        uint64_t off = rd64(e + 0x18), sz = rd64(e + 0x20);
        if (off > elf_len || sz > elf_len - off) return -LS_RELO_EBADELF;
        if (isbtf) { btf_d = elf + off; btf_sz = sz; } else { ext_d = elf + off; ext_sz = sz; }
    }
    if (!btf_d || !ext_d) return -LS_RELO_ENOBTF;

    struct btf L;
    if (btf_sz > 0xffffffffu || ls_core_btf_open(&L, btf_d, (uint32_t)btf_sz) < 0)
        return -LS_RELO_EBADBTF;

    /* .BTF.ext header: magic(2) ver(1) flags(1) hdr_len(4), then three (off,len) pairs;
     * core_relo is the third pair. */
    int rc = -LS_RELO_EBADBTF;
    if (ext_sz < 32) goto out;
    uint32_t hdr_len  = rd32(ext_d + 4);
    uint32_t core_off = rd32(ext_d + 24), core_len = rd32(ext_d + 28);
    if ((uint64_t)hdr_len + core_off + core_len > ext_sz || core_len < 4) goto out;
    const uint8_t *base = ext_d + hdr_len;
    const uint8_t *p    = base + core_off;
    const uint8_t *end  = p + core_len;
    uint32_t rec_size = rd32(p); p += 4;
    if (rec_size < 16) goto out;

    unsigned done = 0;
    while ((uint64_t)(end - p) >= 8) {
        uint32_t sec_name_off = rd32(p), num = rd32(p + 4); p += 8;
        const char *secname = btf_str(&L, sec_name_off);
        /* the program (code) section these relos apply to */
        uint8_t  *psec = NULL; uint64_t psec_sz = 0;
        for (uint16_t i = 0; i < shnum; i++) {
            const uint8_t *e = elf + shoff + (uint64_t)i * shentsize;
            uint32_t nameo = rd32(e);
            if (nameo < shstr_size && !strcmp(shstr + nameo, secname)) {
                uint64_t off = rd64(e + 0x18), sz = rd64(e + 0x20);
                if (off <= elf_len && sz <= elf_len - off) { psec = elf + off; psec_sz = sz; }
                break;
            }
        }
        for (uint32_t r = 0; r < num; r++) {
            if ((uint64_t)(end - p) < rec_size) { rc = -LS_RELO_EBADBTF; goto out; }
            uint32_t insn_off = rd32(p), type_id = rd32(p + 4),
                     acc_off  = rd32(p + 8), kind = rd32(p + 12);
            p += rec_size;
            if (kind != 0) { rc = -LS_RELO_EKIND; goto out; }      /* only FIELD_BYTE_OFFSET */
            long off = core_field_offset(&L, type_id, btf_str(&L, acc_off), target);
            if (off < 0) { rc = -LS_RELO_ENOFIELD; goto out; }
            if (!psec || patch_imm(psec, psec_sz, insn_off, (int32_t)off) < 0) {
                rc = -LS_RELO_EBOUNDS; goto out;
            }
            done++;
        }
    }
    if (n_out) *n_out = done;
    rc = LS_RELO_OK;
out:
    ls_core_btf_free(&L);
    return rc;
}

/* ---- self-test driver (not compiled into TMM) ----
 * Build:  gcc -O2 -Wall -DLS_CORE_RELO_TEST ls_core_relo.c -o relo
 * Run:    ./relo prog.o tmm.btf [out.o]   (exit 0 = every relo resolved)
 */
#ifdef LS_CORE_RELO_TEST
static int read_file(const char *path, uint8_t **buf, size_t *len) {
    FILE *f = fopen(path,"rb"); if(!f) return -1;
    fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
    *buf=malloc(n); *len=fread(*buf,1,n,f); fclose(f); return 0;
}
int main(int argc, char **argv) {
    /* --has-relos <obj>...  : print the ls_core_elf_has_relos() verdict per object.
     * Lives in the same driver so it is compiled exactly the way the in-TMM copy is,
     * rather than in a second harness that could drift from it. */
    if (argc >= 3 && strcmp(argv[1], "--has-relos") == 0) {
        int bad = 0;
        for (int i = 2; i < argc; i++) {
            uint8_t *e; size_t n;
            if (read_file(argv[i], &e, &n)) { printf("%-28s UNREADABLE\n", argv[i]); bad = 1; continue; }
            int r = ls_core_elf_has_relos(e, (uint32_t)n);
            printf("%-28s %s\n", argv[i],
                   r == 1 ? "1  needs relocation" :
                   r == 0 ? "0  offsets are baked" : "-1 cannot parse (treated as NEEDS)");
            free(e);
        }
        return bad;
    }
    if (argc < 3) { fprintf(stderr,"usage: %s prog.o tmm.btf [out.o]\n"
                                   "       %s --has-relos <obj>...\n",argv[0],argv[0]); return 2; }
    uint8_t *elf; size_t elflen; if (read_file(argv[1],&elf,&elflen)) return 2;
    uint8_t *tbtf; size_t tbtflen; if (read_file(argv[2],&tbtf,&tbtflen)) return 2;
    struct btf T;
    if (ls_core_btf_open(&T, tbtf, (uint32_t)tbtflen) < 0) { fprintf(stderr,"bad target BTF\n"); return 2; }
    fprintf(stderr,"target BTF: %u types\n", T.nids-1);
    unsigned n = 0;
    int rc = ls_core_relocate(elf, (uint32_t)elflen, &T, &n);
    fprintf(stderr,"ls_core_relocate rc=%d, %u relo(s)\n", rc, n);
    if (rc == LS_RELO_OK && argc >= 4) {
        FILE *o = fopen(argv[3],"wb");
        if (o) { fwrite(elf,1,elflen,o); fclose(o); fprintf(stderr,"wrote relocated object: %s\n", argv[3]); }
    }
    ls_core_btf_free(&T);
    return rc == LS_RELO_OK ? 0 : 1;
}
#endif /* LS_CORE_RELO_TEST */

ls_core_relo.h.text:
/* ls_core_relo.h --- CO-RE field-offset relocation for the loader.
 *
 * A portable program (surface/shield) names TMM fields by struct+field NAME and
 * carries .BTF + .BTF.ext relocation records. At load, ls_core_relocate() resolves
 * each field's byte offset against THIS build's BTF and patches the instruction
 * immediate --- so one bytecode runs on any build, no baked offsets, no rebuild.
 *
 * Scope: kind=0 FIELD_BYTE_OFFSET, the only kind our compiler emits for
 * preserve_access_index field reads. Every other kind is rejected (fail-dark).
 *
 * Runs on the TMM thread (via ls_prep_run_pending -> ls_vm_reload), where malloc
 * is legal; it is NOT safe on the loader pthread.
 */
#ifndef LS_CORE_RELO_H
#define LS_CORE_RELO_H

#include <stdint.h>

/* Parsed BTF: a type-id -> byte-offset index over an in-memory BTF blob.
 * The blob must outlive the struct (not copied). Free idx with free(). */
struct btf {
    const uint8_t *types;  uint32_t types_len;
    const char    *strs;   uint32_t strs_len;
    uint32_t      *idx;    uint32_t nids;   /* idx[id] = byte offset in types[] */
};

/* Parse a BTF blob (the target build's BTF, or a program's local .BTF) into `b`.
 * Returns 0 on success, <0 on a malformed blob. Allocates b->idx (free() it). */
int ls_core_btf_open(struct btf *b, const uint8_t *blob, uint32_t len);
void ls_core_btf_free(struct btf *b);

/* Find the `.BTF` section span inside an ELF64 blob (bounds-checked). On success
 * sets *btf and *btf_sz to point into `elf` and returns 0; returns <0 if the ELF is
 * malformed or has no `.BTF` section. Used to read the running binary's own BTF
 * from /proc/self/exe --- the kernel's "embed .BTF in vmlinux" model for a
 * userspace process. */
int ls_core_btf_find_in_elf(const uint8_t *elf, uint32_t elf_len,
                            const uint8_t **btf, uint32_t *btf_sz);

/* 1 if the program object carries `.BTF.ext` (so it needs relocating), 0 if it does
 * not, -1 if the ELF cannot be walked. Asked BEFORE the target BTF is demanded, so
 * a program whose offsets were resolved at sign time --- and whose `.BTF`/`.BTF.ext`
 * were therefore stripped --- is not refused for lacking type information it does
 * not use. Treat -1 as "needs relocation": see the note in ls_core_relo.c. */
int ls_core_elf_has_relos(const uint8_t *elf, uint32_t elf_len);

/* Relocate `elf` (an eBPF program object, MUTABLE) in place against `target`.
 * Parses the program's own .BTF/.BTF.ext, resolves every FIELD_BYTE_OFFSET record
 * by field name against `target`, and patches the instruction immediates.
 * Returns 0 iff EVERY record resolved and was patched; <0 (and leaves the object
 * untrusted) if the object is malformed, carries an unsupported record kind, or a
 * field is absent in the target --- the caller MUST refuse to load on <0.
 * n_out (optional) receives the number of records relocated. */
int ls_core_relocate(void *elf, uint32_t elf_len, const struct btf *target,
                     unsigned *n_out);

/* relocation result codes (negated on return) */
enum {
    LS_RELO_OK            = 0,
    LS_RELO_EBADELF       = 1,   /* ELF header/section table out of bounds        */
    LS_RELO_ENOBTF        = 2,   /* program lacks .BTF/.BTF.ext                    */
    LS_RELO_EBADBTF       = 3,   /* malformed local BTF or .BTF.ext               */
    LS_RELO_EKIND         = 4,   /* unsupported relocation kind                   */
    LS_RELO_ENOFIELD      = 5,   /* field/struct absent in target, or bitfield    */
    LS_RELO_EBOUNDS       = 6,   /* insn offset outside its program section       */
};

#endif /* LS_CORE_RELO_H */

ls_fexit.c.text:
/*
 * ls_fexit.c --- the C half of the function-exit trampoline: the shadow stack.
 *
 * The per-slot exit trampolines (ls_fexit_slot<n>, trampoline_x86_64.S) call:
 *
 *   ls_fexit_enter(slot, slot_addr, args)  at the hooked function's ENTRY ---
 *       record the real return address (and which exit-program slot to run) and
 *       hijack the stack slot.
 *   ls_fexit_leave(cur, retval)  when the body RETURNS into the stub --- find the
 *       matching frame (reclaiming any a non-local exit skipped), run the exit
 *       program, hand back the real return address.
 *
 * WHY KEYED BY THE STACK POINTER, not a plain LIFO. A skipped return (longjmp or
 * a C++ exception unwinding past a hooked frame) never runs that frame's `ret`,
 * so its exit stub never fires and its frame is never popped; a plain stack would
 * then pop a stale frame and return to the wrong address. Keying each frame to
 * the hijacked slot's address lets ls_fexit_leave discard every frame DEEPER than
 * the one returning (deeper == lower address; the stack grows down) before it
 * matches --- the reclaim kretprobes does. TMM itself has no longjmp and no C++
 * unwind (P8, on the build box), so this is a backstop; a future exit hook on an
 * unwind-traversable target is refused at arm time instead.
 *
 * ONE INSTANCE, no lock: TMM is core-pinned and run-to-completion, so two
 * invocations never overlap on a core --- the same assumption ls_vm.h makes. All
 * state is g_ls_fexit_*, which the TMM globals whitelist carries as a set.
 *
 * Value-return hooks call the program at return. Snapshot hooks also run at
 * entry, then retain only a bounded private state copy with this exact frame.
 */

#include <stdint.h>
#include <string.h>

#include "ls_fexit.h"
#include "ls_vm.h"       /* ls_vm_call --- run the exit program on struct ls_ctx_exit */

/* Bounded: overflow degrades to "do not hijack" (a plain return), never grows or
 * crashes. 512 is far past any real depth under a single hooked chain. */
#define LS_FEXIT_DEPTH 512

struct ls_fexit_frame {
    uint64_t *slot;         /* address of the caller-return we overwrote (the key) */
    uint64_t  real_ret;     /* what was there --- where the function truly returns  */
    uint64_t  args[6];      /* rdi..r9 as captured at entry                         */
    uint64_t  seq;          /* which enter this was                                 */
    int       prog_slot;    /* which exit-program to run at leave                   */
    int       snapshot;
    int       captured;
    struct ls_snapshot_id identity;
    uint64_t  state[4];
};

/* Per-instance state. Non-static: the whole g_ls_fexit_* set is what the TMM
 * globals whitelist must declare, and the harness reads the counters/log. */
struct ls_fexit_frame g_ls_fexit_stack[LS_FEXIT_DEPTH];
int      g_ls_fexit_top;        /* number of live frames                            */
uint64_t g_ls_fexit_seq;        /* monotonic enter counter                          */

struct ls_fexit_event g_ls_fexit_log[LS_FEXIT_LOG];
unsigned g_ls_fexit_log_n;      /* exits recorded (capped at LS_FEXIT_LOG)          */
uint64_t g_ls_fexit_exits;      /* total exits observed                             */
uint64_t g_ls_fexit_reclaimed;  /* frames discarded as skipped (non-local exits)    */
uint64_t g_ls_fexit_overflow;   /* enters that could not hijack (depth exceeded)    */
uint64_t g_ls_fexit_desync;     /* leaves that found no matching frame (must be 0)  */

/* The exit STUB's address (trampoline_x86_64.S), written into the hijacked slot. */
extern char ls_fexit_stub[];

void
ls_fexit_reset(void)
{
    g_ls_fexit_top = 0;
    g_ls_fexit_seq = 0;
    g_ls_fexit_log_n = 0;
    g_ls_fexit_exits = g_ls_fexit_reclaimed = g_ls_fexit_overflow = g_ls_fexit_desync = 0;
    memset(g_ls_fexit_log, 0, sizeof g_ls_fexit_log);
}

/*
 * At the hooked function's entry. `slot` is the address of its caller-return on
 * the live stack; `args` points at the six saved integer-argument registers;
 * `prog_slot` is which exit program runs at leave.
 *
 * Record the frame, then overwrite *slot so the body returns into the stub. On
 * overflow we DO NOT hijack: the function returns normally, no exit fires, and
 * nothing is corrupted --- a bounded, safe degradation.
 */
void
ls_fexit_enter(int prog_slot, uint64_t *slot, const uint64_t *args)
{
    if (g_ls_fexit_top >= LS_FEXIT_DEPTH || g_ls_fexit_seq == UINT64_MAX) {
        g_ls_fexit_overflow++;
        return;                                 /* do not hijack: plain return */
    }
    struct ls_fexit_frame *f = &g_ls_fexit_stack[g_ls_fexit_top++];
    f->slot      = slot;
    f->real_ret  = *slot;
    memcpy(f->args, args, sizeof f->args);
    f->seq       = ++g_ls_fexit_seq;
    f->prog_slot = prog_slot;
    f->snapshot = ls_vm_snapshot_identity(prog_slot, &f->identity);
    f->captured = 0;
    memset(f->state, 0, sizeof f->state);

    if (f->snapshot) {
        struct ls_snapshot_ctx ctx = {0};
        memcpy(ctx.arg, f->args, sizeof ctx.arg);
        ctx.phase = LS_SNAPSHOT_ENTRY;
        ctx.sequence = f->seq;
        if (ls_vm_snapshot_call(prog_slot, &f->identity, &ctx) == 0) {
            memcpy(f->state, ctx.state, sizeof f->state);
            f->captured = 1;
        }
    }

    *slot = (uint64_t)(void *)ls_fexit_stub;    /* the hijack */
}

/*
 * When the body returns into the stub. `cur` is rsp at stub entry --- exactly
 * (the hijacked slot's address) + 8, because the body's `ret` popped the slot.
 * So the returning frame has slot == cur - 8.
 *
 * Reclaim first: any frame whose slot is DEEPER (lower address) than the one
 * returning was skipped by a non-local exit --- discard it. Then the top frame
 * must be the match; pop it, run the exit program, return its real address.
 *
 * Fail-safe: if no frame matches (a desync we cannot resolve --- must not happen
 * for a hooked target under the arm-time rules), return `retval`.
 */
uint64_t
ls_fexit_leave(uint64_t cur, uint64_t retval)
{
    uint64_t *watermark = (uint64_t *)(cur - 8);

    while (g_ls_fexit_top > 0 && g_ls_fexit_stack[g_ls_fexit_top - 1].slot < watermark) {
        g_ls_fexit_top--;
        g_ls_fexit_reclaimed++;
    }

    if (g_ls_fexit_top == 0 || g_ls_fexit_stack[g_ls_fexit_top - 1].slot != watermark) {
        g_ls_fexit_desync++;
        return retval;                          /* unreachable under arm-time rules */
    }

    struct ls_fexit_frame *f = &g_ls_fexit_stack[--g_ls_fexit_top];

    /*
     * Run the exit program on the EXIT CONTEXT (fexit step #2): the entry
     * arguments plus the return value. arg[0..4] are rdi..r8, matching the entry
     * ctx; arg[5]/r9 is captured but not exposed (the entry ctx is five wide).
     *
     * The verdict is IGNORED --- the body has already run, so there is no
     * SAFE_RETURN to apply; an exit program is observe-only (read post-execution
     * state, stream, count). ls_vm_call fails open, exactly like the entry path:
     * a program that cannot run must not take TMM down with it.
     */
    if (f->snapshot) {
        struct ls_snapshot_ctx ctx = {0};
        memcpy(ctx.arg, f->args, sizeof ctx.arg);
        ctx.phase = LS_SNAPSHOT_RETURN;
        ctx.flags = f->captured ? LS_SNAPSHOT_CAPTURED : 0;
        ctx.sequence = f->seq;
        memcpy(ctx.state, f->state, sizeof ctx.state);
        (void)ls_vm_snapshot_call(f->prog_slot, &f->identity, &ctx);
    } else {
        struct ls_ctx_exit ctx = {0};
        memcpy(ctx.arg, f->args, sizeof ctx.arg);
        ctx.ret = retval;
        (void)ls_vm_call(f->prog_slot, &ctx, sizeof ctx);
    }

    /* Record for `status` and the harness --- recent exits, like ls_vm.h's ctx
     * samples: a small per-instance ring, not the program's job. */
    g_ls_fexit_exits++;
    if (g_ls_fexit_log_n < LS_FEXIT_LOG) {
        struct ls_fexit_event *e = &g_ls_fexit_log[g_ls_fexit_log_n++];
        e->seq    = f->seq;
        e->slot   = f->prog_slot;
        e->retval = f->snapshot ? 0 : retval;
        memcpy(e->args, f->args, sizeof e->args);
    }

    return f->real_ret;
}

ls_fexit.h.text:
/*
 * ls_fexit.h --- the function-exit trampoline's shadow-stack interface.
 *
 * The per-slot exit trampolines (ls_fexit_slot<n>, in trampoline_x86_64.S) call
 * ls_fexit_enter / ls_fexit_leave; the harness (check_fexit.c) reads the log and
 * counters. See ls_fexit.c.
 *
 * All mutable state is a single per-instance block of g_ls_fexit_* globals ---
 * one VM per core-pinned run-to-completion TMM instance, so no lock, and the
 * whole set is what the TMM globals whitelist must carry (like g_ls_audit).
 */
#ifndef LS_FEXIT_H
#define LS_FEXIT_H

#include <stdint.h>
#include "ls_vm.h"

#define LS_FEXIT_LOG 64u        /* recent exits kept for inspection */

/* The exit payload retains arg[0..4] at bytes 0..39 and ret at bytes 40..47.
 * fexit/ selects the same 96-byte tracing descriptor as fentry/, so the rest
 * must also be allocated and zeroed before calling the program. */
struct ls_ctx_exit {
    uint64_t arg[5];            /* rdi..r8, as the entry ctx           */
    uint64_t ret;              /* the hooked function's return value  */
    uint64_t reserved[LS_TRACING_CTX_SIZE / sizeof(uint64_t) - 6];
};
_Static_assert(sizeof(struct ls_ctx_exit) == LS_TRACING_CTX_SIZE,
               "exit context must cover the verifier's tracing region");
_Static_assert(offsetof(struct ls_ctx_exit, ret) == 40,
               "exit return-value offset must not change");
_Static_assert(offsetof(struct ls_ctx_exit, reserved) == 48,
               "exit payload must remain 48 bytes");

/* One observed exit: what the exit program would have been handed, plus which
 * slot's program it was. */
struct ls_fexit_event {
    uint64_t seq;               /* which enter this paired with           */
    int      slot;              /* which exit-program slot                */
    uint64_t retval;            /* the hooked function's return value      */
    uint64_t args[6];           /* rdi..r9 captured at entry               */
};

/* Called from the per-slot exit trampoline. `slot` is which exit-program to run
 * at leave; `slot_addr` is the caller-return to hijack; `args` the saved rdi..r9. */
void     ls_fexit_enter(int slot, uint64_t *slot_addr, const uint64_t *args);
uint64_t ls_fexit_leave(uint64_t cur, uint64_t retval);

/* Clear all state between test cases (and at instance init). */
void ls_fexit_reset(void);

/* Per-instance state / observability (defined in ls_fexit.c). */
extern struct ls_fexit_event g_ls_fexit_log[LS_FEXIT_LOG];
extern unsigned g_ls_fexit_log_n;
extern uint64_t g_ls_fexit_exits;
extern uint64_t g_ls_fexit_reclaimed;
extern uint64_t g_ls_fexit_overflow;
extern uint64_t g_ls_fexit_desync;

#endif /* LS_FEXIT_H */

ls_json.h.text:
/* ls_json.h --- JSON string escaping for the drain agent's output.

 * In its own header so check_json.c can reach it. It lived inside ls_drain.c as a
 * static, next to main(), where nothing could test it --- and escaping that is never
 * exercised is how a malformed line reaches a consumer, which then reports a bug
 * against the producer.
 */
#ifndef LS_JSON_H
#define LS_JSON_H

#include <stdint.h>
#include <stdio.h>

/*
 * JSON string escaping, which this file did NOT do before Phase 3.
 *
 * `file` is a __FILE__ basename --- always [a-z0-9_.] --- so emitting it raw
 * happened to produce valid JSON. `cause` is human-written prose from TMM's source
 * and, at flow_table.c, an entry from a runtime table: a quote, a backslash or a
 * stray control byte in any of those makes the whole line unparseable, and the
 * breakage surfaces in whatever consumes the stream rather than here. Escaping
 * arrives in the same change as the field that needs it.
 *
 * Bytes outside printable ASCII become \uXXXX rather than being passed through,
 * because the record is a fixed-size field from a teardown path and there is no
 * guarantee it holds UTF-8.
 */
static inline void
ls_json_str(const char *p, uint32_t n)
{
    uint32_t i;
    for (i = 0; i < n && p[i] != '\0'; i++) {
        unsigned char c = (unsigned char)p[i];
        switch (c) {
        case '"':  fputs("\\\"", stdout); break;
        case '\\': fputs("\\\\", stdout); break;
        case '\n': fputs("\\n", stdout);  break;
        case '\r': fputs("\\r", stdout);  break;
        case '\t': fputs("\\t", stdout);  break;
        default:
            if (c < 0x20 || c > 0x7e)
                printf("\\u%04x", c);
            else
                putchar(c);
        }
    }
}


#endif /* LS_JSON_H */

ls_map.h.text:
/* ls_map.h --- state that survives between program invocations.
 *
 * WHY THIS IS THE UNLOCK. Until now a program saw one invocation, answered yes or
 * no, and forgot everything. The only question expressible was "is this one input
 * bad?". With a map it can ask "has this client done this forty times in a
 * minute?" --- which is what most real abuse looks like, and what TMM's tmstat
 * counters cannot answer because they hold totals with no link back to the
 * request that caused them.
 *
 * THREE THINGS THAT MADE THIS CHEAPER THAN EXPECTED, each an assumption that was
 * wrong:
 *
 *   - PREVAIL already understands maps. A program declaring a standard
 *     SEC("maps") hash and calling helpers 1/2/3 verifies UNCHANGED, with every
 *     gate on (substrate/shields/exp/map_probe.bpf.c). Helper ids 1/2/3 are the
 *     standard BPF map helpers and PREVAIL's linux platform knows their
 *     signatures, so implementing those ids with those semantics needs no
 *     verifier work at all.
 *   - uBPF resolves the map reference for us. clang emits `lddw r1, 0` plus an
 *     R_BPF_64_64 relocation against the map symbol, and uBPF ignores
 *     relocations --- so the helper would receive 0. But
 *     ubpf_register_data_relocation() is a callback for exactly this: uBPF hands
 *     us the maps section and the symbol offset, and we return the value to plant
 *     in the instruction.
 *   - uBPF can be taught that map memory is legal. Its bounds check permits only
 *     the ctx and the stack, so a returned value pointer would be refused;
 *     ubpf_register_data_bounds_check() extends that. Note the JIT does NOT
 *     bounds-check at all, so without this the interpreter and the JIT would
 *     disagree --- working in production and failing in test, which is the worst
 *     possible split.
 *
 * WHAT THE PROGRAM IS HANDED, AND THE SECURITY BOUNDARY. The relocation returns
 * a SMALL INDEX, not a pointer. So a program never holds or supplies a host
 * address, and validating a map reference is a range check on an integer --- there
 * is no forged-pointer case to defend against. That is stronger than real BPF's
 * arrangement and it fell out of uBPF's missing relocation step.
 *
 * PREVAIL proves the program passed *a map descriptor* and that it reads at most
 * value_size bytes of what lookup returned. It cannot prove the HOST resolves the
 * index to a map of that shape. So ls_map_check_descriptor() is the crossing
 * where the verifier's assumption meets our storage, and it is the same class of
 * check as finding O14: the verifier proved something about one artifact and the
 * runtime must be shown to agree.
 *
 * PER THREAD, FIXED SIZE, NO LOCKS. One map set per TMM thread, mmap'd at init,
 * never grown, never rehashed. Per-thread removes locking from the hot path by
 * construction, which is the same reason the egress ring is per-thread. mmap
 * rather than malloc because TMM aliases malloc to a per-core allocator whose
 * spinlock is never initialised on threads TMM did not create.
 *
 * Collision policy is EVICT, counted. A bounded table that blocks or fails on a
 * full bucket would put an attacker in control of the data path; overwriting the
 * incumbent and counting it keeps the cost fixed and the loss visible.
 */
#ifndef LS_MAP_H
#define LS_MAP_H

#include <stdint.h>
#include <string.h>

#define LS_MAP_MAX      4u      /* maps per program                     */
#define LS_MAP_ENTRIES  256u    /* power of two --- index masks cleanly  */
#define LS_MAP_KEY_MAX  16u
#define LS_MAP_VAL_MAX  32u

/* Matches struct bpf_map_def, which is what clang writes into SEC("maps") and
 * what PREVAIL parses. Read by the relocation callback. */
struct ls_map_def {
    uint32_t type, key_size, value_size, max_entries, map_flags;
};

#define LS_MAP_TYPE_HASH 1u     /* BPF_MAP_TYPE_HASH */
/*
 * BPF_MAP_TYPE_RINGBUF, and it is NOT storage --- it is a handle on the thread's
 * existing egress ring.
 *
 * WHY A MAP AT ALL. bpf_ringbuf_output(rb, data, size, flags) is helper id 130, whose
 * first argument is a map reference, and PREVAIL already knows that signature --- so a
 * program can emit with ZERO verifier work. Verified 2026-08-18: a program declaring a
 * SEC("maps") entry of this type and calling id 130 passes PREVAIL unchanged. Inventing
 * our own emit helper at a private id would have meant teaching PREVAIL about it.
 *
 * A ringbuf descriptor is SHAPED DIFFERENTLY from a hash one: key_size and value_size
 * are both 0 and max_entries is a BYTE COUNT. So ls_map_check_descriptor has to admit a
 * shape it otherwise (correctly) refuses, and ls_map_create must not allocate a table
 * for it.
 */
#define LS_MAP_TYPE_RINGBUF 27u /* BPF_MAP_TYPE_RINGBUF --- the egress ring     */
/*
 * AND THE ONE ACTUALLY USED, found the hard way. bpf_ringbuf_output is helper id 130, and
 * uBPF's external-function table is UBPF_MAX_EXT_FUNCS entries --- 64 by default
 * (ubpf.h:72). So ubpf_register(vm, 130, ...) returns -1, the all-or-nothing install
 * failed, and an image shipped in which NO helper registered at all: every program load
 * was refused and even the built-in shield never armed. Loud, which is what
 * all-or-nothing is for.
 *
 * bpf_perf_event_output is id 25 --- inside the table --- and PREVAIL knows it just as
 * well (verified: a program declaring this map type and calling id 25 passes unchanged).
 * Its descriptor is shaped like a HASH one (key_size 4, value_size 4), so type is the only
 * thing that separates them, which is why the check below switches on d->type.
 */
#define LS_MAP_TYPE_PERF_EVENT_ARRAY 4u /* BPF_MAP_TYPE_PERF_EVENT_ARRAY        */

struct ls_map {
    uint32_t in_use;
    /* A ringbuf slot holds NO storage: keys/vals stay zeroed and every hash operation
     * on it must refuse. Kept in the same array as the hash maps because the program
     * refers to both by the same index space, and splitting them would mean two
     * relocation namespaces for no gain. */
    uint32_t is_ring;
    uint32_t key_sz, val_sz, entries;
    uint64_t hits, misses, evictions, updates;
    uint8_t  used[LS_MAP_ENTRIES];
    uint8_t  keys[LS_MAP_ENTRIES * LS_MAP_KEY_MAX];
    uint8_t  vals[LS_MAP_ENTRIES * LS_MAP_VAL_MAX];
};

struct ls_map_set {
    struct ls_map m[LS_MAP_MAX];
    uint32_t      n;
    uint64_t      generation;
};

/* FNV-1a over the key bytes. Not cryptographic and does not need to be: the
 * table is per-thread and bounded, so the worst an attacker achieves by forcing
 * collisions is eviction of their own entries, which is already the policy. */
static inline uint32_t
ls_map_hash(const uint8_t *k, uint32_t n)
{
    uint32_t h = 2166136261u, i;
    for (i = 0; i < n; i++) {
        h ^= k[i];
        h *= 16777619u;
    }
    return h & (LS_MAP_ENTRIES - 1u);
}

/*
 * THE CROSSING. PREVAIL verified the program against the descriptor in the ELF;
 * this is where that descriptor is checked against what the host can actually
 * store. A mismatch means the verifier proved bounds for a shape we do not
 * enforce, so it is a REFUSAL, never a clamp.
 */
static inline int
ls_map_check_descriptor(const struct ls_map_def *d)
{
    /* The ringbuf shape, checked FIRST and on its own terms. key_size and value_size
     * are 0 by definition here, so falling through to the hash checks below would
     * refuse it --- and refusing it is right for a hash map and wrong for this. */
    if (d->type == LS_MAP_TYPE_RINGBUF) {
        if (d->key_size != 0 || d->value_size != 0)  return 0;
        if (d->max_entries == 0)                     return 0;
        return 1;
    }
    /* A perf-event array is shaped like a hash map (4/4), so ONLY the type
     * separates them. Admitted on its own terms and never given storage. */
    if (d->type == LS_MAP_TYPE_PERF_EVENT_ARRAY) {
        if (d->max_entries == 0)                     return 0;
        return 1;
    }
    if (d->type != LS_MAP_TYPE_HASH)                return 0;
    if (d->key_size == 0 || d->key_size > LS_MAP_KEY_MAX)   return 0;
    if (d->value_size == 0 || d->value_size > LS_MAP_VAL_MAX) return 0;
    if (d->max_entries == 0 || d->max_entries > LS_MAP_ENTRIES) return 0;
    return 1;
}

/* Create a map from a verified descriptor. Returns its index, or -1. */
static inline int
ls_map_create(struct ls_map_set *s, const struct ls_map_def *d)
{
    struct ls_map *m;
    if (s->n >= LS_MAP_MAX || !ls_map_check_descriptor(d))
        return -1;
    m = &s->m[s->n];
    memset(m, 0, sizeof *m);
    m->in_use  = 1;
    if (d->type == LS_MAP_TYPE_RINGBUF ||
        d->type == LS_MAP_TYPE_PERF_EVENT_ARRAY) {
        /* No table. The slot exists only so an index resolves to "the egress ring";
         * key_sz and val_sz stay 0, which is what every hash operation checks against
         * before touching storage. */
        m->is_ring = 1;
        return (int)s->n++;
    }
    m->key_sz  = d->key_size;
    m->val_sz  = d->value_size;
    m->entries = d->max_entries;
    return (int)s->n++;
}

/* Resolve an index handed back by a program. THE validation --- an integer range
 * check, because the program never holds an address. */
static inline struct ls_map *
ls_map_get(struct ls_map_set *s, uint64_t idx)
{
    if (s == 0)
        return 0;           /* helper ran on a thread with no maps --- fail safe */
    if ((idx >> 8) != s->generation)
        return 0;           /* reference from a retired registry generation */
    idx &= 255u;
    if (idx >= LS_MAP_MAX || idx >= (uint64_t)s->n)
        return 0;
    return s->m[idx].in_use ? &s->m[idx] : 0;
}

/* Linear probe from the hash, bounded by the table size --- so a lookup is O(1)
 * with a constant worst case, which is what a data path requires. */
static inline int
ls_map_slot(struct ls_map *m, const uint8_t *key, int for_insert)
{
    uint32_t h = ls_map_hash(key, m->key_sz) % m->entries, i, s;
    int empty = -1;
    for (i = 0; i < m->entries; i++) {
        s = (h + i) % m->entries;
        if (!m->used[s]) {
            if (empty < 0) empty = (int)s;
            continue;
        }
        if (memcmp(&m->keys[s * LS_MAP_KEY_MAX], key, m->key_sz) == 0)
            return (int)s;
    }
    /* Deletion leaves holes. Search the whole bounded table before inserting,
     * or an existing colliding key beyond a hole can be duplicated or missed. */
    if (for_insert && empty >= 0)
        return empty;
    /* Full: evict at the hash position rather than failing. Counted by the
     * caller --- a silent eviction is indistinguishable from a miss. */
    return for_insert ? (int)h : -1;
}

static inline void *
ls_map_lookup(struct ls_map *m, const uint8_t *key)
{
    /* A RINGBUF slot has no table. Refusing here rather than relying on key_sz==0
     * arithmetic further down: a hash operation on the ring must be an explicit
     * no-op, not an accident of zero sizes. */
    if (m != 0 && m->is_ring)
        return 0;

    int s = ls_map_slot(m, key, 0);
    if (s < 0) { m->misses++; return 0; }
    m->hits++;
    return &m->vals[(uint32_t)s * LS_MAP_VAL_MAX];
}

static inline int
ls_map_update(struct ls_map *m, const uint8_t *key, const uint8_t *val)
{
    /* A RINGBUF slot has no table. Refusing here rather than relying on key_sz==0
     * arithmetic further down: a hash operation on the ring must be an explicit
     * no-op, not an accident of zero sizes. */
    if (m != 0 && m->is_ring)
        return -1;

    int s = ls_map_slot(m, key, 1);
    if (s < 0)
        return -1;
    if (m->used[s] && memcmp(&m->keys[(uint32_t)s * LS_MAP_KEY_MAX], key, m->key_sz) != 0)
        m->evictions++;
    memcpy(&m->keys[(uint32_t)s * LS_MAP_KEY_MAX], key, m->key_sz);
    memcpy(&m->vals[(uint32_t)s * LS_MAP_VAL_MAX], val, m->val_sz);
    m->used[s] = 1;
    m->updates++;
    return 0;
}

static inline int
ls_map_delete(struct ls_map *m, const uint8_t *key)
{
    /* A RINGBUF slot has no table. Refusing here rather than relying on key_sz==0
     * arithmetic further down: a hash operation on the ring must be an explicit
     * no-op, not an accident of zero sizes. */
    if (m != 0 && m->is_ring)
        return -1;

    int s = ls_map_slot(m, key, 0);
    if (s < 0)
        return -1;
    m->used[s] = 0;
    return 0;
}

/*
 * The bounds-check callback's predicate: is `addr` inside a value slot of some
 * map in this set, for `size` bytes?
 *
 * Deliberately checks against the VALUE array only. Keys and metadata are the
 * host's; a program has no business reading either, and PREVAIL never gives it a
 * pointer to them.
 */
static inline int
ls_map_addr_ok(struct ls_map_set *s, uint64_t addr, uint64_t size)
{
    uint32_t i;
    for (i = 0; i < s->n; i++) {
        struct ls_map *m = &s->m[i];
        uint64_t lo = (uint64_t)(uintptr_t)m->vals;
        uint64_t hi = lo + (uint64_t)m->entries * LS_MAP_VAL_MAX;
        if (addr < lo || addr >= hi)
            continue;
        /* Must not straddle the end of the slot it starts in --- otherwise a
         * program could read one value and the beginning of the next. */
        if (size > LS_MAP_VAL_MAX)
            return 0;
        if (((addr - lo) % LS_MAP_VAL_MAX) + size > LS_MAP_VAL_MAX)
            return 0;
        if (addr + size > hi)
            return 0;
        return 1;
    }
    return 0;
}

#endif /* LS_MAP_H */

ls_map_glue.h.text:
/* ls_map_glue.h --- the three uBPF callbacks that make maps work.
 *
 * Registered on every VM before the ELF is loaded, because the relocation
 * callback has to be in place when uBPF walks the maps section.
 *
 *   relocation    resolve `lddw r1, <map symbol>` to a map INDEX
 *   bounds check  permit reads of map VALUE memory
 *   helpers 1/2/3 the standard BPF map helpers, which PREVAIL already knows
 *
 * ALL FIVE REGISTRATIONS GO THROUGH ls_map_glue_install(), AND THAT IS THE POINT.
 * On 2026-08-17 the registration calls existed only in the build box's copy of
 * ls_vm.c and were never carried back here; copying this tree over that one
 * deleted them. Every symptom pointed elsewhere. The programs still loaded, still
 * ran, still verified --- their maps were simply always empty, which is
 * indistinguishable from a predicate that never matches. What caught it was the
 * build's globals manifest: with nothing calling ls_map_reloc, the compiler
 * removed g_ls_shapes as dead, and the manifest noticed a name it expected was
 * gone. A five-call sequence spread across two arm paths is a sequence that can
 * be half-applied; one function cannot.
 *
 * ORDER MATTERS AND IS EASY TO GET WRONG. ubpf_register_data_relocation must
 * precede ubpf_load_elf_ex; registered after, the maps section has already been
 * walked and every `lddw` still holds the zero clang emitted. The program then
 * runs, calls a helper with map=0, gets NULL, and behaves like a map that is
 * simply always empty --- which looks like a working feature and is not.
 */
#ifndef LS_MAP_GLUE_H
#define LS_MAP_GLUE_H

#include "ls_map.h"
#include <stdatomic.h>
#include <stdio.h>
#include <sys/mman.h>
#include "ls_tp.h"
#include "ubpf.h"
#include <fcntl.h>
#include <stdlib.h>   /* strtoull, for the /proc/self/maps parse */
#include <time.h>
#include <unistd.h>

/*
 * SHAPE IS GLOBAL, STORAGE IS PER THREAD, and the split is forced rather than
 * chosen. g_slots in ls_vm.c is a plain process-global, so one VM is shared by
 * every TMM thread --- but relocation runs ONCE, on the loader thread, when the
 * ELF is loaded. If the map set were purely thread-local, the loader thread would
 * get the maps and every data-plane thread would find none: lookups return NULL
 * forever and the feature looks like a map that is always empty.
 *
 * So relocation records only the SHAPE in a process-global table, and each thread
 * allocates its own STORAGE from those shapes the first time a helper runs on it.
 * Threads never share a table. VM calls use an atomic reader count to prevent
 * registry reset during execution; they do not wait for a reset.
 */
/* ONE TU DEFINES THESE, EVERY OTHER TU SEES EXTERNS. They were `static`, which
 * in a header means each including TU gets its OWN copy --- the shapes written by
 * relocation would be invisible to a helper compiled elsewhere. That never bit us
 * only because exactly one file happened to include this header; the install
 * function below means two now do. The owner defines LS_MAP_GLUE_IMPL before
 * including (ls_vm_load.c). If a second file ever does, the link fails on a
 * duplicate symbol --- loudly, at build time, which is the whole reason to prefer
 * extern here over a comment asking people to be careful. */
/*
 * IDENTITY IS THE SYMBOL NAME, NOT THE SHAPE --- and that is a fix, not a
 * preference. This table used to dedup on (key_size, value_size, max_entries)
 * alone, which is correct WITHIN one program (clang emits one relocation per
 * reference, so the same map arrives several times) and wrong ACROSS programs,
 * because g_ls_shapes is process-global and never scoped by slot. Two unrelated
 * programs each declaring a 4-byte-key/8-byte-value/64-entry map resolved to the
 * SAME index and therefore the same per-thread storage: each saw the other's
 * counts as its own. Nothing reported it --- shared state looks exactly like a
 * program whose counters are running a little high.
 *
 * Keying on the name makes both behaviours explicit and separates them:
 *
 *   same name, same shape        -> SHARE the index. Deliberate, and it is what
 *                                   lets a timer program read the counters an
 *                                   entry-armed program is accumulating.
 *   same name, different shape   -> REFUSE. Two programs disagreeing about a
 *                                   shared map's layout is the one case where
 *                                   sharing corrupts, so it must not resolve.
 *   different name               -> a NEW index, i.e. private storage.
 *
 * uBPF already hands us symbol_name; the old code took it only to print it.
 */
#define LS_MAP_NAME_MAX 32u

/* Registry reset is off the data path and never waits for a reader. References
 * carry a generation, so a retained VM cannot alias a replacement's maps. */
struct ls_map_registry {
    _Atomic uint64_t generation;
    _Atomic uint32_t readers, resetting;
};
#ifdef LS_MAP_GLUE_IMPL
struct ls_map_registry g_ls_map_registry;
#else
extern struct ls_map_registry g_ls_map_registry;
#endif

static inline int
ls_map_enter(void)
{
    atomic_fetch_add(&g_ls_map_registry.readers, 1);
    if (atomic_load(&g_ls_map_registry.resetting)) {
        atomic_fetch_sub(&g_ls_map_registry.readers, 1);
        return -1;
    }
    return 0;
}

static inline void
ls_map_leave(void)
{
    atomic_fetch_sub(&g_ls_map_registry.readers, 1);
}

#include "ls_config.h"
#ifdef LS_MAP_GLUE_IMPL
struct ls_config_store g_ls_config;
__thread struct ls_config_view g_ls_config_view;
#else
extern struct ls_config_store g_ls_config;
extern __thread struct ls_config_view g_ls_config_view;
#endif

#ifdef LS_MAP_GLUE_IMPL
struct ls_map_def  g_ls_shapes[LS_MAP_MAX];
char               g_ls_names[LS_MAP_MAX][LS_MAP_NAME_MAX];
_Atomic uint32_t   g_ls_nshapes;             /* published with release ordering */
#else
extern struct ls_map_def g_ls_shapes[LS_MAP_MAX];
extern char              g_ls_names[LS_MAP_MAX][LS_MAP_NAME_MAX];
extern _Atomic uint32_t  g_ls_nshapes;
#endif

/* A pointer, mmap'd on first use --- NOT a __thread object. sizeof(struct
 * ls_map_set) is ~50 KB, and putting that in thread-local storage was both a
 * large TLS demand on every TMM thread and a direct contradiction of what this
 * file claims two paragraphs up ("mmap'd", because TMM's malloc is unusable on
 * threads it did not create). The claim was right; the code was not. */
#ifdef LS_MAP_GLUE_IMPL
__thread struct ls_map_set *g_ls_maps;
__thread int                g_ls_maps_failed;
/* WHICH SLOT IS EXECUTING, set by ls_vm_call before it enters the VM.
 *
 * uBPF's external_function_t is five uint64_t and NO context parameter --- ubpf.h warns
 * that a sixth will not match the typedef --- so a helper cannot be told which slot
 * invoked it. A thread-local is both simpler and cheaper than threading a context
 * through every call, and it is correct for the same reason the map tables are
 * per-thread: TMM is core-pinned and run-to-completion, so exactly one program is
 * executing on this thread at any instant.
 *
 * -1 when no program is running, so a helper reached from anywhere else refuses. */
__thread int                g_ls_cur_slot = -1;
#else
extern __thread struct ls_map_set *g_ls_maps;
extern __thread int                g_ls_maps_failed;
extern __thread int                g_ls_cur_slot;
#endif

/* Lazily bring this thread's storage up to the recorded shapes. Idempotent, and
 * checks the registry generation on each call. */
static inline struct ls_map_set *
ls_map_current(void)
{
    uint32_t n, i;
    uint64_t generation = atomic_load(&g_ls_map_registry.generation);
    void *p;

    if (g_ls_maps_failed)
        return 0;                     /* tried once, failed --- do not retry on
                                       * the hot path, and do not leak a mapping
                                       * per invocation */

    /* CATCH UP ON SHAPES ADDED SINCE THIS THREAD INITIALISED, and note why this
     * is not merely tidiness. Shapes are recorded at LOAD time and indices are
     * global; storage is built per thread on FIRST USE. So loading a second
     * program mid-life gives it a higher index than any thread has storage for,
     * and ls_map_get() returns NULL for it --- every lookup misses, and the
     * program behaves exactly like one whose counter never reaches its threshold.
     *
     * Observed: rate_watch worked at idx 0 on a fresh pod and silently never
     * worked at idx 1 after map_selftest had claimed idx 0. "Works on the first
     * program loaded, never on the second" is a bad failure to leave in place. */
    if (g_ls_maps != 0) {
        if (g_ls_maps->generation != generation) {
            memset(g_ls_maps, 0, sizeof *g_ls_maps);
            g_ls_maps->generation = generation;
        }
        n = atomic_load_explicit(&g_ls_nshapes, memory_order_acquire);
        for (i = g_ls_maps->n; i < n; i++) {
            if (ls_map_create(g_ls_maps, &g_ls_shapes[i]) < 0)
                return g_ls_maps;     /* table full --- existing maps still work */
        }
        return g_ls_maps;
    }

    /* ACQUIRE, paired with the release store in ls_map_reloc. Relocation runs on
     * the LOADER thread; without the pairing a data-plane thread on another core
     * has no guarantee of seeing either the count or the shapes it indexes, and
     * the failure is silent --- every lookup misses and the feature looks like a
     * map that is simply always empty. Same class as ls_vm_reload publishing vm
     * without jit_fn. */
    n = atomic_load_explicit(&g_ls_nshapes, memory_order_acquire);
    if (n == 0)
        return 0;                     /* no maps declared --- nothing to build */

    p = mmap(0, sizeof(struct ls_map_set), PROT_READ | PROT_WRITE,
             MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (p == MAP_FAILED) {
        g_ls_maps_failed = 1;
        return 0;
    }
    memset(p, 0, sizeof(struct ls_map_set));
    ((struct ls_map_set *)p)->generation = generation;

    for (i = 0; i < n; i++) {
        if (ls_map_create((struct ls_map_set *)p, &g_ls_shapes[i]) < 0) {
            munmap(p, sizeof(struct ls_map_set));
            g_ls_maps_failed = 1;     /* a shape we cannot honour --- fail safe */
            return 0;
        }
    }
    g_ls_maps = (struct ls_map_set *)p;
    return g_ls_maps;
}


/*
 * uBPF hands us the maps section and the symbol's offset within it. We read the
 * descriptor clang wrote there, check we can honour it, create the map, and
 * return the INDEX to plant in the instruction.
 *
 * Returning an index rather than a pointer is the security boundary: a program
 * never holds or supplies a host address, so validating a map reference later is
 * an integer range check and there is no forged-pointer case at all. Real BPF
 * hands programs an fd and does this work in the kernel; we get a stronger
 * arrangement for free because uBPF left relocation to the embedder.
 *
 * On refusal we return a deliberately out-of-range value. The helper's range
 * check then rejects it, so a descriptor we cannot honour yields a program whose
 * map calls all fail --- rather than one silently wired to the wrong shape, which
 * is what clamping would produce.
 */
static inline uint64_t
ls_map_reloc(void *ctx, const uint8_t *data, uint64_t data_size,
             const char *symbol_name, uint64_t symbol_offset, uint64_t symbol_size)
{
    struct ls_map_def d;
    int idx;

    if (data == 0)
        goto refused;
    if (symbol_offset > data_size || sizeof d > data_size - symbol_offset || symbol_size < sizeof d)
        goto refused;   /* truncated descriptor */

    memcpy(&d, data + symbol_offset, sizeof d);

    /* An unnamed map cannot be identified, and identity is what decides whether
     * storage is shared or private. Refuse rather than guess: a wrong guess in
     * either direction is silent. */
    if (symbol_name == 0 || symbol_name[0] == '\0')
        goto refused;
    if (strnlen(symbol_name, LS_MAP_NAME_MAX) >= LS_MAP_NAME_MAX)
        goto refused;   /* would not round-trip */

    /* ARRAY is currently the dedicated configuration view only. Its reference
     * identifies this loaded instance, not a name in the mutable hash registry.
     * A stale VM cannot use its reference to read its replacement's policy. */
    if (d.type == 2u || strcmp(symbol_name, LS_CONFIG_MAP_NAME) == 0) {
        uint64_t handle = (uint64_t)(uintptr_t)ctx;
        if (strcmp(symbol_name, LS_CONFIG_MAP_NAME) || d.type != 2u ||
            d.key_size != 4u || d.value_size != LS_CONFIG_VALUE_SIZE ||
            d.max_entries != LS_CONFIG_ROWS + 1u || d.map_flags != LS_CONFIG_MAP_FLAG ||
            !(handle & LS_CONFIG_HANDLE_BIT)) {
            g_ls_config.load_error = 1;
            goto refused;
        }
        return handle;
    }

    /* Already recorded under this NAME? clang emits one relocation per REFERENCE,
     * so the same map arrives several times --- three, in the experiment program.
     * Recording one shape per reference would exhaust the table and, worse, give
     * two references to the same declared map separate storage.
     *
     * A name match with a DIFFERENT shape is refused, not shared: the two
     * programs disagree about the layout of memory they would both write. */
    {
        uint32_t i, have = atomic_load_explicit(&g_ls_nshapes, memory_order_relaxed);
        for (i = 0; i < have; i++) {
            if (strncmp(g_ls_names[i], symbol_name, LS_MAP_NAME_MAX) != 0)
                continue;
            if (g_ls_shapes[i].type       == d.type &&
                g_ls_shapes[i].map_flags  == d.map_flags &&
                g_ls_shapes[i].key_size   == d.key_size &&
                g_ls_shapes[i].value_size == d.value_size &&
                g_ls_shapes[i].max_entries == d.max_entries)
                return (atomic_load(&g_ls_map_registry.generation) << 8) | i;
            fprintf(stderr, "ls_map: REFUSED %s --- shape disagrees with the "
                            "map already registered under that name "
                            "(have key=%u val=%u max=%u, asked key=%u val=%u max=%u)\n",
                    symbol_name,
                    g_ls_shapes[i].key_size, g_ls_shapes[i].value_size,
                    g_ls_shapes[i].max_entries,
                    d.key_size, d.value_size, d.max_entries);
            goto refused;
        }
    }

    /* Record the SHAPE only. Storage is per thread and built on first use --- see
     * ls_map_current(). Refuse here rather than at first use, so a descriptor we
     * cannot honour fails at load time where somebody is watching. */
    {
        uint32_t have = atomic_load_explicit(&g_ls_nshapes, memory_order_relaxed);
        if (!ls_map_check_descriptor(&d) || have >= LS_MAP_MAX) {
            g_ls_config.load_error = 1;
            goto refused;
        }
        idx = (int)have;
        g_ls_shapes[have] = d;
        /* Fill the shape AND THE NAME before publishing the count: a reader that
         * observes the count must be guaranteed to see the entry it indexes, and
         * the name is now part of that entry rather than a debug string. */
        memset(g_ls_names[have], 0, LS_MAP_NAME_MAX);
        memcpy(g_ls_names[have], symbol_name,
               strnlen(symbol_name, LS_MAP_NAME_MAX - 1u));
        atomic_store_explicit(&g_ls_nshapes, have + 1u, memory_order_release);
    }
    fprintf(stderr, "ls_map: reloc %s -> idx %d (key=%u val=%u max=%u)\n",
            symbol_name ? symbol_name : "?", idx,
            d.key_size, d.value_size, d.max_entries);
    return (atomic_load(&g_ls_map_registry.generation) << 8) | (uint64_t)idx;
refused:
    g_ls_config.load_error = 1;
    return (uint64_t)LS_MAP_MAX + 1u;
}

/* uBPF permits only the ctx and the stack. This extends it to map values --- and
 * note the JIT does not bounds-check at all, so without this the interpreter and
 * the JIT disagree: the program works in production and fails in test. */
/*
 * Release every recorded shape only when all slots are disabled and the
 * prepare path is idle. The loader checks those conditions before calling.
 *
 * Without this, shapes accumulate for the process lifetime: each load records
 * its own and LS_MAP_MAX is 4, so the fifth program loaded finds the table full
 * and its maps silently do not exist. Per-thread STORAGE is not reclaimed here
 * --- a data-plane thread may be inside a helper --- so the mapping is left and
 * the thread rebuilds from the new shapes on its next call. Bounded: it is one
 * mapping per thread, not per load.
 */
static inline int
ls_map_reset_shapes(void)
{
    if (atomic_exchange(&g_ls_map_registry.resetting, 1))
        return -1;
    uint64_t generation = atomic_load(&g_ls_map_registry.generation);
    if (atomic_load(&g_ls_map_registry.readers) || generation == ((1ull << 55) - 1)) {
        atomic_store(&g_ls_map_registry.resetting, 0);
        return -1; /* in-flight calls finish; generation exhaustion never wraps */
    }
    /* Clear the NAMES as well. They are identity now, so a name left behind at an
     * index the next load reuses would match a map it has nothing to do with ---
     * reintroducing exactly the cross-program aliasing the name key removes. */
    memset(g_ls_names, 0, sizeof g_ls_names);
    atomic_store_explicit(&g_ls_nshapes, 0, memory_order_release);
    atomic_store(&g_ls_map_registry.generation, generation + 1);
    atomic_store(&g_ls_map_registry.resetting, 0);
    return 0;
}

/* This runs on the thread doing the access, so ls_map_current() gives that
 * thread's own storage --- which is the only storage its program can legally
 * reach. */
static inline bool
ls_map_bounds(void *ctx, uint64_t addr, uint64_t size)
{
    (void)ctx;
    if (ls_config_addr_ok(&g_ls_config_view, addr, size))
        return true;
    struct ls_map_set *s = ls_map_current();
    return s != 0 && ls_map_addr_ok(s, addr, size) != 0;
}


/* --- the three helpers, at the ids PREVAIL already knows -----------------
 *
 * uBPF's external_function_t is FIVE uint64_t and NO context parameter --- ubpf.h
 * even warns that a 6th parameter will not match the typedef. There is a
 * dispatcher form that carries a context, but the map set is per-thread anyway,
 * so a thread-local pointer is both simpler and cheaper than threading a context
 * through every call.
 *
 * ls_map_set_current() is called once per thread when its maps are created. A
 * helper invoked on a thread that never did so finds NULL and returns failure ---
 * which is the safe direction: no map, no state, program falls through.
 */


static inline uint64_t
ls_h_map_lookup(uint64_t map, uint64_t key, uint64_t a, uint64_t b, uint64_t c)
{
    if (map & LS_CONFIG_HANDLE_BIT) {
        uint32_t index;
        if (!key) return 0;
        memcpy(&index, (const void *)(uintptr_t)key, sizeof index);
        return (uint64_t)(uintptr_t)ls_config_lookup(&g_ls_config, &g_ls_config_view,
                                                    map, index);
    }
    struct ls_map *m = ls_map_get(ls_map_current(), map);
    (void)a; (void)b; (void)c;
    if (m == 0 || key == 0)
        return 0;
    return (uint64_t)(uintptr_t)ls_map_lookup(m, (const uint8_t *)(uintptr_t)key);
}

static inline uint64_t
ls_h_map_update(uint64_t map, uint64_t key, uint64_t val, uint64_t flags, uint64_t c)
{
    if (map & LS_CONFIG_HANDLE_BIT) return (uint64_t)-1;
    struct ls_map *m = ls_map_get(ls_map_current(), map);
    (void)flags; (void)c;
    if (m == 0 || key == 0 || val == 0)
        return (uint64_t)-1;
    return (uint64_t)ls_map_update(m, (const uint8_t *)(uintptr_t)key,
                                   (const uint8_t *)(uintptr_t)val);
}

static inline uint64_t
ls_h_map_delete(uint64_t map, uint64_t key, uint64_t a, uint64_t b, uint64_t c)
{
    if (map & LS_CONFIG_HANDLE_BIT) return (uint64_t)-1;
    struct ls_map *m = ls_map_get(ls_map_current(), map);
    (void)a; (void)b; (void)c;
    if (m == 0 || key == 0)
        return (uint64_t)-1;
    return (uint64_t)ls_map_delete(m, (const uint8_t *)(uintptr_t)key);
}

/* --- readable-range cache, for bpf_probe_read ----------------------------
 *
 * WHY A RANGE CHECK AND NOT A FAULT HANDLER. bpf_probe_read must return an ERROR for a bad
 * address, never crash. The kernel gets that from its page-fault handler plus a fixup
 * table. Userspace has three options and only one of them is affordable on a poll loop:
 *
 *   range-check against cached mappings   two compares. Catches NULL, wild pointers and
 *                                         unmapped addresses --- the whole common case.
 *   process_vm_readv on self              a syscall per read. Catches everything, and is
 *                                         far too slow per invocation.
 *   SIGSEGV handler + siglongjmp          catches everything, but async-signal-safety
 *                                         inside run-to-completion, and the handler is
 *                                         PROCESS-WIDE so it collides with TMM's own crash
 *                                         handling. Not a trade to make quietly.
 *
 * So: range check. STATE THE LIMIT PLAINLY --- it does not catch a pointer that is mapped
 * but wrong. Neither does a hand-written ctx builder, which dereferences on trust today, so
 * this is not a regression; it is a bound where there was none.
 *
 * PER THREAD, like the map storage, for the same reason: no locking on the hot path. Built
 * on first use from /proc/self/maps, and REFRESHED ONCE on a miss before refusing, because
 * TMM mmaps after init (the per-thread map tables are themselves an example) and a stale
 * snapshot would refuse a legitimate read forever.
 */
#define LS_RANGES_MAX 64u

struct ls_range { uint64_t lo, hi; };

struct ls_ranges {
    struct ls_range r[LS_RANGES_MAX];
    uint32_t n;
};

#ifdef LS_MAP_GLUE_IMPL
__thread struct ls_ranges *g_ls_ranges;
__thread int               g_ls_ranges_failed;
#else
extern __thread struct ls_ranges *g_ls_ranges;
extern __thread int               g_ls_ranges_failed;
#endif

/* Parse /proc/self/maps into the readable ranges.
 *
 * Deliberately ignores any mapping without 'r' --- a write-only or guard mapping is not
 * somewhere a program may read from. Uses stdio because this runs ONCE PER THREAD at first
 * use, off the hot path; the per-invocation cost is the two compares in ls_addr_readable.
 */
static inline int
ls_ranges_load(struct ls_ranges *rs)
{
    FILE *f;
    char line[512];

    rs->n = 0;
    f = fopen("/proc/self/maps", "r");
    if (f == 0)
        return -1;
    while (rs->n < LS_RANGES_MAX && fgets(line, (int)sizeof line, f) != 0) {
        char *p = line, *q;
        uint64_t lo, hi;

        lo = strtoull(p, &q, 16);
        if (q == p || *q != '-')
            continue;
        p = q + 1;
        hi = strtoull(p, &q, 16);
        if (q == p || hi <= lo)
            continue;
        while (*q == ' ')
            q++;
        if (*q != 'r')                 /* not readable --- not our business */
            continue;
        /* Merge with the previous range when they abut. /proc/self/maps splits on permission
         * and backing changes, so a heap can appear as several adjacent readable entries and
         * a 64-slot table would otherwise fill on a large process. */
        if (rs->n > 0 && rs->r[rs->n - 1].hi == lo) {
            rs->r[rs->n - 1].hi = hi;
        } else {
            rs->r[rs->n].lo = lo;
            rs->r[rs->n].hi = hi;
            rs->n++;
        }
    }
    fclose(f);
    return rs->n ? 0 : -1;
}

/* This thread's ranges, built on first use. Returns 0 on failure, and remembers the
 * failure so a broken /proc is not retried on every invocation. */
static inline struct ls_ranges *
ls_ranges_current(int refresh)
{
    if (g_ls_ranges_failed && !refresh)
        return 0;
    if (g_ls_ranges == 0) {
        void *m = mmap(0, sizeof(struct ls_ranges), PROT_READ | PROT_WRITE,
                       MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (m == MAP_FAILED) {
            g_ls_ranges_failed = 1;
            return 0;
        }
        g_ls_ranges = (struct ls_ranges *)m;
        refresh = 1;
    }
    if (refresh) {
        if (ls_ranges_load(g_ls_ranges) != 0) {
            g_ls_ranges_failed = 1;
            return 0;
        }
        g_ls_ranges_failed = 0;
    }
    return g_ls_ranges;
}

/* Is [addr, addr+size) entirely inside ONE readable mapping?
 *
 * One mapping, not several: a read spanning two adjacent mappings is legal in principle and
 * is far more likely to be a pointer that walked off the end of something. Refusing it costs
 * a caller nothing real and removes a whole class of accident.
 *
 * On a miss the snapshot is REFRESHED ONCE and retried, because TMM mmaps after init --- the
 * per-thread map tables are themselves an example --- and a stale snapshot would refuse a
 * legitimate read forever.
 */
static inline int
ls_addr_readable(uint64_t addr, uint64_t size)
{
    int attempt;

    if (size == 0 || addr == 0)
        return 0;
    if (addr + size < addr)                 /* wrap --- refuse before doing arithmetic */
        return 0;

    for (attempt = 0; attempt < 2; attempt++) {
        struct ls_ranges *rs = ls_ranges_current(attempt);   /* 2nd pass refreshes */
        uint32_t i;
        if (rs == 0)
            return 0;
        for (i = 0; i < rs->n; i++) {
            if (addr >= rs->r[i].lo && addr + size <= rs->r[i].hi)
                return 1;
        }
    }
    return 0;
}

/* --- bpf_ktime_get_ns, helper id 5 ---------------------------------------
 *
 * WHY A CLOCK IS THE SINGLE MOST USEFUL ADDITION. Without one a program cannot know what
 * time it is, so it cannot express "N per second", any rate limit, or any decay. That is
 * why rate_watch's threshold means "this site fired more than 5 times EVER" rather than
 * recently --- the counter never resets, so safe_returns answers a question nobody asked.
 *
 * CLOCK_MONOTONIC, NOT CLOCK_REALTIME, and the difference matters. The ring record's
 * ts_ns is REALTIME because a feed has to correlate with wall-clock logs. A program doing
 * rate limiting must NOT be affected by a clock step: on a REALTIME jump backwards every
 * interval computation would go negative and every limiter would open. Two clocks for two
 * jobs, deliberately, and a program comparing its own timestamps against a record's ts_ns
 * would be comparing different clocks --- which is why programs get no access to ts_ns.
 *
 * Resolves through the vDSO, so no syscall. It is still a read on the hot path and the
 * per-call cost of it is UNMEASURED, like everything else on this path.
 */
static inline uint64_t
ls_h_ktime_get_ns(uint64_t a, uint64_t b, uint64_t c, uint64_t d, uint64_t e)
{
    struct timespec ts;
    (void)a; (void)b; (void)c; (void)d; (void)e;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 0;      /* 0 is safe: a program comparing against it sees no elapsed time */
    return (uint64_t)ts.tv_sec * 1000000000ull + (uint64_t)ts.tv_nsec;
}

/* --- bpf_ringbuf_output, helper id 130 -----------------------------------
 *
 * PROGRAM-CONTROLLED EMISSION. Until now the host published a record for every event,
 * after the program ran, so a program could not say "this one is not interesting". That
 * fixed one-record-per-event rate is what the parked timer hook existed to work around;
 * with this helper and a clock, a program does its own rate limiting and its own
 * summarising, and the timer is not needed.
 *
 * Signature is bpf_ringbuf_output(ringbuf, data, size, flags) --- id 130, which PREVAIL
 * already knows, so this costs ZERO verifier work. Verified by test 2026-08-18: a program
 * declaring a BPF_MAP_TYPE_RINGBUF map and calling id 130 passes PREVAIL unchanged.
 *
 * WHAT WE VALIDATE, AND WHAT WE CANNOT. `size` is clamped and refused above the cap. The
 * POINTER is trusted, because PREVAIL proved the program owns [data, data+size) --- and
 * that is precisely the trust uBPF's own docs/VerifiedPrograms.md warns about: "PREVAIL
 * assumes that r1 points to a valid memory region" while uBPF "doesn't enforce any
 * particular context layout" and "memory safety depends on the program". The interpreter
 * would catch a bad pointer through the bounds callback; THE JIT DOES NOT CONSULT IT, and
 * the lab runs the JIT. So the real control here is signature verification of the program
 * (scope item 4, unbuilt), not this function. Stated rather than implied.
 */
#define LS_RB_MAX_RECORD 256u   /* the drain reads into a 512-byte buffer; stay well
                                 * under it, and cap what one program can push per
                                 * invocation so a hot hook cannot flood the ring in a
                                 * single call */

static inline uint64_t
ls_h_perf_event_output(uint64_t ctx, uint64_t map, uint64_t flags, uint64_t data,
                       uint64_t size)
{
    struct ls_map *m = ls_map_get(ls_map_current(), map);

    /* ARGUMENT ORDER IS bpf_perf_event_output(ctx, map, flags, data, size). The map is
     * arg 1 and the payload is args 3 and 4 --- NOT bpf_ringbuf_output's
     * (map, data, size, flags), which this used before id 130 turned out to be outside
     * uBPF's table. Getting the order wrong would read the ctx pointer as a map index. */
    (void)ctx; (void)flags;

    /* Refuse, never clamp. A silently truncated record decodes as a short one and a
     * consumer cannot tell it from a program that meant to emit that much. */
    if (m == 0 || !m->is_ring)
        return (uint64_t)-1;          /* not an event-output map */
    if (data == 0 || size == 0 || size > LS_RB_MAX_RECORD)
        return (uint64_t)-1;
    if (g_ls_cur_slot < 0)
        return (uint64_t)-1;          /* reached from outside a program run */

    return (uint64_t)(int64_t)ls_tp_publish_raw(g_ls_cur_slot,
                                                (const void *)(uintptr_t)data,
                                                (unsigned long)size);
}

/* --- bpf_probe_read, helper id 4 -----------------------------------------
 *
 * WHY THIS IS THE MOST STRUCTURALLY IMPORTANT HELPER IN THE SET. A verified program cannot
 * chase a pointer --- PREVAIL refuses it --- so until now the HOST had to dereference and
 * hand the program flat scalars. That host code is a per-hook ctx builder written in C and
 * COMPILED INTO TMM, which means a hook with a new argument shape costs a rebuild.
 *
 * With this helper the program chases pointers itself, and the generic five-register ctx
 * covers arbitrary hooks. A new hook shape becomes a NEW PROGRAM rather than a new build:
 * minutes instead of a build cycle. That is the difference between "we can instrument
 * anything, given a rebuild" and "we can instrument anything, now".
 *
 * PREVAIL admits id 4 with every gate on --- verified before this was written, not after.
 *
 * WHAT IS AND IS NOT GUARANTEED, stated because the whole value depends on it:
 *
 *   src   RANGE-CHECKED against this thread's readable mappings. NULL, unmapped and wild
 *         pointers are refused with -1 rather than faulting. A pointer that is mapped but
 *         semantically wrong is NOT caught --- and neither is it by a hand-written ctx
 *         builder, which dereferences on trust today. This is a bound where there was none.
 *   size  capped. A program cannot ask for an unbounded copy.
 *   dst   TRUSTED, because PREVAIL proved the program owns it. Same trust the event-output
 *         helper takes, and the same reason it is the signing gate (scope item 4) that
 *         really underwrites this rather than any check here.
 *
 * The kernel's version of this helper is backed by the page-fault handler and a fixup table.
 * Ours is a range check, because the userspace alternatives are a syscall per read (far too
 * slow on a poll loop) or a process-wide SIGSEGV handler with siglongjmp (async-signal-safety
 * inside run-to-completion, colliding with TMM's own crash handling). The range check is the
 * affordable 95%, and saying which 5% it misses is the point of this comment.
 */
#define LS_PROBE_READ_MAX 256u

static inline uint64_t
ls_h_probe_read(uint64_t dst, uint64_t size, uint64_t src, uint64_t d, uint64_t e)
{
    (void)d; (void)e;

    if (dst == 0 || src == 0 || size == 0)
        return (uint64_t)-1;
    if (size > LS_PROBE_READ_MAX)
        return (uint64_t)-1;          /* refuse, never clamp --- a short read is
                                       * indistinguishable from a program that meant it */
    if (!ls_addr_readable(src, size))
        return (uint64_t)-1;

    memcpy((void *)(uintptr_t)dst, (const void *)(uintptr_t)src, (size_t)size);
    return 0;
}

/* Assert the helper signatures really match uBPF's, so a future edit that adds a
 * parameter fails the build rather than corrupting arguments at run time. */
static inline void
ls_map_glue_abi_check(void)
{
    external_function_t f;
    f = (external_function_t)ls_h_map_lookup; (void)f;
    f = (external_function_t)ls_h_map_update; (void)f;
    f = (external_function_t)ls_h_map_delete; (void)f;
    f = (external_function_t)ls_h_ktime_get_ns; (void)f;
    f = (external_function_t)ls_h_perf_event_output; (void)f;
    f = (external_function_t)ls_h_probe_read; (void)f;
}

/*
 * THE ONE CALL. Every VM that will run a program with maps goes through here,
 * before ubpf_load_elf_ex --- see the ordering note in the banner. Returns 0, or
 * -1 with a reason on stderr.
 *
 * Registration is all-or-nothing on purpose. A VM with the relocation callback
 * but no bounds check would resolve map indices and then refuse every read of a
 * value; a VM with helpers but no relocation would hand every helper map=0. Both
 * produce a program that loads, verifies and runs while its maps do nothing. So a
 * partial install is treated as a failed install.
 */
static inline int
ls_map_glue_install(struct ubpf_vm *vm)
{
    if (vm == 0)
        return -1;

    /* Order: relocation first, because ubpf_load_elf_ex walks the maps section
     * and consults it there. Registered afterwards it is simply never asked. */
    g_ls_config.load_error = 0;
    if (ubpf_register_data_relocation(vm, (void *)(uintptr_t)g_ls_config.loading,
                                      ls_map_reloc) != 0) {
        fprintf(stderr, "ls_map: relocation callback refused\n");
        return -1;
    }
    if (ubpf_register_data_bounds_check(vm, 0, ls_map_bounds) != 0) {
        fprintf(stderr, "ls_map: bounds callback refused\n");
        return -1;
    }

    /* ids 1/2/3 with the standard names and semantics, which is what lets
     * PREVAIL verify these programs with no platform work at all. */
    if (ubpf_register(vm, 1, "bpf_map_lookup_elem",
                      (external_function_t)ls_h_map_lookup) != 0 ||
        ubpf_register(vm, 2, "bpf_map_update_elem",
                      (external_function_t)ls_h_map_update) != 0 ||
        ubpf_register(vm, 3, "bpf_map_delete_elem",
                      (external_function_t)ls_h_map_delete) != 0) {
        fprintf(stderr, "ls_map: helper registration refused\n");
        return -1;
    }

    /* ids 5 and 130, again with the standard names and semantics so PREVAIL needs no
     * platform work. All-or-nothing with the three above: a VM that resolved a ringbuf
     * map and then had no helper to emit through would give a program that verifies,
     * runs, and silently drops everything it tried to publish. */
    /* EVERY ID MUST BE INSIDE uBPF'S TABLE, asserted at COMPILE time. ubpf_register
     * refuses idx >= UBPF_MAX_EXT_FUNCS (64 by default, ubpf.h:72) and returns -1, which
     * all-or-nothing turns into a total install failure. An image shipped that way on
     * 2026-08-18: bpf_ringbuf_output's id is 130, so NO helper registered at all, every
     * program load was refused and even the built-in shield never armed. Loud, which is
     * what all-or-nothing is for --- but a build failure is better than loud. */
    _Static_assert(4  < UBPF_MAX_EXT_FUNCS, "bpf_probe_read id outside uBPF's table");
    _Static_assert(5  < UBPF_MAX_EXT_FUNCS, "bpf_ktime_get_ns id outside uBPF's table");
    _Static_assert(25 < UBPF_MAX_EXT_FUNCS, "bpf_perf_event_output id outside the table");
    _Static_assert(1  < UBPF_MAX_EXT_FUNCS && 2 < UBPF_MAX_EXT_FUNCS
                   && 3 < UBPF_MAX_EXT_FUNCS, "map helper ids outside uBPF's table");

    if (ubpf_register(vm, 4, "bpf_probe_read",
                      (external_function_t)ls_h_probe_read) != 0 ||
        ubpf_register(vm, 5, "bpf_ktime_get_ns",
                      (external_function_t)ls_h_ktime_get_ns) != 0 ||
        ubpf_register(vm, 25, "bpf_perf_event_output",
                      (external_function_t)ls_h_perf_event_output) != 0) {
        fprintf(stderr, "ls_map: probe-read/clock/event-output registration refused\n");
        return -1;
    }

    ls_map_glue_abi_check();     /* compile-time signature pin, no run cost */
    return 0;
}

#endif /* LS_MAP_GLUE_H */

ls_ring.h.text:
/* ls_ring.h --- the egress ring. One variable-length class, SPSC, shm-backed.
 *
 * Implements data-plane-egress-primitives.md sections 5.1-5.5. Header-only so the
 * producer side can be inlined into the trampoline and the consumer side compiled
 * into a separate drain process from the same source --- one definition of the
 * layout, which is the only way the two stay in agreement.
 *
 * THE PROPERTY THIS EXISTS TO PRESERVE: the transport never inspects the payload.
 * A record is a length and some bytes. Whether those bytes are a ctx struct, a
 * byte window, or a derived feature vector is invisible here, which is what lets a
 * new tracepoint be a new schema id rather than new plumbing.
 *
 * WRAPAROUND: pad-to-end with a DISCARD record, NOT a double mapping. The kernel's
 * ringbuf maps its data area twice so a record can straddle the end transparently;
 * that needs MAP_FIXED trickery over the shm fd. Padding is simpler, portable, and
 * costs one skipped header per wrap --- and the consumer already handles DISCARD,
 * so it adds no new path. This answers section 8's "pow2+mask or a true bip-buffer"
 * question with a third, cheaper option; revisit if the padding waste ever matters.
 *
 * ORDERING is specified by semantics, not per architecture (section 5.2): positions
 * and the header word are _Atomic, accessed with acquire/release, so the payload
 * memcpy is part of the release and cannot become visible after the commit. On
 * x86-64 that lowers to plain accesses plus a compiler barrier; on aarch64 to
 * ldar/stlr. Same source, no #ifdef.
 */
#ifndef LS_RING_H
#define LS_RING_H

#include <stdatomic.h>
#include <stdint.h>
#include <string.h>

#define LS_RING_MAGIC     0x4c53524e47303031ull   /* "LSRNG001" */
#define LS_RING_HDR_SZ    8u                       /* kernel BPF-ringbuf record header */
#define LS_RING_BUSY      (1u << 31)               /* producer is mid-write */
#define LS_RING_DISCARD   (1u << 30)               /* consumer must skip this record */
#define LS_RING_LEN_MASK  (~(LS_RING_BUSY | LS_RING_DISCARD))
#define LS_RING_ALIGN     8u

/* Policy is declared at creation and is NOT interchangeable (section 5.1):
 * a flight recorder must overwrite its oldest record or its dump holds the state
 * of the box long before the incident; a streaming drain must never overwrite or
 * a consumer has records pulled out from under it mid-read. */
enum ls_ring_policy {
    LS_RING_STREAM = 0,   /* full -> drop the new record and count it */
    LS_RING_RECORD = 1    /* full -> overwrite the oldest; never blocks, never drops */
};

/* The control block, at offset 0 of the shared segment. The data area follows,
 * `data_size` bytes, which MUST be a power of two so positions mask cleanly. */
struct ls_ring {
    uint64_t magic;
    uint32_t version;
    uint32_t policy;
    uint32_t data_size;              /* power of two                                */
    uint32_t _pad;
    _Atomic uint64_t producer_pos;   /* monotonic byte position; masked into data   */
    _Atomic uint64_t consumer_pos;   /* STREAM only; RECORD never consults a reader */
    _Atomic uint64_t drops;          /* STREAM only (section 5.5)                   */
    _Atomic uint64_t drop_bytes;
};

/* Our record header, inside the payload the transport carries. The transport does
 * not read these fields; the CONSUMER uses hook_id+schema_id to find a layout in
 * the hook map. Kept fixed and small so a drain can index records without a schema. */
struct ls_rec {
    uint32_t hook_id;
    uint32_t schema_id;
    uint64_t seq;
    /* THE SLOT THE PROGRAM RAN IN --- renamed from tmm_id 2026-08-18, because that is
     * what has always been written here. The only producer passes (unsigned)slot, and
     * the drain emitted it as "tmm", so every record claimed a TMM instance number and
     * carried a slot. Every live record read "tmm":5 on both pods for the obvious
     * reason: slot 5 is where rst_why was armed.
     *
     * Nothing detected it because both are small integers and 5 is a plausible TMM id.
     * The BYTE layout is unchanged --- same offset, same width --- so a consumer walking
     * records is unaffected; only the JSON key changes, and it changes because the old
     * one was a false statement.
     *
     * A real TMM instance id would be worth having and is NOT available here: `tid`
     * lives in TMM's -nostdinc include world and this file is STDINC. It would need the
     * same kind of cross-include-world crossing the retired cookie helpers used. */
    uint32_t slot;
    uint32_t len;                    /* payload bytes following this header         */
    uint64_t ts_ns;                  /* CLOCK_REALTIME at capture, ns since epoch   */
};

/* WHY ts_ns LIVES HERE AND NOT IN THE PAYLOAD. It describes the capture, not the
 * thing captured, so it belongs with hook_id and seq rather than inside any one
 * hook's record --- which means an HTTP/2 or HTTP/3 call site inherits it without
 * a second schema bump. seq gives ordering; a clock is what lets a feed compute
 * rate, correlate with other systems, and detect a stalled producer. */

static inline uint8_t *ls_ring_data(struct ls_ring *r) { return (uint8_t *)(r + 1); }
static inline uint32_t ls_ring_round(uint32_t n) { return (n + LS_RING_ALIGN - 1) & ~(LS_RING_ALIGN - 1); }

static inline void
ls_ring_init(struct ls_ring *r, uint32_t data_size, enum ls_ring_policy policy)
{
    memset(r, 0, sizeof *r);
    r->magic = LS_RING_MAGIC;
    r->version = 1;
    r->policy = (uint32_t)policy;
    r->data_size = data_size;
    atomic_store_explicit(&r->producer_pos, 0, memory_order_relaxed);
    atomic_store_explicit(&r->consumer_pos, 0, memory_order_relaxed);
}

/* Write one record. Returns 1 if it landed, 0 if dropped (STREAM, ring full).
 *
 * The whole producer is this function: bounded memcpy, two ordered stores, no
 * allocation, no syscall, no lock. That is the property the hot path depends on
 * and the one check_ring asserts by construction rather than by inspection. */
static inline int
ls_ring_emit(struct ls_ring *r, const struct ls_rec *rec, const void *payload, uint32_t len)
{
    uint8_t *data = ls_ring_data(r);
    const uint32_t ds = r->data_size;
    const uint32_t need = ls_ring_round(LS_RING_HDR_SZ + (uint32_t)sizeof *rec + len);

    if (need > ds)
        return 0;                                        /* never fits; not a drop of THIS ring's making */

    uint64_t prod = atomic_load_explicit(&r->producer_pos, memory_order_relaxed);
    uint32_t off  = (uint32_t)(prod & (ds - 1));

    /* Pad to the end rather than straddle. One DISCARD record, which the consumer
     * already knows how to skip --- see the header note on wraparound. */
    if (off + need > ds) {
        uint32_t pad = ds - off;
        if (pad >= LS_RING_HDR_SZ) {
            uint32_t phdr = (pad - LS_RING_HDR_SZ) | LS_RING_DISCARD;
            memcpy(data + off, &phdr, 4);
            uint32_t aux = 0; memcpy(data + off + 4, &aux, 4);
        }
        prod += pad;
        atomic_store_explicit(&r->producer_pos, prod, memory_order_release);
        off = 0;
    }

    if (r->policy == LS_RING_STREAM) {
        uint64_t cons = atomic_load_explicit(&r->consumer_pos, memory_order_acquire);
        if (prod - cons + need > ds) {                    /* would overwrite unconsumed data */
            atomic_fetch_add_explicit(&r->drops, 1, memory_order_relaxed);
            atomic_fetch_add_explicit(&r->drop_bytes, len, memory_order_relaxed);
            return 0;
        }
    }
    /* RECORD never checks: full means overwrite-oldest, so reserve cannot fail. */

    /* The header word is accessed AS AN ATOMIC, not as bytes plus a standalone
     * barrier. Section 5.2 specifies it that way and it matters twice over: the
     * release attaches to the store that publishes the record, which is the
     * pairing the consumer's acquire needs; and ThreadSanitizer can model it,
     * whereas a bare standalone barrier it cannot model at all. An earlier
     * version here used memcpy plus a barrier and was therefore unverifiable. */
    _Atomic uint32_t *hdrp = (_Atomic uint32_t *)(void *)(data + off);
    uint32_t body = (uint32_t)sizeof *rec + len;

    atomic_store_explicit(hdrp, body | LS_RING_BUSY, memory_order_relaxed);
    uint32_t aux = 0; memcpy(data + off + 4, &aux, 4);

    memcpy(data + off + LS_RING_HDR_SZ, rec, sizeof *rec);
    if (len)
        memcpy(data + off + LS_RING_HDR_SZ + sizeof *rec, payload, len);

    /* Publish: this release makes the payload above visible to any consumer that
     * acquires this same word. */
    atomic_store_explicit(hdrp, body, memory_order_release);
    atomic_store_explicit(&r->producer_pos, prod + need, memory_order_release);
    return 1;
}

/* Consume one record. Returns the payload length and fills *rec, or -1 when the
 * ring is empty or the next record is still BUSY. DISCARD records are skipped
 * transparently, which is what makes the pad-to-end wrap invisible to callers. */
static inline int
ls_ring_consume(struct ls_ring *r, struct ls_rec *rec, void *out, uint32_t out_max)
{
    uint8_t *data = ls_ring_data(r);
    const uint32_t ds = r->data_size;

    for (;;) {
        uint64_t cons = atomic_load_explicit(&r->consumer_pos, memory_order_relaxed);
        uint64_t prod = atomic_load_explicit(&r->producer_pos, memory_order_acquire);
        if (cons >= prod)
            return -1;                                   /* empty */

        uint32_t off = (uint32_t)(cons & (ds - 1));
        _Atomic uint32_t *hdrp = (_Atomic uint32_t *)(void *)(data + off);
        uint32_t hdr = atomic_load_explicit(hdrp, memory_order_acquire);
        if (hdr & LS_RING_BUSY)
            return -1;                                   /* producer mid-write; try later */

        uint32_t body = hdr & LS_RING_LEN_MASK;
        uint32_t step = ls_ring_round(LS_RING_HDR_SZ + body);

        if (hdr & LS_RING_DISCARD) {                     /* padding, or an abandoned record */
            atomic_store_explicit(&r->consumer_pos, cons + step, memory_order_release);
            continue;
        }
        if (body < sizeof *rec)
            return -1;                                   /* structurally invalid; do not trust it */

        memcpy(rec, data + off + LS_RING_HDR_SZ, sizeof *rec);
        uint32_t plen = body - (uint32_t)sizeof *rec;
        if (plen > out_max)
            plen = out_max;
        if (plen)
            memcpy(out, data + off + LS_RING_HDR_SZ + sizeof *rec, plen);

        atomic_store_explicit(&r->consumer_pos, cons + step, memory_order_release);
        return (int)plen;
    }
}

/* Wire-layout assertions. These are the reason section 6's framing-compatibility
 * claim is enforced rather than merely described: an 8-byte record header with the
 * length in the low bits and BUSY/DISCARD in bits 31/30 is what a stock libbpf
 * ring_buffer consumer walks. */
_Static_assert(LS_RING_HDR_SZ == 8, "kernel BPF-ringbuf record header is 8 bytes");
_Static_assert(LS_RING_BUSY == 0x80000000u, "BUSY is bit 31, as in the kernel");
_Static_assert(LS_RING_DISCARD == 0x40000000u, "DISCARD is bit 30, as in the kernel");
_Static_assert(sizeof(struct ls_rec) == 32, "ls_rec is fixed at 32 bytes (24 + ts_ns)");
_Static_assert(sizeof(struct ls_ring) % 8 == 0, "control block keeps the data area 8-aligned");

#endif /* LS_RING_H */

ls_snapshot.h.text:
/* Completion-only context. No application pointer is writable through it. */
#ifndef LS_SNAPSHOT_H
#define LS_SNAPSHOT_H

#define LS_SNAPSHOT_SECTION "fexit/snapshot/"
#define LS_SNAPSHOT_PREFIX_LEN 15u
#define LS_SNAPSHOT_ENTRY 1u
#define LS_SNAPSHOT_RETURN 2u
#define LS_SNAPSHOT_CAPTURED 1u

struct ls_snapshot_ctx {
    __UINT64_TYPE__ arg[5];
    __UINT64_TYPE__ no_return;
    __UINT32_TYPE__ phase;
    __UINT32_TYPE__ flags;
    __UINT64_TYPE__ sequence;
    __UINT64_TYPE__ state[4];
};
_Static_assert(sizeof(struct ls_snapshot_ctx) == 96, "snapshot context size");
_Static_assert(__builtin_offsetof(struct ls_snapshot_ctx, state) == 64,
               "snapshot state offset");

/* Host-only identity. Bytecode cannot change it through its private context. */
struct ls_snapshot_id {
    __UINT64_TYPE__ instance;
    __UINT64_TYPE__ epoch;
};
#endif

ls_target.h.text:
/* Build-resolved attachment record. It lives in .ls.target in the program ELF,
 * hence inside the SHA-256 authenticated by the existing Ed25519 binding. No
 * wire-layout change and no function/type catalog on the deployed host.
 *
 * Version 1 deliberately admits only ELF64 little-endian ET_EXEC x86-64 targets
 * with a 20-byte GNU build ID and a +0/+4 five-NOP entry pad. PIE needs a separate
 * load-bias contract. Return ABI/unwind admission remains the signer's job.
 */
#ifndef LS_TARGET_H
#define LS_TARGET_H
#include <elf.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include "ls_snapshot.h"

#define LS_TARGET_SECTION ".ls.target"
#define LS_TARGET_MAGIC "LSTARG1"
#define LS_TARGET_SNAPSHOT_MAGIC "LSTARG2"
struct ls_target {
    char magic[8];
    char build_id[40];             /* full lowercase GNU build ID, no terminator */
    uint64_t entry;                /* function entry, NOT the +4 patch address */
    uint8_t is_exit;
    uint8_t pad_offset;
    uint8_t reserved[6];
};
_Static_assert(sizeof(struct ls_target) == 64, "target record size");
_Static_assert(offsetof(struct ls_target, entry) == 48, "target entry offset");

static int
ls_target_span(size_t len, uint64_t off, uint64_t size)
{
    return off <= len && size <= len - off;
}

/* Parse only bounded bytes, including section names; reject duplicate records.
 * Called after signature verification, but a signed malformed ELF still fails. */
static int
ls_target_parse(const void *elf, size_t len, const char *section,
                const char *build, struct ls_target *out)
{
    const unsigned char *p = elf;
    Elf64_Ehdr e;
    Elf64_Shdr strings, sh;
    unsigned records = 0, programs = 0;
    if (len < sizeof e) return -1;
    memcpy(&e, p, sizeof e);
    if (memcmp(e.e_ident, ELFMAG, SELFMAG) || e.e_ident[EI_CLASS] != ELFCLASS64 ||
        e.e_ident[EI_DATA] != ELFDATA2LSB || e.e_machine != EM_BPF ||
        e.e_type != ET_REL || e.e_shentsize != sizeof sh ||
        !e.e_shnum || e.e_shstrndx >= e.e_shnum ||
        !ls_target_span(len, e.e_shoff, (uint64_t)e.e_shnum * sizeof sh)) return -1;
    memcpy(&strings, p + e.e_shoff + e.e_shstrndx * sizeof sh, sizeof sh);
    if (strings.sh_type != SHT_STRTAB ||
        !ls_target_span(len, strings.sh_offset, strings.sh_size)) return -1;
    for (unsigned i = 0; i < e.e_shnum; i++) {
        memcpy(&sh, p + e.e_shoff + i * sizeof sh, sizeof sh);
        if (sh.sh_name >= strings.sh_size) return -1;
        const char *name = (const char *)p + strings.sh_offset + sh.sh_name;
        if (!memchr(name, 0, strings.sh_size - sh.sh_name)) return -1;
        if (!strncmp(name, "fentry/", 7) || !strncmp(name, "fexit/", 6)) {
            if (strcmp(name, section)) return -1;
            programs++;
        }
        if (strcmp(name, LS_TARGET_SECTION)) continue;
        if (++records != 1 || sh.sh_type != SHT_PROGBITS ||
            sh.sh_size != sizeof *out || (sh.sh_flags & SHF_EXECINSTR) ||
            !ls_target_span(len, sh.sh_offset, sh.sh_size)) return -1;
        memcpy(out, p + sh.sh_offset, sizeof *out);
    }
    int snapshot = strncmp(section, LS_SNAPSHOT_SECTION,
                           LS_SNAPSHOT_PREFIX_LEN) == 0;
    if (records != 1 || programs != 1 || !build || strlen(build) != 40 ||
        memcmp(out->magic, snapshot ? LS_TARGET_SNAPSHOT_MAGIC :
                                     LS_TARGET_MAGIC, 8) ||
        (snapshot && !section[LS_SNAPSHOT_PREFIX_LEN]) ||
        memcmp(out->build_id, build, 40) || !out->entry ||
        out->is_exit > 1 || out->is_exit != (strncmp(section, "fexit/", 6) == 0) ||
        (out->pad_offset != 0 && out->pad_offset != 4)) return -1;
    for (unsigned i = 0; i < sizeof out->reserved; i++)
        if (out->reserved[i]) return -1;
    return 0;
}

/* Check the signed address against the executing file's executable segments and
 * original pad bytes before any direct dereference of that address is allowed.
 * Read the file, not mutable live text: same-target program replacement can
 * happen while the entry is patched. ls_arm_live separately checks live NOPs. */
static int
ls_target_check_file(const char *path, const struct ls_target *t)
{
    Elf64_Ehdr e;
    Elf64_Phdr ph;
    unsigned char bytes[9];
    const unsigned char expected[9] = {0xf3,0x0f,0x1e,0xfa,0x90,0x90,0x90,0x90,0x90};
    size_t need = t->pad_offset + 5;
    int rc = -1, fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    if (pread(fd, &e, sizeof e, 0) != sizeof e ||
        memcmp(e.e_ident, ELFMAG, SELFMAG) || e.e_ident[EI_CLASS] != ELFCLASS64 ||
        e.e_ident[EI_DATA] != ELFDATA2LSB || e.e_type != ET_EXEC ||
        e.e_machine != EM_X86_64 || e.e_phentsize != sizeof ph ||
        e.e_phoff > INT64_MAX || e.e_phnum > 1024 ||
        (t->pad_offset != 0 && t->pad_offset != 4)) goto out;
    for (unsigned i = 0; i < e.e_phnum; i++) {
        uint64_t off = e.e_phoff + (uint64_t)i * sizeof ph;
        if (off > INT64_MAX || pread(fd, &ph, sizeof ph, (off_t)off) != sizeof ph) goto out;
        if (ph.p_type != PT_LOAD || !(ph.p_flags & PF_X) || t->entry < ph.p_vaddr) continue;
        uint64_t delta = t->entry - ph.p_vaddr;
        if (delta > ph.p_filesz || need > ph.p_filesz - delta ||
            ph.p_offset > INT64_MAX || delta > INT64_MAX - ph.p_offset) continue;
        if (pread(fd, bytes, need, (off_t)(ph.p_offset + delta)) != (ssize_t)need) goto out;
        rc = memcmp(bytes, expected + (t->pad_offset ? 0 : 4), need) ? -1 : 0;
        break;
    }
out:
    close(fd);
    return rc;
}
#endif

ls_tp_ring.h.text:
/* ls_tp_ring.h --- the shared-memory segment the tracepoint publishes into.
 *
 * ls_ring.h is the ring: lock-free, bounded, 15 assertions, TSan clean. It has
 * never run inside TMM. This file is the missing half --- the segment that holds
 * the rings, who creates it, and which ring a given thread writes to.
 *
 * WHY SHARED MEMORY IS FORCED, NOT PREFERRED. TMM aliases malloc to a per-core
 * allocator whose spinlock is never initialised on a thread TMM did not create,
 * so a drain agent that allocates spins forever. Everything here is mmap.
 * Equally, the consumer must live in another process: a broker client linked
 * into TMM would put a socket, a reconnect and a stalled subscriber inside the
 * poll loop. TMM writes bytes and forgets; the agent maps them read-only and
 * publishes. It can crash without TMM noticing.
 *
 * ONE RING PER THREAD, BY CONSTRUCTION. ls_ring.h is single-producer --- that is
 * what lets it be lock-free, and it is a correctness precondition, not a
 * performance note. g_slots in ls_vm.c is a plain process-global despite
 * ls_prep.c describing "per-thread VM state", and the TMM process here runs
 * three threads. Whether more than one reaches the tracepoint is exactly the
 * kind of thing that has been assumed wrongly before, so each thread claims its
 * own ring by atomic index and writes only to that. The precondition then holds
 * whatever the thread model turns out to be.
 *
 * OFF UNLESS ASKED. Nothing here allocates, maps or executes unless LS_TP_RING
 * names a segment --- the same discipline as the loader socket. The shipped path
 * is a load of one pointer and a branch.
 */
#ifndef LS_TP_RING_H
#define LS_TP_RING_H

#include <fcntl.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>

#include "ls_tp.h"
#include "ls_ring.h"

#define LS_TP_SEG_MAGIC   0x4c53534547303031ull   /* "LSSEG001" */
/* Segment format version. ls_rec gained ts_ns, so a consumer built against
 * version 1 walks records at the wrong stride --- it must be REFUSED, not left to
 * decode plausible garbage. Checked in ls_tp_seg_open below. */
#define LS_TP_SEG_VERSION   2u
#define LS_TP_MAX_RINGS    16u
#define LS_TP_RING_BYTES   (64u * 1024u)          /* power of two --- ls_ring requires it */

/* Hook and schema identity live in ls_tp.h --- they are part of the
 * ls_tp_dispatch() contract, and the trampoline needs them without
 * dragging mmap and stdatomic in. */

/* Segment header, at offset 0. Rings follow at a fixed stride so a consumer can
 * find ring i without walking anything. */
struct ls_tp_seg {
    uint64_t magic;
    uint32_t version;
    uint32_t n_rings;
    uint32_t ring_stride;            /* bytes from one ring's start to the next */
    uint32_t ring_data_size;
    _Atomic uint32_t claimed;        /* how many threads have taken a ring      */
    uint32_t _pad;
};

#define LS_TP_STRIDE  ((uint32_t)sizeof(struct ls_ring) + LS_TP_RING_BYTES)
#define LS_TP_SEG_SZ  ((size_t)sizeof(struct ls_tp_seg) + \
                       (size_t)LS_TP_MAX_RINGS * LS_TP_STRIDE)

static inline struct ls_ring *
ls_tp_seg_ring(struct ls_tp_seg *s, uint32_t i)
{
    return (struct ls_ring *)((uint8_t *)s + sizeof(struct ls_tp_seg)
                              + (size_t)i * s->ring_stride);
}

/*
 * Create and map the segment. Idempotent and safe to call from every thread:
 * the loser of the race unmaps its own view and takes the winner's.
 *
 * Returns NULL when disabled or on any failure. EVERY failure path here is
 * non-fatal by design --- telemetry that can prevent TMM from starting is worse
 * than no telemetry.
 */
static inline struct ls_tp_seg *
ls_tp_seg_open(const char *path, int create)
{
    int fd, i;
    void *p;
    struct ls_tp_seg *s;

    if (path == NULL || *path == '\0')
        return NULL;

    fd = open(path, create ? (O_RDWR | O_CREAT) : O_RDWR, 0600);
    if (fd < 0)
        return NULL;

    if (create && ftruncate(fd, (off_t)LS_TP_SEG_SZ) != 0) {
        close(fd);
        return NULL;
    }

    p = mmap(NULL, LS_TP_SEG_SZ, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    close(fd);                        /* the mapping keeps the object alive */
    if (p == MAP_FAILED)
        return NULL;

    s = (struct ls_tp_seg *)p;
    if (!create) {
        if (s->magic != LS_TP_SEG_MAGIC || s->version != LS_TP_SEG_VERSION ||
            s->ring_stride != LS_TP_STRIDE) {
            munmap(p, LS_TP_SEG_SZ);
            return NULL;             /* wrong magic, wrong version, or wrong geometry */
        }
        return s;
    }

    /* Initialise every ring before publishing the magic, so a consumer that
     * opens mid-setup either sees no segment or sees a complete one. */
    s->version        = LS_TP_SEG_VERSION;
    s->n_rings        = LS_TP_MAX_RINGS;
    s->ring_stride    = LS_TP_STRIDE;
    s->ring_data_size = LS_TP_RING_BYTES;
    atomic_store_explicit(&s->claimed, 0, memory_order_relaxed);
    for (i = 0; i < (int)LS_TP_MAX_RINGS; i++)
        ls_ring_init(ls_tp_seg_ring(s, (uint32_t)i), LS_TP_RING_BYTES,
                     LS_RING_STREAM);

    /* STREAM, not RECORD, and the choice matters. A streaming analytic feed must
     * never have a record pulled out from under a mid-read consumer, and the
     * data plane must never wait on that consumer. Full therefore means drop the
     * NEW record and count it --- a counted gap, never a silent one, and never
     * backpressure into the poll loop. */

    __atomic_store_n(&s->magic, LS_TP_SEG_MAGIC, __ATOMIC_RELEASE);
    return s;
}

/*
 * The calling thread's own ring, claimed once and remembered.
 *
 * __thread rather than an index derived from a TMM thread id: the id is not
 * available in this include world, and a wrong index would silently give two
 * threads the same ring --- which does not crash, it corrupts records
 * occasionally, which is the worst way for this to be wrong.
 */
static inline struct ls_ring *
ls_tp_my_ring(struct ls_tp_seg *s)
{
    static __thread struct ls_ring *mine;
    static __thread int tried;
    uint32_t idx;

    if (mine != NULL || tried)
        return mine;
    tried = 1;                        /* claim at most once, even on failure */

    if (s == NULL)
        return NULL;

    idx = atomic_fetch_add_explicit(&s->claimed, 1, memory_order_relaxed);
    if (idx >= s->n_rings)
        return NULL;                  /* more threads than rings: this one is silent */

    mine = ls_tp_seg_ring(s, idx);
    return mine;
}

/*
 * Publish one record. Returns 1 if it landed, 0 if dropped or disabled.
 *
 * The entire cost on the hot path: a bounded memcpy and two ordered stores. No
 * allocation, no syscall, no lock --- which is the property that makes this
 * acceptable in a poll loop at all, and the one check_ring asserts by
 * construction rather than by inspection.
 */
static inline int
ls_tp_ring_publish(struct ls_tp_seg *seg, uint32_t hook_id, uint32_t schema_id,
                   uint32_t slot, uint64_t seq, uint64_t ts_ns,
                   const void *rec, uint32_t len)
{
    struct ls_ring *r = ls_tp_my_ring(seg);
    struct ls_rec h;

    if (r == NULL)
        return 0;

    h.hook_id   = hook_id;
    h.schema_id = schema_id;
    h.seq       = seq;
    h.slot      = slot;
    h.len       = len;
    h.ts_ns     = ts_ns;
    return ls_ring_emit(r, &h, rec, len);
}

#endif /* LS_TP_RING_H */

ls_tramp.c.text:
/*
 * ls_tramp.c --- the C half of the patched-entry trampoline.
 *
 * The assembly in trampoline_x86_64.S is generic: it saves the ABI's argument
 * registers, calls this, and acts on the verdict. Everything PER-HOOK lives
 * here, in C, because the ctx layout is generated from the build's DWARF
 * (development-scope.md item 6) and changes whenever a hooked function's
 * signature does. Putting it in assembly would mean regenerating assembly per
 * hook, which is the cost this split exists to avoid.
 *
 * Status: LIVE. ls_tramp_dispatch is reached from a patched function entry on every
 * armed hook, on a running TMM under traffic. This comment read "candidate artifact...
 * Nothing calls it" until 2026-08-18 --- true before arming was built, and the opposite
 * of true since.
 */

#include "ls_vm.h"
#include "ls_arm.h"

/* Slot numbers live in ls_slots.h, checked for collisions by the compiler. They
 * were here as a bare macro whose value (0, the shield slot) contradicted the
 * comment above it (7) --- so slot 0 got the parse ctx instead of the generic
 * register ctx. See ls_slots.h. */

#include <stdint.h>
#include <string.h>

/* What the assembly expects back. rax carries this; rdx carries the safe value
 * when it is 1. Kept as plain ints because the asm reads eax. */
#define LS_TRAMP_FALLTHROUGH 0
#define LS_TRAMP_SAFE_RETURN 1

/*
 * Called with the hooked function's first five integer arguments, exactly as
 * the ABI delivered them, before its prologue ran.
 *
 * The returned safe_value is what the hooked function's caller should see if we
 * skip the body; the assembly moves it to rax. What counts as safe is per-hook
 * and belongs to the safe-return policy table (item 7); a slot carries its own.
 *
 * Returns LS_TRAMP_SAFE_RETURN to skip the hooked function entirely.
 */
/*
 * Returned in rax:rdx by the System V ABI --- which is precisely the pair the
 * assembly reads. An earlier draft took a seventh `uint64_t *safe_out`
 * argument; the ABI puts a seventh argument on the STACK, while the call site
 * passes only six registers, so the callee would have dereferenced whatever
 * happened to be at that address. Returning the pair removes the mismatch by
 * construction rather than by both sides remembering the same convention.
 */
/* struct ls_tramp_result lives in ls_arm.h */

struct ls_tramp_result
ls_tramp_dispatch(int slot, const struct ls_regs *regs)
{
    struct ls_tramp_result r = { LS_TRAMP_FALLTHROUGH, 0 };

    /*
     * ALL SIX arguments, via a pointer to the block the trampoline already saved
     * (Phase 3). The named accessors in ls_arm.h exist because the block is in
     * STACK order, which is the reverse of ABI order --- indexing it by argument
     * position would silently swap arguments rather than fail.
     *
     * regs is NULL only if something other than the trampoline called this. Guard
     * rather than trust: a fall-through is always a safe answer.
     */
    uint64_t a0, a1, a2, a3, a4;

    if (regs == 0)
        return r;

    a0 = LS_ARG0(regs);
    a1 = LS_ARG1(regs);
    a2 = LS_ARG2(regs);
    a3 = LS_ARG3(regs);
    a4 = LS_ARG4(regs);
    /*
     * The ctx is a per-invocation stack copy, never a view onto the argument
     * registers or onto TMM state. PREVAIL cannot express a read-only region,
     * so a verified program can write every byte of what it is handed
     * (finding O1); handing it the live frame would make the safety mechanism
     * an argument-injection primitive.
     *
     * PREVAIL's tracing descriptor permits 96 bytes, even though the argument
     * payload is only 40. Allocate and initialise the entire verified region;
     * otherwise a verified JIT load/store can reach this function's own frame.
     * The reserved tail is reset on EVERY invocation, including after a program
     * writes it. Existing programs retain their five argument offsets.
     */
    struct ls_ctx_generic ctx = {0};

    ctx.arg[0] = a0;
    ctx.arg[1] = a1;
    ctx.arg[2] = a2;
    ctx.arg[3] = a3;
    ctx.arg[4] = a4;

    /*
     * ONE PATH: the generic five-register context. There are no typed, per-hook ctx builders
     * any more. A program reads whatever fields it needs from the argument pointers via CO-RE
     * relocations resolved against the target build's BTF before signing, so the host
     * never learns any hook's layout --- which is what removed the "burns a build per data
     * source" coupling: adding a data source is writing bytecode now, not editing TMM. An
     * arbitrary armed function therefore gets exactly this: the register block, nothing
     * dereferenced.
     */
    if (ls_vm_call(slot, &ctx, sizeof ctx) != LS_SAFE_RETURN)
        return r;

    /*
     * The safe value belongs to the SLOT (item 7). v1 carries one configured
     * value per slot (ls_vm_safe_value, set from LS_SHIELD_SAFE_VALUE at arm) ---
     * not yet the full per-return-type policy table, but enough that an err_t
     * hook returns ERR_BUF instead of 0. Zero was right for a pointer/BOOL hook
     * and wrong for one whose caller treats 0 as success, which converts a crash
     * into silent misbehaviour: dtls_tx is precisely that case (0 == ERR_OK).
     */
    r.verdict    = LS_TRAMP_SAFE_RETURN;
    r.safe_value = ls_vm_safe_value(slot);
    return r;
}

ls_vm.c.text:
/*
 * ls_vm.c --- the embedded eBPF VM. The whole of it.
 *
 * ~120 lines of real code against uBPF's real API. This is what makes the
 * sentence "TMM has its own BPF VM" true; everything else in the scope list is
 * about reaching functions nobody planned for.
 *
 * THE TMM-SIDE CHANGES, in full --- three places, and no more:
 *
 *   1. src/compile/Makefile   link the library
 *          CFLAGS  += -I$(TOPDIR)/.ubpf/vm/inc
 *          LDFLAGS += $(TOPDIR)/.ubpf/build/lib/libubpf.a
 *
 *   2. TMM instance startup, beside the other per-instance init:
 *          ls_vm_init();
 *
 *   3. A call site. One, to start with, at a place already known to fault:
 *
 *          static bool
 *          http_psm_profile_name_lookup(enum errdefs_key key, void *source,
 *                                       errdefs_append append_fn, void *dest)
 *          {
 *              struct http_psm_log_data *log_data = source;
 *              struct http_scb *scb = log_data->scb;
 *              struct connflow *cf = uflow_get_connflow(scb->uf);
 *              struct fw_log_profile_protocol_transfer *ptlp =
 *                  flow_get_listener(cf)->prot_transfer_log_profile;
 *
 *     [SUPERSEDED --- illustrates the RETIRED typed-ctx model. Today the trampoline hands
 *      every program the generic register ctx and a CO-RE program reads fields by relocation;
 *      no per-hook ctx type is built in the host. Kept as the design record of why.]
 *     +        struct ls_ctx_http_psm c = {                  // per-core scratch
 *     +            .ptlp      = (uint64_t)(uintptr_t)ptlp,
 *     +            .ptlp_name = ptlp ? (uint64_t)(uintptr_t)ptlp->name : 0,
 *     +            .name_len  = (ptlp && ptlp->name) ? (uint32_t)strlen(ptlp->name) : 0,
 *     +        };
 *     +        if (ls_vm_call(ls_ptlog_slot, &c, sizeof c) == LS_SAFE_RETURN)
 *     +            return false;                             // the declared safe value
 *
 *     and at init, passing BOTH identities (O14):
 *     +        ls_ptlog_slot = ls_vm_arm(blob, sizeof blob,
 *     +                                  "fentry/http_psm_profile_name_lookup",
 *     +                                  "shield", LS_MODE_ENFORCE);
 *
 *              const char *str = ptlp->name;
 *              return append_fn(str, strlen(str), dest);
 *          }
 *
 * That third block is the entire per-hook cost, and it is the DESIGNED-IN form:
 * a deliberate call site in source F5 owns. The trampoline and pad-rewriting
 * work exists to get this same effect at a function nobody edited --- a bigger
 * claim, and not this one.
 *
 * Note what the call site does NOT do: it does not consult the mode. The program
 * always selects the outcome its predicate implies and the host decides whether
 * to apply it, because gating mode inside the program would make a monitor-mode
 * hit indistinguishable from a miss.
 *
 * Status: candidate artifact. Compiles against the vendored uBPF headers.
 * Nothing in this repo instantiates it inside TMM.
 */

#include "ls_vm.h"
#include "ls_vm_config.h"
#include "ls_tp.h"          /* ls_tp_emit_shield --- the enforcement-evidence event */
#include "vm_stack_policy.h"
#include "ls_map.h"
#include "ls_map_glue.h"
#include "ls_core_relo.h"
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>

#include <elf.h>
#include <stdio.h>
#include <stdlib.h>   /* free() for uBPF's error strings */
#include <string.h>

#include "ubpf.h"

/* 12, matching the LS_TRAMP expansions in trampoline_x86_64.S. The two are compared
 * at arm time against the count that file publishes --- see ls_arm.c --- because a
 * C-side constant larger than the real table indexes past .rodata and arms a wild
 * address. Raised from 8 on 2026-08-18 for the ssl__err tracepoint plus headroom. */
#define LS_MAX_SLOTS 12

/*
 * Per-instance program stack, allocated once.
 *
 * ubpf_exec() declares `uint64_t stack[UBPF_EBPF_STACK_SIZE/8]` --- 4 KB --- as a
 * local, so every invocation pushes and touches a 4 KB frame at whatever depth
 * TMM's call graph happens to be at. That is the same hazard finding O7 raised
 * against the JIT prologue, present on the interpreter path as well, and it is
 * paid per call rather than once.
 *
 * ubpf_exec_ex() takes the stack from the caller, so we allocate it once per TMM
 * instance and hand the same one to every invocation. Safe here for the reason
 * the rest of this file is lock-free: one VM per instance, run-to-completion, so
 * two invocations never overlap on a core. It would NOT be safe if a hook could
 * be re-entered --- a shield that somehow triggered the hooked path again would
 * corrupt its own stack, which is why re-entrancy is on the trampoline's
 * requirement list (scope item 1) rather than assumed away.
 */
/* Defined below ls_vm_call, which it uses; declared here because ls_vm_arm
 * invokes it. */
static void ls_vm_selftest(int slot, unsigned level);

static uint8_t *g_prog_stack;
#define LS_PROG_STACK_SIZE 4096

/* Per TMM instance. Not shared, not locked --- see the header. `static` because
 * each TMM instance is its own process. */
static struct ls_slot g_slots[LS_MAX_SLOTS];
static bool           g_ready;

/* What PREVAIL was told, and therefore what uBPF must allocate. Passed to uBPF
 * as the calculator cookie so the two agree by construction rather than by two
 * defaults coincidentally matching (item 6a; see vm_stack_policy.h). */
static const struct vm_stack_policy g_policy = { .proven_frame = 256, .max_depth = 8 };

static struct ls_vm_config g_cfg;

/* Where the program came from, for the arm-time log. Knowing WHICH shield a pod
 * is running has already been a question once; it should never be a guess. */
static char g_origin[160];

/*
 * Read the timestamp counter. Used only when LS_VM_TIMING or LS_VM_BENCH is on,
 * so the shipped path is untouched by default.
 *
 * This is a CYCLE COUNT, not a duration, and the two are not interchangeable on
 * a machine that scales frequency. It is the right primitive for comparing two
 * paths on one box; it is the wrong primitive for quoting nanoseconds. The
 * aarch64 counter is worse still --- 10-40ns granularity against a budget of
 * tens of ns (finding O6) --- which is why any arm64 number from this needs its
 * own caveat rather than the same one.
 */
static inline uint64_t
ls_cycles(void)
{
#if defined(__x86_64__)
    uint32_t lo, hi;
    __asm__ __volatile__("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi << 32) | lo;
#elif defined(__aarch64__)
    uint64_t v;
    __asm__ __volatile__("mrs %0, cntvct_el0" : "=r"(v));
    return v;
#else
    return 0;
#endif
}

/* Read a program from a file instead of the compiled-in blob. This is what turns
 * "change the shield" from a rebuild into a restart. Bounded: a program that
 * does not fit the cap is refused rather than truncated, because a truncated
 * ELF that happens to parse is worse than no program. */
#define LS_MAX_PROG 262144

/* Allocated for the file's actual size, at init, and freed once the program is
 * loaded into the VM. A static buffer here is permanently-resident .bss in every
 * TMM instance --- one per core --- holding a copy of something uBPF has already
 * copied. Measured: the static version cost 256 KB per instance for nothing. */
static unsigned char *g_filebuf;

static size_t
ls_read_program(const char *path)
{
    FILE *f = fopen(path, "rb");
    if (f == NULL)
        return 0;
    if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return 0; }
    long sz = ftell(f);
    rewind(f);
    if (sz <= 0 || sz > LS_MAX_PROG) {
        fprintf(stderr, "ls_vm: %s is %ld bytes; limit is %d --- refusing rather "
                        "than truncating\n", path, sz, LS_MAX_PROG);
        fclose(f);
        return 0;
    }
    free(g_filebuf);
    g_filebuf = malloc((size_t)sz);
    if (g_filebuf == NULL) { fclose(f); return 0; }
    size_t n = fread(g_filebuf, 1, (size_t)sz, f);
    fclose(f);
    return (n == (size_t)sz) ? n : 0;
}

/* Adapter, not a cast. vm_stack_policy.h deliberately does not include uBPF's
 * headers --- it must stay checkable on its own --- so its calculator takes
 * `const void *` where uBPF's typedef takes `const struct ubpf_vm *`. Those are
 * DIFFERENT function pointer types, and calling through a converted incompatible
 * function pointer is undefined behaviour, not a style question. One forwarding
 * function costs nothing and keeps both sides honest. */
static int
ls_stack_usage(const struct ubpf_vm *vm, uint16_t pc, void *cookie)
{
    return vm_stack_usage((const void *)vm, pc, cookie);
}


/*
 * Does `function` live in `section` within this object? (Finding O14.)
 *
 * PREVAIL is told a SECTION and proves the program there. uBPF is told a FUNCTION
 * SYMBOL and runs that. Nothing in either tool relates the two, so an object with
 * more than one function can be verified as one program and executed as another.
 * This closes that by reading the object's own symbol table.
 *
 * Written defensively on purpose: `elf_len` is attacker-influenced in the real
 * loader path, so every offset is bounds-checked against it before use. Returns
 * 1 only when the relationship is positively established --- unknown is a refusal,
 * not a pass.
 */
static int
ls_symbol_is_in_section(const void *elf, size_t elf_len,
                        const char *section, const char *function)
{
    const unsigned char *base = (const unsigned char *)elf;

    if (elf == NULL || section == NULL || function == NULL)
        return 0;
    if (elf_len < sizeof(Elf64_Ehdr))
        return 0;

    Elf64_Ehdr eh;
    memcpy(&eh, base, sizeof eh);
    if (memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0 || eh.e_ident[EI_CLASS] != ELFCLASS64)
        return 0;
    if (eh.e_shentsize != sizeof(Elf64_Shdr) || eh.e_shnum == 0)
        return 0;
    /* section header table must lie wholly inside the object */
    if (eh.e_shoff > elf_len ||
        (size_t)eh.e_shnum * sizeof(Elf64_Shdr) > elf_len - (size_t)eh.e_shoff)
        return 0;
    if (eh.e_shstrndx >= eh.e_shnum)
        return 0;

    const Elf64_Shdr *sh = (const Elf64_Shdr *)(const void *)(base + eh.e_shoff);

    /* section-name string table */
    const Elf64_Shdr *shstr = &sh[eh.e_shstrndx];
    if (shstr->sh_offset > elf_len || shstr->sh_size > elf_len - shstr->sh_offset)
        return 0;
    const char *shstrtab = (const char *)(base + shstr->sh_offset);

    /* find the symbol table and its string table */
    const Elf64_Shdr *symtab = NULL;
    for (unsigned i = 0; i < eh.e_shnum; i++) {
        if (sh[i].sh_type == SHT_SYMTAB) { symtab = &sh[i]; break; }
    }
    if (symtab == NULL || symtab->sh_entsize != sizeof(Elf64_Sym))
        return 0;
    if (symtab->sh_offset > elf_len || symtab->sh_size > elf_len - symtab->sh_offset)
        return 0;
    if (symtab->sh_link >= eh.e_shnum)
        return 0;

    const Elf64_Shdr *strh = &sh[symtab->sh_link];
    if (strh->sh_offset > elf_len || strh->sh_size > elf_len - strh->sh_offset)
        return 0;
    const char *strtab = (const char *)(base + strh->sh_offset);

    const Elf64_Sym *sym = (const Elf64_Sym *)(const void *)(base + symtab->sh_offset);
    size_t nsyms = (size_t)(symtab->sh_size / sizeof(Elf64_Sym));

    for (size_t i = 0; i < nsyms; i++) {
        if (sym[i].st_name >= strh->sh_size)
            continue;                       /* name would run off the string table */
        if (strcmp(strtab + sym[i].st_name, function) != 0)
            continue;
        if (ELF64_ST_TYPE(sym[i].st_info) != STT_FUNC)
            continue;                       /* a data symbol of the same name is not it */
        if (sym[i].st_shndx >= eh.e_shnum)
            return 0;                       /* SHN_UNDEF / ABS: not defined here */

        const Elf64_Shdr *owner = &sh[sym[i].st_shndx];
        if (owner->sh_name >= shstr->sh_size)
            return 0;
        return strcmp(shstrtab + owner->sh_name, section) == 0;
    }
    return 0;                               /* no such function: refuse */
}

/* The single STT_FUNC symbol defined in `section` --- the program's entry, taken FROM the
 * object we verified rather than assumed to be a fixed name. Same bounds discipline as
 * ls_symbol_is_in_section. Returns the name length (copied into out), or 0 if none. */
size_t
ls_function_in_section(const void *elf, size_t elf_len, const char *section,
                       char *out, size_t outlen)
{
    const unsigned char *base = elf;
    if (elf == NULL || section == NULL || out == NULL || outlen == 0) return 0;
    if (elf_len < sizeof(Elf64_Ehdr)) return 0;
    Elf64_Ehdr eh; memcpy(&eh, base, sizeof eh);
    if (eh.e_shentsize != sizeof(Elf64_Shdr) || eh.e_shnum == 0) return 0;
    if (eh.e_shoff > elf_len || (size_t)eh.e_shnum * sizeof(Elf64_Shdr) > elf_len - eh.e_shoff) return 0;
    const Elf64_Shdr *sh = (const Elf64_Shdr *)(const void *)(base + eh.e_shoff);
    if (eh.e_shstrndx >= eh.e_shnum) return 0;
    const Elf64_Shdr *shstr = &sh[eh.e_shstrndx];
    if (shstr->sh_offset > elf_len || shstr->sh_size > elf_len - shstr->sh_offset) return 0;
    const char *shstrtab = (const char *)(base + shstr->sh_offset);
    const Elf64_Shdr *symtab = NULL;
    for (unsigned i = 0; i < eh.e_shnum; i++)
        if (sh[i].sh_type == SHT_SYMTAB) { symtab = &sh[i]; break; }
    if (symtab == NULL || symtab->sh_entsize != sizeof(Elf64_Sym)) return 0;
    if (symtab->sh_offset > elf_len || symtab->sh_size > elf_len - symtab->sh_offset) return 0;
    if (symtab->sh_link >= eh.e_shnum) return 0;
    const Elf64_Shdr *strh = &sh[symtab->sh_link];
    if (strh->sh_offset > elf_len || strh->sh_size > elf_len - strh->sh_offset) return 0;
    const char *strtab = (const char *)(base + strh->sh_offset);
    const Elf64_Sym *sym = (const Elf64_Sym *)(const void *)(base + symtab->sh_offset);
    size_t nsyms = (size_t)(symtab->sh_size / sizeof(Elf64_Sym));
    for (size_t i = 0; i < nsyms; i++) {
        if (ELF64_ST_TYPE(sym[i].st_info) != STT_FUNC) continue;
        if (sym[i].st_shndx >= eh.e_shnum || sym[i].st_name >= strh->sh_size) continue;
        const Elf64_Shdr *owner = &sh[sym[i].st_shndx];
        if (owner->sh_name >= shstr->sh_size) continue;
        if (strcmp(shstrtab + owner->sh_name, section) != 0) continue;
        const char *nm = strtab + sym[i].st_name;
        size_t n = strlen(nm);
        if (n == 0 || n >= outlen) return 0;
        memcpy(out, nm, n + 1);
        return n;
    }
    return 0;
}

bool
ls_vm_init(void)
{
    memset(g_slots, 0, sizeof g_slots);
    ls_vm_config_load(&g_cfg);
    if (g_prog_stack == NULL) {
        g_prog_stack = calloc(1, LS_PROG_STACK_SIZE);
        if (g_prog_stack == NULL)
            return false;
    }
    if (!g_cfg.enable) {
        /* A shield that misbehaves must be switchable off without reverting the
         * integration and without a rebuild. */
        fprintf(stderr, "ls_vm: disabled by LS_SHIELD_ENABLE=0\n");
        return false;
    }
    g_ready = true;
    if (g_cfg.verbose)
        fprintf(stderr, "ls_vm: init  build=%s %s  jit=%d fuel=%u timing=%d\n",
                __DATE__, __TIME__, (int)g_cfg.jit, g_cfg.fuel, (int)g_cfg.timing);
    return true;
}

bool
ls_vm_stats(int slot, struct ls_stats *out)
{
    if (slot < 0 || slot >= LS_MAX_SLOTS || out == NULL)
        return false;
    const struct ls_slot *s = &g_slots[slot];
    out->armed = s->armed;
    out->is_exit = s->is_exit;
    out->mode = (int)s->mode;
    out->fired = s->fired;
    out->safe_returns = s->safe_returns;
    /* Counters are per SLOT and survive a program swap. That residue was read as
     * a result twice on 2026-08-17 --- a safe_returns=246 left by one program was
     * taken as evidence about the next. `gen` increments on every reload, so a
     * reader can tell whether the counts belong to the program it just loaded. */
    out->gen = s->gen;
    out->errors = s->errors;
    out->cycles = s->cycles;
    out->cycles_max = s->cycles_max;
    out->cycles_min = s->cycles_min;
    out->snapshot_entry_errors = s->snapshot_entry_errors;
    out->snapshot_return_errors = s->snapshot_return_errors;
    return true;
}

uint64_t
ls_vm_safe_value(int slot)
{
    if (slot < 0 || slot >= LS_MAX_SLOTS)
        return 0;
    return g_slots[slot].safe_value;
}

unsigned
ls_vm_samples(int slot, struct ls_ctx_sample *out, unsigned max)
{
    if (slot < 0 || slot >= LS_MAX_SLOTS || out == NULL)
        return 0;
    struct ls_slot *s = &g_slots[slot];
    unsigned have = s->sample_next < LS_CTX_SAMPLES ? (unsigned)s->sample_next
                                                    : LS_CTX_SAMPLES;
    if (have > max)
        have = max;
    for (unsigned i = 0; i < have; i++)
        out[i] = s->samples[i];
    return have;
}

/*
 * Load a program, benchmark it, throw it away --- WITHOUT arming it onto a hook.
 *
 * Move-3 instrument. Calibrating the budget pass needs the measured cost of many
 * programs of varying length and opcode mix. Doing that through LS_SHIELD_PATH
 * costs a pod restart per data point; doing it here costs a message. That is the
 * difference between fitting a model and sampling twice and guessing.
 *
 * Runs on the loader thread, off the data path, and never touches a live slot.
 */
int
ls_vm_bench_program(const void *elf, size_t elf_len,
                    const char *section, const char *function,
                    uint32_t iters,
                    uint64_t *min_out, uint64_t *mean_out, uint64_t *max_out,
                    int *jitted_out)
{
    char *err = NULL;
    struct ubpf_vm *vm = NULL;
    uint8_t *stack = NULL;
    unsigned char ctx[LS_TRACING_CTX_SIZE];
    uint64_t ret = 0, best = ~0ull, worst = 0, total = 0;
    int rc = -1;

    if (elf == NULL || iters == 0)
        return -1;
    if (!ls_symbol_is_in_section(elf, elf_len, section, function))
        return -1;                          /* same O14 gate as the real path */

    vm = ubpf_create();
    if (vm == NULL)
        return -1;
    if (ubpf_register_stack_usage_calculator(vm, ls_stack_usage, (void *)&g_policy) != 0)
        goto out;
    /* Maps, before the load --- the bench path needs it for the same reason the
     * arm path does: a program with maps must measure with its maps working, or
     * the number describes a program that fell through every lookup. */
    if (ls_map_glue_install(vm) != 0)
        goto out;
    if (ubpf_load_elf_ex(vm, elf, elf_len, function, &err) < 0)
        goto out;
    if (g_ls_config.load_error)
        goto out;

    /* Its own stack: the shared one belongs to the data path, and this runs on
     * the loader thread. */
    stack = calloc(1, LS_PROG_STACK_SIZE);
    if (stack == NULL)
        goto out;

    /*
     * MEASURE THE PATH AN ARMED HOOK ACTUALLY TAKES.
     *
     * This loop called ubpf_exec_ex --- the INTERPRETER --- while ls_vm_call prefers jit_fn
     * whenever it is non-NULL, and this build runs with jit=1. So the figure it produced
     * described an execution path no armed hook uses. It was not wrong by a little: an
     * earlier off-TMM measurement in this repo put the interpreter at 48 ns against the JIT's
     * 10 ns, and the whole reason this op exists is to answer "what does a hook cost per
     * call". Reporting the interpreter under that question invites exactly one misreading and
     * it is the pessimistic one.
     *
     * So: compile when the configuration says to, call through the same ubpf_jit_ex_fn cast
     * ls_vm_call uses, with the same stack argument, and report WHICH path was measured so
     * the number cannot be read as the other one.
     *
     * EXTENDED mode, matching ls_vm_arm. Basic mode's prologue allocates its own stack ---
     * ubpf.h: "automatically allocates a stack" --- which is the unprobed 4 KB frame finding
     * O7 is about, and it would also make this measure a different prologue than the live one.
     *
     * A JIT FAILURE FALLS BACK rather than aborting: an unbenchmarkable program is less useful
     * than an interpreter figure that says so. The caller is told which it got.
     */
    ubpf_jit_ex_fn jf = NULL;

    if (g_cfg.jit) {
        char *jerr = NULL;
        jf = ubpf_compile_ex(vm, &jerr, ExtendedJitMode);
        if (jf == NULL) {
            fprintf(stderr, "ls_vm: bench: JIT failed (%s) --- measuring the interpreter "
                            "instead; the number is NOT the armed-hook path\n",
                    jerr ? jerr : "?");
        }
        free(jerr);
    }
    if (jitted_out)
        *jitted_out = (jf != NULL);

    memset(ctx, 0, sizeof ctx);
    /* Warm the caches and, on the JIT path, fault in the generated code. Measuring the first
     * call would measure the page fault. */
    for (uint32_t i = 0; i < 100 && i < iters; i++) {
        if (jf != NULL)
            (void)jf(ctx, sizeof ctx, stack, LS_PROG_STACK_SIZE);
        else
            (void)ubpf_exec_ex(vm, ctx, sizeof ctx, &ret, stack, LS_PROG_STACK_SIZE);
    }

    for (uint32_t i = 0; i < iters; i++) {
        uint64_t t0 = ls_cycles();
        if (jf != NULL) {
            /* No error channel, exactly as on the data path: ls_vm_call cannot tell a faulting
             * compiled program from a returning one either. That asymmetry with the
             * interpreter branch below is a real property of the JIT, not an omission here. */
            (void)jf(ctx, sizeof ctx, stack, LS_PROG_STACK_SIZE);
        } else if (ubpf_exec_ex(vm, ctx, sizeof ctx, &ret, stack, LS_PROG_STACK_SIZE) != 0) {
            goto out;
        }
        uint64_t d = ls_cycles() - t0;
        total += d;
        if (d < best)  best = d;
        if (d > worst) worst = d;
    }
    if (min_out)  *min_out  = best;
    if (mean_out) *mean_out = total / iters;
    if (max_out)  *max_out  = worst;
    rc = 0;
out:
    free(err);
    free(stack);
    if (vm) ubpf_destroy(vm);
    return rc;
}

void
ls_vm_report(void)
{
    for (int i = 0; i < LS_MAX_SLOTS; i++) {
        const struct ls_slot *s = &g_slots[i];
        if (!s->armed)
            continue;
        fprintf(stderr,
                "ls_vm: slot=%d mode=%d fired=%llu safe_returns=%llu errors=%llu"
                " cycles_total=%llu cycles_mean=%llu cycles_max=%llu\n",
                i, (int)s->mode,
                (unsigned long long)s->fired, (unsigned long long)s->safe_returns,
                (unsigned long long)s->errors, (unsigned long long)s->cycles,
                (unsigned long long)(s->fired ? s->cycles / s->fired : 0),
                (unsigned long long)s->cycles_max);
    }
}

/*
 * Run the program N times over a fixed ctx and report cycle statistics.
 *
 * This exists because the alternative --- waiting for live traffic to reach one
 * specific vulnerable function --- requires a listener configured with a
 * protocol-transfer log profile, which is a whole config exercise standing
 * between us and a number. The benchmark answers "what does one invocation
 * cost" directly.
 *
 * What it measures: ubpf_exec plus this function's own loop overhead, on a warm
 * cache, with no contention. That is the FLOOR. A real invocation adds the ctx
 * build, a cold-ish cache, and whatever the poll loop is doing. Report it as a
 * floor or not at all.
 */
static void
ls_vm_bench(int slot, uint32_t iters)
{
    struct ls_slot *s = &g_slots[slot];
    unsigned char ctx[LS_TRACING_CTX_SIZE];
    uint64_t ret = 0, best = ~0ull, worst = 0, total = 0;

    if (!s->armed || iters == 0)
        return;
    memset(ctx, 0, sizeof ctx);        /* the NULL case: the shield's hot branch */

    ubpf_jit_ex_fn jf = (ubpf_jit_ex_fn)s->jit_fn;

    for (uint32_t i = 0; i < 100 && i < iters; i++)   /* warm */
        if (jf) (void)jf(ctx, sizeof ctx, g_prog_stack, LS_PROG_STACK_SIZE);
        else    (void)ubpf_exec_ex(s->vm, ctx, sizeof ctx, &ret, g_prog_stack, LS_PROG_STACK_SIZE);

    for (uint32_t i = 0; i < iters; i++) {
        uint64_t t0 = ls_cycles();
        int rc = 0;
        if (jf) ret = jf(ctx, sizeof ctx, g_prog_stack, LS_PROG_STACK_SIZE);
        else    rc  = ubpf_exec_ex(s->vm, ctx, sizeof ctx, &ret, g_prog_stack, LS_PROG_STACK_SIZE);
        uint64_t d = ls_cycles() - t0;
        if (rc != 0) { fprintf(stderr, "ls_vm: bench exec fault at %u\n", i); return; }
        total += d;
        if (d < best)  best = d;
        if (d > worst) worst = d;
    }
    fprintf(stderr,
            "ls_vm: bench slot=%d path=%s iters=%u min=%llu mean=%llu max=%llu cycles"
            "  (floor: warm cache, no contention, ubpf_exec only --- NOT a"
            " per-packet cost)\n",
            slot, jf ? "JIT" : "interp", iters, (unsigned long long)best,
            (unsigned long long)(total / iters), (unsigned long long)worst);
}

/* ---- CO-RE target BTF: THIS build's type info, embedded in the binary ----
 * The kernel embeds BTF in vmlinux as a `.BTF` section (pahole at build; see
 * evidence/cache/kernel-btf.html) and re-exposes it via /sys/kernel/btf/vmlinux
 * only because userspace cannot read kernel memory. TMM is a userspace process,
 * so its equivalent is to read its OWN `.BTF` section from /proc/self/exe --- the
 * same model minus the sysfs indirection. Packaging embeds `.BTF` into the binary
 * (pahole + objcopy --add-section); this reads it back. The BTF therefore cannot
 * mismatch the binary: it IS the binary's own section. */

/* One fact, one whitelist entry: the parsed target BTF and its load state
 * (0 unset, 1 ok, -1 failed). Folded into a struct rather than two globals so the
 * mutable-state manifest gains one name, not two --- see ls_audit's lesson. */
static struct { struct btf b; int state; } g_ls_btf;

/* Load and parse the binary's own `.BTF` once, lazily, on the TMM thread (malloc
 * is legal here; reached only via ls_prep_run_pending). The mmap outlives the
 * parse deliberately --- ls_core_btf_open does not copy the blob. */
static const struct btf *
ls_vm_target_btf(void)
{
    if (g_ls_btf.state == 0) {
        g_ls_btf.state = -1;                          /* pessimistic until proven */
        int fd = open("/proc/self/exe", O_RDONLY);
        if (fd >= 0) {
            off_t sz = lseek(fd, 0, SEEK_END);
            void *mem = (sz > 0 && sz < (off_t)0x80000000)
                          ? mmap(NULL, (size_t)sz, PROT_READ, MAP_PRIVATE, fd, 0)
                          : MAP_FAILED;
            close(fd);
            if (mem != MAP_FAILED) {
                const uint8_t *btf = 0; uint32_t btf_sz = 0;
                if (ls_core_btf_find_in_elf(mem, (uint32_t)sz, &btf, &btf_sz) == 0 &&
                    ls_core_btf_open(&g_ls_btf.b, btf, btf_sz) == 0)
                    g_ls_btf.state = 1;
            }
        }
        if (g_ls_btf.state != 1)
            fprintf(stderr, "ls_vm: no usable `.BTF` section in /proc/self/exe --- programs "
                            "cannot be relocated and will be refused\n");
    }
    return g_ls_btf.state == 1 ? &g_ls_btf.b : NULL;
}

int
ls_vm_arm(const void *elf, size_t elf_len,
          const char *section, const char *function, enum ls_mode m)
{
    int slot = -1;
    char *err = NULL;

    if (!g_ready || elf == NULL || section == NULL || function == NULL)
        return -1;

    /* O14: the verifier proved the program in `section`; uBPF is about to run the
     * one named `function`. Refuse unless they are the same program. */
    if (!ls_symbol_is_in_section(elf, elf_len, section, function)) {
        fprintf(stderr, "ls_vm: refusing --- '%s' does not live in section '%s'; "
                        "the verified program and the loaded one may differ\n",
                function, section);
        return -1;
    }

    for (int i = 0; i < LS_MAX_SLOTS; i++) {
        if (!g_slots[i].armed) { slot = i; break; }
    }
    if (slot < 0)
        return -1;

    /* The hook KIND rides on the verified section: a program compiled for
     * fexit/<fn> is armed at the function's RETURN (ls_fexit_table), one for
     * fentry/<hook> at its ENTRY. Recorded now, read at arm --- see ls_arm_live. */
    g_slots[slot].is_exit = (strncmp(section, "fexit/", 6) == 0);
    g_slots[slot].is_snapshot =
        strncmp(section, LS_SNAPSHOT_SECTION, LS_SNAPSHOT_PREFIX_LEN) == 0;
    g_slots[slot].snapshot_id.instance = g_ls_config.loading;
    g_slots[slot].snapshot_id.epoch = 1;
    if (g_slots[slot].is_snapshot &&
        (!g_ls_config.loading || m > LS_MODE_MONITOR))
        return -1;

    /* The safe-return value for THIS slot (item 7, v1: one configured value via
     * env, not yet the per-return-type policy table). Read here, off the data
     * path, and delivered by ls_tramp_dispatch. Default 0 is correct for a
     * pointer/BOOL hook and WRONG for an err_t one --- dtls_tx wants ERR_BUF(2),
     * set with LS_SHIELD_SAFE_VALUE=2 at arm. */
    {
        const char *sv = getenv("LS_SHIELD_SAFE_VALUE");
        g_slots[slot].safe_value = (sv != NULL && *sv != '\0')
                                 ? (uint64_t)strtoull(sv, NULL, 0) : 0;
    }

    struct ubpf_vm *vm = ubpf_create();
    if (vm == NULL)
        return -1;

    /* Before load: make the runtime allocate the frame the proof assumed.
     * Registering this is not optional --- without it uBPF falls back to 256
     * regardless of what the program was verified against, and a calculator
     * that returns 0 gets a ZERO-byte frame (finding O13). */
    if (ubpf_register_stack_usage_calculator(vm, ls_stack_usage, (void *)&g_policy) != 0)
        goto fail;

    /* Maps. MUST precede ubpf_load_elf_ex: the relocation callback is consulted
     * while uBPF walks the maps section, and a VM without it hands every helper
     * map=0 --- a program that loads, verifies, runs, and whose maps are silently
     * always empty. That is exactly the state this build was in. */
    if (ls_map_glue_install(vm) != 0)
        goto fail;

    /* CO-RE RELOCATION --- before verify+JIT. A portable program names TMM fields
     * by struct+field name and carries .BTF.ext records; here each is resolved to
     * THIS build's byte offset (from the baked BTF) and the instruction immediate
     * is patched, so one bytecode runs on any build with no baked offset and no
     * rebuild. `elf` is the caller's private, mutable prep buffer, so patching in
     * place is sound. FAIL-DARK: a program we cannot fully relocate is refused,
     * never run against a stale offset; a program with no .BTF.ext (nothing to
     * relocate) proceeds. Reached on the TMM thread, where malloc is legal. */
    {
        /* ASK WHETHER RELOCATION IS NEEDED BEFORE DEMANDING THE TYPE INFORMATION.
         *
         * This block used to call ls_vm_target_btf() first and refuse outright on
         * NULL. That is correct only while the binary carries its own `.BTF`, and
         * it is the single line standing between here and removing that section
         * (02-RESEARCH-PARAMETERS.md P9): once offsets are resolved at sign time
         * the shipped program has `.BTF`/`.BTF.ext` STRIPPED and needs no target
         * BTF at all --- but the old order refused it for lacking something it does
         * not use. The check further down already tolerated -LS_RELO_ENOBTF, so
         * the tolerance existed and was unreachable, guarded by a refusal above it.
         *
         * The three cases are now distinguished, and the middle one is the point:
         *   needs relocation + BTF present -> relocate, as before
         *   needs NO relocation            -> proceed; the target BTF is never read
         *   needs relocation + no BTF      -> REFUSE, naming the actual problem
         *
         * FAIL-DARK ON "CANNOT TELL". A malformed object gives -1 from the probe,
         * and that is treated as "needs relocation" --- never as "nothing to do".
         * Guessing the latter would run a program against unresolved placeholder
         * offsets (0, 1, 2 for a stub struct), reading whatever sits at the front
         * of a real TMM structure. Silently, and with PREVAIL's blessing, because
         * the proof was taken against the placeholder. */
        int needs = ls_core_elf_has_relos((const uint8_t *)elf, (uint32_t)elf_len);
        const struct btf *tb = (needs != 0) ? ls_vm_target_btf() : NULL;

        if (needs != 0 && tb == NULL) {
            fprintf(stderr, "ls_vm: refusing --- this program carries CO-RE "
                            "relocation records%s but this binary has no `.BTF` to "
                            "resolve them against. Resolve the field offsets at "
                            "sign time (the offsets must match this build) or load "
                            "a binary that embeds its own type information.\n",
                    needs < 0 ? " (or could not be parsed, which is treated the same)"
                              : "");
            goto fail;
        }

        unsigned nrel = 0;
        int rrc = (needs != 0)
                ? ls_core_relocate((void *)elf, (uint32_t)elf_len, tb, &nrel)
                : LS_RELO_OK;
        if (rrc != LS_RELO_OK && rrc != -LS_RELO_ENOBTF) {
            fprintf(stderr, "ls_vm: refusing --- CO-RE relocation failed (rc=%d)\n", rrc);
            goto fail;
        }
        if (needs == 0 && g_cfg.verbose)
            fprintf(stderr, "ls_vm: no CO-RE records --- offsets are baked; the "
                            "binary's own type information was not read\n");
        if (g_cfg.verbose && nrel)
            fprintf(stderr, "ls_vm: CO-RE relocated %u field offset(s)\n", nrel);
    }

    /* Interpreter by default. The JIT is reachable by env var so its cost can be
     * MEASURED without a rebuild --- not because it is safe to run (O6: fuel has
     * no effect once JIT'd; O7: the prologue opens a 4KB frame with no probe). */
    /* uBPF selects by FUNCTION SYMBOL here, not section --- see O14 and the
     * check above, which is what makes passing `function` safe. */
    if (ubpf_load_elf_ex(vm, elf, elf_len, function, &err) < 0)
        goto fail;
    if (g_ls_config.load_error) {
        fprintf(stderr, "ls_vm: refusing --- invalid configuration map declaration\n");
        goto fail;
    }

    /* Fuel. Works in the interpreter; documented as having no effect once
     * compiled to native code, which is the other half of why this is the
     * interpreter path first. */
    ubpf_set_instruction_limit(vm, g_cfg.fuel ? g_cfg.fuel : 10000, NULL);

    if (g_cfg.jit) {
        char *jerr = NULL;
        /* ubpf_exec/_ex ALWAYS interpret --- they never dispatch to compiled
         * code. A JIT'd program is reached only through the function pointer
         * ubpf_compile returns, so storing it is what makes the JIT do anything
         * at all. Compiling and then calling ubpf_exec, as an earlier version of
         * this file did, JITs the program and throws the result away: the
         * measurement showed jit=1 and jit=0 within noise of each other, which
         * was the tell. */
        /* EXTENDED mode, not basic. Basic mode's generated prologue allocates
         * its own stack --- ubpf.h: "automatically allocates a stack" --- which
         * is the unprobed 4 KB frame finding O7 is about. Extended mode takes the
         * stack as an argument, so the same per-instance buffer serves both the
         * interpreter and the compiled path. */
        g_slots[slot].jit_fn = (void *)ubpf_compile_ex(vm, &jerr, ExtendedJitMode);
        if (g_slots[slot].jit_fn == NULL) {
            fprintf(stderr, "ls_vm: JIT requested but failed: %s\n", jerr ? jerr : "?");
            free(jerr);
            goto fail;
        }
    }

    g_slots[slot].vm    = vm;
    g_slots[slot].mode  = m;
    /* THE BUILDER COMES FROM THE DECLARED HOOK, not from the slot number. `section` is
     * "fentry/<hook>" and ls_symbol_is_in_section just checked that identity against the
     * program's own symbol, so it is the strongest statement available about what this
     * program expects to be handed. NULL --- no registered builder --- means the generic
     * five registers and no dereference. ls_slots.h records what went wrong when the slot
     * number decided this. */
    g_slots[slot].armed = true;

    if (g_cfg.verbose)
        fprintf(stderr, "ls_vm: ARMED slot=%d section=%s function=%s mode=%d"
                        " bytes=%lu origin=%s jit=%d\n",
                slot, section, function, (int)m, (unsigned long)elf_len,
                g_origin[0] ? g_origin : "builtin", (int)g_cfg.jit);

    if (g_cfg.bench)
        ls_vm_bench(slot, g_cfg.bench);

    if (g_cfg.selftest)
        ls_vm_selftest(slot, g_cfg.selftest);

    return slot;

fail:
    if (err) { fprintf(stderr, "ls_vm: arm failed: %s\n", err); free(err); }
    ubpf_destroy(vm);
    return -1;
}

/*
 * Reproduce the CVE condition against the armed shield --- LS_VM_SELFTEST.
 *
 * WHAT THIS DEMONSTRATES: the real verified program, in the real VM, inside the
 * real TMM binary, deciding on the exact input the vulnerable call site would
 * hand it --- a NULL protocol-transfer log profile. And, at level 2, that the
 * dereference which follows a FALLTHROUGH verdict really is fatal.
 *
 * WHAT IT DOES NOT DEMONSTRATE, and must not be reported as: that the hook is
 * correctly placed in http_psm_profile_name_lookup, or that live traffic reaches
 * it. Those are separate claims needing a configured listener and a security log
 * profile whose format string contains ${profile_name}. This synthesises the
 * condition; it does not drive the path.
 *
 * Deliberately not built from fake TMM structures. Walking
 * log_data->scb->uf -> connflow -> listener would mean synthesising four internal
 * types, and a crash inside flow_get_listener() would prove nothing about this
 * bug. The ctx is what the shield actually sees, so the ctx is what is reproduced.
 *
 *   LS_VM_SELFTEST=1  evaluate and report. Never crashes.
 *   LS_VM_SELFTEST=2  evaluate, and on FALLTHROUGH perform the real dereference.
 *                     With the shield armed this survives; with LS_SHIELD_ENABLE=0
 *                     it is a segfault. That difference is the whole demonstration.
 */
static void
ls_vm_selftest(int slot, unsigned level)
{
    /* The generic five-register context, exactly what the trampoline now hands every
     * program: arg[0] is the first argument register. There are no typed ctx builders any
     * more --- a CO-RE program reads the fields it needs by relocation, so the self-test's
     * job is only to feed the mechanism the CVE condition (a null source pointer) and see
     * whether the loaded program returns SAFE_RETURN. */
    struct ls_ctx_generic c;
    memset(&c, 0, sizeof c);          /* arg[0] == NULL --- the CVE condition (source pointer null) */

    enum ls_verdict v = ls_vm_call(slot, &c, sizeof c);

    fprintf(stderr,
            "ls_vm: SELFTEST cve-condition ptlp=NULL -> verdict=%s  (%s)\n",
            v == LS_SAFE_RETURN ? "SAFE_RETURN" : "FALLTHROUGH",
            v == LS_SAFE_RETURN
              ? "the shield would skip the body --- no dereference, no crash"
              : "the body would run --- the NULL dereference happens next");

    if (level < 2)
        return;

    if (v == LS_SAFE_RETURN) {
        fprintf(stderr, "ls_vm: SELFTEST survived --- shield prevented the "
                        "dereference. Re-run with LS_SHIELD_ENABLE=0 to see the "
                        "same binary crash.\n");
        return;
    }

    /* No shield, or it declined. Do what the vulnerable line does. */
    fprintf(stderr, "ls_vm: SELFTEST performing the unshielded dereference --- "
                    "this is expected to be fatal\n");
    fflush(stderr);
    {
        volatile const char *const *pp = (volatile const char *const *)(uintptr_t)c.arg[0];
        volatile char sink = *(*pp);      /* the source pointer, with arg[0] == NULL */
        (void)sink;
    }
    fprintf(stderr, "ls_vm: SELFTEST did NOT crash --- unexpected; the platform "
                    "may be mapping page zero\n");
}

int
ls_vm_arm_configured(const void *blob, size_t blob_len,
                     const char *section, const char *function)
{
    const void *prog = blob;
    size_t      len  = blob_len;

    if (!g_ready)
        return -1;

    /* The compiled-in blob is OPT-IN. A hardcoded, auto-armed shield is exactly what
     * the socket load path exists to remove, so unless the operator explicitly asked
     * for the built-in (LS_SHIELD_BUILTIN=1) or named a program to run in its place
     * (LS_SHIELD_PATH / LS_SHIELD_SECTION), arm nothing here and let the socket loader
     * be the only way a program arrives. */
    if (!g_cfg.builtin && !g_cfg.path && !g_cfg.section) {
        if (g_cfg.verbose)
            fprintf(stderr, "ls_vm: no built-in shield armed (LS_SHIELD_BUILTIN=0) --- "
                            "socket load is the only arming path\n");
        return -1;
    }

    /* A program on disk replaces the compiled-in one. Refusing on a bad path
     * rather than silently falling back to the built-in matters: an operator who
     * pointed at a file and got the old shield, with no error, would have no way
     * to tell which program is running. */
    if (g_cfg.path) {
        size_t n = ls_read_program(g_cfg.path);
        if (n == 0) {
            fprintf(stderr, "ls_vm: LS_SHIELD_PATH=%s unreadable or empty --- "
                            "refusing (NOT falling back to the built-in)\n", g_cfg.path);
            return -1;
        }
        prog = g_filebuf;
        len  = n;
        /* uBPF copies the program during load, so this buffer is dead after
         * ls_vm_arm returns --- freed below rather than held for the process
         * lifetime. */
        snprintf(g_origin, sizeof g_origin, "file:%s(%lu)", g_cfg.path, (unsigned long)n);
    } else {
        snprintf(g_origin, sizeof g_origin, "builtin(%lu)", (unsigned long)len);
    }

    int slot = ls_vm_arm(prog, len,
                         g_cfg.section  ? g_cfg.section  : section,
                         g_cfg.function ? g_cfg.function : function,
                         (enum ls_mode)g_cfg.mode);
    free(g_filebuf);
    g_filebuf = NULL;
    return slot;
}

/*
 * The ctx builder a slot's program declared, or NULL for "generic, dereference nothing".
 *
 * NULL for an out-of-range slot, an unarmed one, and an unregistered hook alike --- all three
 * mean the same thing to the caller, which is why one return value covers them.
 *
 * Acquire-loaded to pair with the release in ls_vm_reload: a core already inside the
 * trampoline must not see the new builder with the old program or the reverse.
 */
/*
 * Is signature enforcement on?
 *
 * An accessor rather than exporting g_cfg, and rather than letting ls_vm_load.c read the
 * environment itself. One place parses configuration; two would eventually disagree, and the one
 * place they must not disagree is whether a security gate is armed.
 */
int
ls_vm_sig_enforce(void)
{
    return g_cfg.sig_enforce ? 1 : 0;
}




static enum ls_verdict
ls_vm_run(int slot, void *ctx, size_t ctx_len,
          const struct ls_snapshot_id *identity, int *completed)
{
    uint64_t ret = 0;

    if (slot < 0 || slot >= LS_MAX_SLOTS)
        return LS_FALLTHROUGH;

    if (ls_map_enter() != 0)
        return LS_FALLTHROUGH;
    struct ls_slot *s = &g_slots[slot];

    /* Both of these can be replaced under us by the loader thread, so read each
     * exactly once. Reading s->vm twice could straddle a swap and use one
     * program's VM with another's expectations. */
    enum ls_mode mode = __atomic_load_n(&s->mode, __ATOMIC_ACQUIRE);
    void *vm = __atomic_load_n(&s->vm, __ATOMIC_ACQUIRE);
    if (!s->armed || vm == NULL || mode == LS_MODE_DISABLE) {
        ls_map_leave();
        return LS_FALLTHROUGH;
    }
    if ((identity == NULL && s->is_snapshot) ||
        (identity != NULL &&
         (!s->is_snapshot || !identity->instance ||
          identity->epoch == UINT64_MAX ||
          identity->instance != s->snapshot_id.instance ||
          identity->epoch != __atomic_load_n(&s->snapshot_id.epoch,
                                             __ATOMIC_ACQUIRE)))) {
        ls_map_leave();
        return LS_FALLTHROUGH;
    }

    /* PUBLISH WHICH SLOT IS RUNNING, for helpers that need it and cannot be told.
     * uBPF's external_function_t has no context parameter, so bpf_ringbuf_output has no
     * way to know which slot invoked it; a thread-local is correct because TMM is
     * core-pinned and run-to-completion, so exactly one program runs on this thread at
     * any instant. Set AFTER the early returns so a disabled or unarmed slot never
     * leaves a stale value behind, and cleared on every exit path below. */
    g_ls_cur_slot = slot;
    ls_config_begin(&g_ls_config_view, (unsigned)slot);

    /* A non-zero return from ubpf_exec is an execution fault --- fuel exhausted,
     * or a bounds check the interpreter enforces at run time. Fall through: a
     * shield that cannot run must not take the flow with it. Counted, because a
     * silent fail-open is indistinguishable from a shield that never matched. */
    uint64_t t0 = g_cfg.timing ? ls_cycles() : 0;
    /* Compiled path if we have one, interpreter otherwise. Both take the stack
     * from us: ubpf_exec would allocate and touch 4 KB of C stack on every packet
     * reaching this hook, and basic-mode JIT code would do the same in its
     * prologue without a guard-page probe (O7). */
    int rc = 0;
    void *jf = __atomic_load_n(&s->jit_fn, __ATOMIC_ACQUIRE);
    if (jf != NULL) {
        ret = ((ubpf_jit_ex_fn)jf)(ctx, ctx_len, g_prog_stack, LS_PROG_STACK_SIZE);
    } else {
        rc = ubpf_exec_ex(vm, ctx, ctx_len, &ret, g_prog_stack, LS_PROG_STACK_SIZE);
    }
    g_ls_config_view.active = 0;
    g_ls_cur_slot = -1;
    ls_map_leave();
    if (g_cfg.timing) {
        uint64_t d = ls_cycles() - t0;
        s->cycles += d;
        if (d > s->cycles_max) s->cycles_max = d;
        if (s->cycles_min == 0 || d < s->cycles_min) s->cycles_min = d;
    }
    if (rc != 0) {
        s->errors++;
        return LS_FALLTHROUGH;
    }
    if (completed != NULL)
        *completed = 1;

    /* Sample the ctx. A fixed-size memcpy into a slot-resident ring: no
     * allocation, no lock, no syscall. Gated so the shipped path is untouched
     * unless asked --- same discipline as timing. */
    if (g_cfg.samples) {
        struct ls_ctx_sample *sm = &s->samples[s->sample_next % LS_CTX_SAMPLES];
        size_t n = ctx_len < LS_CTX_SAMPLE_BYTES ? ctx_len : LS_CTX_SAMPLE_BYTES;
        sm->seq = s->fired;
        sm->len = (uint32_t)ctx_len;
        sm->verdict = (uint32_t)ret;
        memcpy(sm->bytes, ctx, n);
        s->sample_next++;
    }

    if (s->fired == 0 && g_cfg.verbose)
        fprintf(stderr, "ls_vm: FIRST INVOCATION slot=%d --- the hook is reached\n", slot);
    s->fired++;
    if (g_cfg.report_every && (s->fired % g_cfg.report_every) == 0)
        ls_vm_report();

    if (identity != NULL || ret != LS_SAFE_RETURN)
        return LS_FALLTHROUGH;

    s->safe_returns++;

    /* THE EVIDENCE EVENT. A counter answers "how many"; this answers "show me the
     * one it stopped". Emitted in BOTH modes --- enforce (blocked) and monitor
     * (WOULD have blocked) --- so a shield validated in monitor still produces the
     * record a reviewer needs, tagged with which mode it was. Rate-limited and
     * ring-gated inside ls_tp_emit_shield; a no-op on the shipped default. Off the
     * common path: SAFE_RETURN fires only when the exploit precondition holds. */
    ls_tp_emit_shield(slot, s->gen, (unsigned)mode, (unsigned)ret, ctx, ctx_len);

    /* Monitor mode counts the selection and applies nothing. The counters above
     * are what make a monitor-mode hit distinguishable from a miss. */
    return (mode == LS_MODE_ENFORCE) ? LS_SAFE_RETURN : LS_FALLTHROUGH;
}

enum ls_verdict
ls_vm_call(int slot, void *ctx, size_t ctx_len)
{
    return ls_vm_run(slot, ctx, ctx_len, NULL, NULL);
}

int
ls_vm_snapshot_identity(int slot, struct ls_snapshot_id *identity)
{
    int snapshot = 0;
    memset(identity, 0, sizeof *identity);
    if (slot >= 0 && slot < LS_MAX_SLOTS && g_slots[slot].is_snapshot) {
        identity->instance = g_slots[slot].snapshot_id.instance;
        identity->epoch = __atomic_load_n(&g_slots[slot].snapshot_id.epoch,
                                          __ATOMIC_ACQUIRE);
        snapshot = 1;
    }
    return snapshot;
}

int
ls_vm_snapshot_call(int slot, const struct ls_snapshot_id *identity,
                    struct ls_snapshot_ctx *ctx)
{
    int completed = 0;
    uint32_t phase = ctx->phase;
    if (identity != NULL)
        (void)ls_vm_run(slot, ctx, sizeof *ctx, identity, &completed);
    if (!completed && slot >= 0 && slot < LS_MAX_SLOTS) {
        if (phase == LS_SNAPSHOT_ENTRY)
            g_slots[slot].snapshot_entry_errors++;
        else
            g_slots[slot].snapshot_return_errors++;
    }
    return completed ? 0 : -1;
}

/*
 * Publish a new program over a live slot. The whole point of this function is
 * the ORDER: everything expensive and everything fallible happens first, into
 * storage the data path cannot see, and the data path only ever observes a
 * single pointer store that is either the old program or the new one.
 *
 * What this is NOT: the ordered cross-core publish of item 0. A call already in
 * flight keeps the VM it loaded at entry; the next call gets the new one. That
 * is atomic-per-call replacement, which is sufficient for one hook and one
 * program and is not sufficient for a coordinated multi-hook update.
 *
 * The old VM is deliberately LEAKED. Freeing it needs proof that no core is
 * still inside it --- items 0b/0c --- and a wrong free here is a use-after-free
 * on the data path. Leaking is bounded by the number of loads and cannot
 * corrupt anything; a load loop would exhaust memory, which is a real limit
 * stated rather than hidden.
 */
int
ls_vm_reload(int slot, const void *elf, size_t elf_len,
             const char *section, const char *function, enum ls_mode m)
{
    if (slot < 0 || slot >= LS_MAX_SLOTS || !g_ready)
        return -1;

    /* Prepare into a spare slot: create, identity-check, load, JIT if asked.
     * All of it off the data path, all of it able to fail harmlessly. */
    int staged = ls_vm_arm(elf, elf_len, section, function, m);
    if (staged < 0)
        return -1;
    if (staged == slot)
        return slot;                      /* nothing was live here */

    struct ls_slot *live = &g_slots[slot];
    struct ls_slot *new  = &g_slots[staged];

    /* The publish. Release-ordered so each object's contents are visible to any
     * core that observes the pointer.
     *
     * jit_fn MUST be published with vm, and this is not a detail. ls_vm_call
     * prefers jit_fn whenever it is non-NULL and only falls back to the
     * interpreter when it is NULL --- so a swap that replaced vm alone left the
     * PREVIOUS program's compiled code executing while the new program sat in an
     * interpreter nothing ever consulted. Every load over the socket appeared to
     * succeed, the counters moved, and the resident program kept answering. The
     * two observable symptoms were a verdict that ignored the loaded program and
     * a slot whose behaviour never changed no matter what was sent to it.
     *
     * Order matters for a core already inside ls_vm_call:
     *   1. mode  -> DISABLE   readers take the early-out and fall through
     *   2. jit_fn-> NULL      no reader can enter the OLD compiled code
     *   3. vm    -> new       the interpreter now backs this slot
     *   4. jit_fn-> new       compiled path returns, matching the new vm
     *   5. mode  -> m         the slot goes live again
     * Steps 2-4 are what make (vm, jit_fn) observably one program rather than
     * two. A reader that sampled the old jit_fn before step 2 runs old compiled
     * code to completion, which is safe only because the old VM is leaked rather
     * than destroyed --- the code it points at stays mapped. That known debt
     * (item 0c) is load-bearing here; reclaiming it needs the quiescence pass,
     * not a free() in this function. */
    __atomic_store_n(&live->mode, LS_MODE_DISABLE, __ATOMIC_RELAXED);
    __atomic_store_n(&live->jit_fn, NULL, __ATOMIC_RELEASE);
    __atomic_store_n(&live->vm, new->vm, __ATOMIC_RELEASE);   /* old VM leaked */
    __atomic_store_n(&live->jit_fn, new->jit_fn, __ATOMIC_RELEASE);
    live->armed = true;
    live->is_exit = new->is_exit;   /* the kind rides with the program on the swap */
    live->is_snapshot = new->is_snapshot;
    live->snapshot_id = new->snapshot_id;
    __atomic_store_n(&live->mode, m, __ATOMIC_RELEASE);
    live->safe_value = new->safe_value; /* and its safe-return value (item 7) */
    live->gen++;              /* so STATUS can distinguish residue from result */

    new->armed = false;                   /* the staging slot goes back */
    new->vm = NULL;
    new->jit_fn = NULL;

    fprintf(stderr, "ls_vm: RELOADED slot=%d mode=%d bytes=%lu "
                    "(previous VM leaked --- reclamation is item 0c)\n",
            slot, (int)m, (unsigned long)elf_len);
    return slot;
}

void
ls_vm_set_mode(int slot, enum ls_mode m)
{
    if (slot < 0 || slot >= LS_MAX_SLOTS)
        return;
    if (g_slots[slot].is_snapshot) {
        if (m > LS_MODE_MONITOR)
            m = LS_MODE_DISABLE;
        uint64_t epoch = __atomic_load_n(&g_slots[slot].snapshot_id.epoch,
                                         __ATOMIC_RELAXED);
        if (epoch != UINT64_MAX)
            __atomic_store_n(&g_slots[slot].snapshot_id.epoch, epoch + 1,
                             __ATOMIC_RELEASE);
    }
    __atomic_store_n(&g_slots[slot].mode, m, __ATOMIC_RELEASE);
    fprintf(stderr, "ls_vm: slot=%d mode -> %d\n", slot, (int)m);
}

void
ls_vm_fini(void)
{
    ls_vm_report();
    for (int i = 0; i < LS_MAX_SLOTS; i++) {
        if (g_slots[i].armed) {
            ubpf_destroy(g_slots[i].vm);
            g_slots[i].armed = false;
        }
    }
    g_ready = false;
}

ls_vm.h.text:
/*
 * ls_vm.h --- the embedded eBPF VM, as TMM would see it.
 *
 * This is the smallest interface that makes "TMM has its own BPF VM" a true
 * statement: a VM instance owned by TMM, created at startup, holding verified
 * programs, callable from a TMM code path, with its result acted on.
 *
 * Four calls. Everything else in development-scope.md --- the trampoline, pad
 * rewriting, the safe point, the signing chain --- exists to hook functions
 * NOBODY PLANNED FOR. None of it is needed to embed the VM itself, which is why
 * this is the first increment rather than the last.
 *
 * Shape follows TMM's, and the reasons matter:
 *
 *   - ONE VM PER TMM INSTANCE, never shared. TMM is core-pinned and
 *     run-to-completion, so a per-instance VM needs no lock on the call path.
 *     A shared VM would need one, and a lock in the poll loop is the thing this
 *     design cannot afford.
 *   - INTERPRETER, not the native-code path, for the first cut. uBPF's
 *     instruction limit "has no effect on JIT'd programs" (ubpf.h) but does work
 *     in the interpreter, and the native path's prologue opens a 4KB frame with
 *     no guard-page probe at arbitrary call depth (findings O6, O7). Switching
 *     later is one call, once those are addressed.
 *   - THE CTX IS A COPY. PREVAIL cannot express a read-only region, so a verified
 *     program can write every byte of what it is handed (finding O1). Handing it
 *     a live view of TMM state would make the safety mechanism deliver a
 *     state-injection primitive. The caller fills a per-instance scratch struct.
 *
 * Status: candidate artifact. It compiles against the real uBPF headers. It is
 * not wired into TMM here --- see ls_vm.c for exactly which lines would be the
 * TMM-side change.
 */

#ifndef LS_VM_H
#define LS_VM_H

#include <stdbool.h>
#include <stddef.h>   /* size_t --- this header must stand alone */
#include <stdint.h>

/* PREVAIL's tracing descriptor (fentry/ and fexit/) permits 96 context bytes.
 * The JIT does not bounds-check these accesses: every trampoline must supply
 * the full allocation, with a zeroed tail, not just the fields a program uses.
 * Keep this in step with the pinned verifier; CONTESTED-PREMISES.md §17.
 */
#define LS_TRACING_CTX_SIZE 96u

struct ls_ctx_generic {
    uint64_t arg[5];
    uint64_t reserved[LS_TRACING_CTX_SIZE / sizeof(uint64_t) - 5];
};
_Static_assert(sizeof(struct ls_ctx_generic) == LS_TRACING_CTX_SIZE,
               "entry context must cover the verifier's tracing region");
_Static_assert(offsetof(struct ls_ctx_generic, reserved) == 40,
               "entry argument offsets must not change");

/* Outcomes the host owns. The program SELECTS one; the host APPLIES it. In
 * observe mode the host counts the selection and applies nothing --- observe is
 * not a seventh outcome (substrate §2). */
enum ls_verdict {
    LS_FALLTHROUGH = 0,   /* run the original function body                */
    LS_SAFE_RETURN = 1,   /* skip the body, return the declared safe value */
};

enum ls_mode {
    LS_MODE_DISABLE = 0,
    LS_MODE_MONITOR = 1,  /* evaluate and count; do not apply */
    LS_MODE_ENFORCE = 2,
};

/* The last few ctx values the hook was called with.
 *
 * Move-4 instrument: when the hook starts firing, `fired > 0` with
 * `safe_returns == 0` is ambiguous --- the shield may be wrong, or the CVE
 * condition may simply never have arrived. Without a sample there is no way to
 * tell those apart, and they call for opposite responses.
 *
 * Deliberately tiny and fixed: 8 entries of 32 bytes, in the slot, overwritten
 * oldest-first. This is development-scope.md item 14's ring at a scale that
 * needs no allocator, no drain agent and no backpressure policy --- the real one
 * is per-core shared memory with a consumer ABI. Sized to answer one question,
 * not to be that. */
#define LS_CTX_SAMPLES 8
#define LS_CTX_SAMPLE_BYTES 48   /* fits the fexit payload (arg[5] + ret = 48B), so a
                                  * sample captures the RETURN VALUE at offset 40, not
                                  * just the first four args. Was 32 (entry ctx only). */

struct ls_ctx_sample {
    uint64_t seq;                              /* which invocation this was  */
    uint32_t len;                              /* the ctx's real length      */
    uint32_t verdict;
    uint8_t  bytes[LS_CTX_SAMPLE_BYTES];       /* truncated, deliberately    */
};

/* One armed program. TMM holds a small fixed array of these per instance ---
 * fixed because allocating on the call path is not acceptable. */

#include "ls_snapshot.h"

struct ls_slot {
    void        *vm;        /* struct ubpf_vm *, opaque here          */
    void        *jit_fn;    /* ubpf_jit_fn when JIT'd; NULL = interpret.
                             * Held separately because ubpf_exec never
                             * dispatches to compiled code --- the pointer IS
                             * the only route to it. */
    enum ls_mode mode;
    bool         armed;
    bool         is_exit;       /* fexit hook: arm via ls_fexit_table, not the
                                 * entry table. Set at load from the program's
                                 * fexit/ vs fentry/ section; read at arm. */
    bool         is_snapshot;
    struct ls_snapshot_id snapshot_id;
    uint64_t     snapshot_entry_errors;
    uint64_t     snapshot_return_errors;
    uint64_t     safe_value;    /* what the CALLER receives when SAFE_RETURN skips
                                 * the body (item 7). ZERO IS NOT UNIVERSALLY SAFE:
                                 * for an err_t-returning hook 0 is ERR_OK ---
                                 * "succeeded" --- so a shield that skips dtls_tx
                                 * must return ERR_BUF(2), not 0, or it converts a
                                 * crash into silent misbehaviour. Set per arm
                                 * (LS_SHIELD_SAFE_VALUE); delivered by
                                 * ls_tramp_dispatch. */
    uint64_t     fired;         /* per-instance; a box-wide sum is wrong */
    uint64_t     safe_returns;
    uint64_t     errors;        /* exec faults: fuel exhausted, bounds  */
    uint64_t     cycles;        /* only when timing is enabled          */
    uint64_t     cycles_max;    /* the tail is what bounds a hot hook   */
    uint64_t     cycles_min;    /* the floor: least preemption-polluted */
    uint32_t     gen;           /* bumped per reload. Counters above are
                                 * per SLOT and SURVIVE a program swap ---
                                 * on 2026-08-17 a safe_returns=246 left by
                                 * one program was twice read as evidence
                                 * about the next. `gen` lets a reader tell
                                 * residue from result. */
    struct ls_ctx_sample samples[LS_CTX_SAMPLES];
    uint32_t     sample_next;
};

/* A snapshot of one slot, for whatever eventually reports these. Copied rather
 * than returning a pointer, because the caller must not be able to reach into
 * live VM state. The permanent home for these numbers is `tmstat`, TMM's own
 * statistics mechanism, which is already linked into the runtime image ---
 * see development-scope.md item 14. Until then, logging. */
struct ls_stats {
    bool     armed;
    bool     is_exit;        /* fexit hook (armed via ls_fexit_table) */
    int      mode;
    uint64_t fired;
    uint64_t safe_returns;
    uint32_t gen;            /* increments per reload --- see ls_vm_stats */
    uint64_t errors;
    uint64_t cycles;
    uint64_t cycles_max;
    uint64_t cycles_min;
    uint64_t snapshot_entry_errors;
    uint64_t snapshot_return_errors;
};

/* The form TMM actually calls. Applies the environment overrides --- program
 * source, section, function, mode --- over the compiled-in defaults, so the
 * call site never has to know they exist. Pass the built-in blob and its two
 * identities; LS_SHIELD_PATH replaces the blob, LS_SHIELD_SECTION and
 * LS_SHIELD_FUNCTION replace the names, LS_SHIELD_MODE replaces the mode.
 *
 * This is what makes a shield change a pod restart rather than a rebuild. */
int ls_vm_arm_configured(const void *blob, size_t blob_len,
                         const char *section, const char *function);

/* Off the data path. Returns false for an out-of-range slot. */
/* The single STT_FUNC symbol defined in `section` of `elf`, copied into out[outlen].
 * Returns its length, or 0 if none/ambiguous. Lets the loader take a program's entry
 * function FROM the object it verified, instead of assuming a fixed name. */
size_t ls_function_in_section(const void *elf, size_t elf_len, const char *section,
                              char *out, size_t outlen);

bool ls_vm_stats(int slot, struct ls_stats *out);

/* The value the trampoline hands the hooked function's caller on SAFE_RETURN for
 * this slot (item 7). Off the data path only in that it is read once per skipped
 * call; returns 0 for an out-of-range or unarmed slot, which is the fail-safe for
 * a pointer/BOOL return and the documented wrong answer for an err_t one --- which
 * is why it is configurable. */
uint64_t ls_vm_safe_value(int slot);

/* Copy out the recent ctx samples. Off the data path. Returns how many were
 * written, up to LS_CTX_SAMPLES. */
unsigned ls_vm_samples(int slot, struct ls_ctx_sample *out, unsigned max);

/* Benchmark an ARBITRARY program without arming it onto a hook --- move-3
 * instrument. Loading a program, benching it and discarding it is what turns
 * budget-pass calibration from one restart per data point into one message per
 * data point. Returns 0 on success and fills min/mean/max.
 *
 * QUOTE THE MIN. The mean is 2-3x it and swings run to run --- 194 to 538 for one program on
 * an idle box --- because a single rdtsc pair spanning a context switch dominates the total.
 * That is the same effect that makes the armed-hook counter mean unusable, and it is why the
 * max is reported: seeing 130,720 next to a min of 132 is what tells a reader the mean is
 * measuring the scheduler.
 *
 * `jitted_out` says WHICH EXECUTION PATH was measured, and it is not optional information.
 * This function used to time the interpreter unconditionally while every armed hook runs
 * jit_fn, so the figure described a path nothing uses. It now compiles when the configuration
 * does, falls back to the interpreter if the JIT fails, and reports which happened --- a
 * caller that ignores this can publish an interpreter number as a hook cost, which is the
 * mistake the flag exists to prevent. Pass NULL only if you genuinely do not care.
 *
 * IT IS STILL A FLOOR, not the cost of an armed hook. It measures program execution in a
 * tight loop with a warm cache and no contention. A live hook additionally pays the
 * trampoline's register save and restore, the call and return, and cache effects from real
 * traffic. */
int ls_vm_bench_program(const void *elf, size_t elf_len,
                        const char *section, const char *function,
                        uint32_t iters,
                        uint64_t *min_out, uint64_t *mean_out, uint64_t *max_out,
                        int *jitted_out);

/* Whether signature enforcement is on --- see ls_vm_config.c for why the opt-out is a word
 * rather than a boolean. Exported so the loader does not become a second reader of the
 * environment; the one thing two config readers must never disagree about is whether a
 * security gate is armed. */
int ls_vm_sig_enforce(void);

/* Log the current counters for every armed slot. Called at fini, every
 * LS_VM_REPORT_EVERY invocations, and on demand. */
void ls_vm_report(void);

/* Create this instance's VM state. Called once per TMM instance at startup,
 * off the data path. Returns false and leaves nothing armed on any failure ---
 * a TMM that cannot bring up the VM must run exactly as it does today. */
bool ls_vm_init(void);

/* Load a VERIFIED, SIGNED program object into a slot and arm it. Off the data
 * path (admission time). Signature checking happens BEFORE this.
 *
 * BOTH names are required, and that is not redundancy --- the verifier and the
 * runtime identify a program differently:
 *
 *   PREVAIL  selects by ELF SECTION name   ("fentry/<hook>")
 *   uBPF     selects by FUNCTION SYMBOL    ("shield")   [ubpf_loader.c:271,
 *            despite its header calling the parameter `main_section_name`]
 *
 * So "PREVAIL verified this object" and "uBPF is about to run this program" are
 * statements about two different identities, and in an object carrying several
 * functions they can denote different code. This function refuses unless the
 * named symbol actually lives in the named section --- see finding O14. Passing
 * one name and hoping is how a verified-but-not-the-verified-one program loads.
 *
 * Returns the slot index, or -1. */
int ls_vm_arm(const void *elf, size_t elf_len,
              const char *section, const char *function, enum ls_mode m);

/* THE CALL PATH. Everything above is setup; this is the part that runs per
 * invocation and the only part whose cost is in the poll loop.
 *
 * ctx points at the caller's scratch copy of the fields the program needs.
 * Returns the verdict the host must apply, or LS_FALLTHROUGH on any error ---
 * fail-open is correct HERE and only here: a shield that cannot run must not
 * take TMM down with it. Admission fails closed; invocation fails open. */
enum ls_verdict ls_vm_call(int slot, void *ctx, size_t ctx_len);

/* Frame-bound completion mode. Identity is read on the owning TMM thread.
 * Execution failure is distinct from a program's FALLTHROUGH verdict. */
int ls_vm_snapshot_identity(int slot, struct ls_snapshot_id *identity);
int ls_vm_snapshot_call(int slot, const struct ls_snapshot_id *identity,
                        struct ls_snapshot_ctx *ctx);

/* Runtime load path (ls_vm_load.c). Started only if LS_LOAD_SOCKET is set.
 * VERIFIES EVERY PROGRAM'S SIGNATURE (ls_sig.c) and NOTHING ABOUT ITS SENDER: the
 * socket has no peer authentication, so the env gate and the 0600 mode are what
 * limit who may ask. Off by default for that reason --- which is a different reason
 * from the one this comment carried until 2026-08-20. */
void ls_vm_loader_start(void);

int  ls_vm_reload(int slot, const void *elf, size_t elf_len,
                  const char *section, const char *function, enum ls_mode m);
void ls_vm_set_mode(int slot, enum ls_mode m);

void ls_vm_fini(void);

#endif /* LS_VM_H */

ls_vm_config.c.text:
/*
 * ls_vm_config.c --- read the knobs once, at init.
 *
 * Deliberately dull. Every value is read from the environment exactly once, off
 * the data path, with a default that matches the shipped behaviour --- so an
 * unset environment behaves identically to the version before this file existed.
 * An unrecognised value falls back to the default rather than failing: a typo in
 * a pod spec should not stop TMM starting.
 */

#include "ls_vm_config.h"

#include <stdlib.h>
#include <string.h>

static bool
env_bool(const char *name, bool dflt)
{
    const char *v = getenv(name);
    if (v == NULL || *v == '\0')
        return dflt;
    if (!strcmp(v, "1") || !strcasecmp(v, "true") || !strcasecmp(v, "yes"))
        return true;
    if (!strcmp(v, "0") || !strcasecmp(v, "false") || !strcasecmp(v, "no"))
        return false;
    return dflt;
}

static uint32_t
env_u32(const char *name, uint32_t dflt)
{
    const char *v = getenv(name);
    if (v == NULL || *v == '\0')
        return dflt;
    char *end = NULL;
    unsigned long n = strtoul(v, &end, 10);
    if (end == v || *end != '\0' || n > 0xffffffffUL)
        return dflt;
    return (uint32_t)n;
}

static const char *
env_str(const char *name, const char *dflt)
{
    const char *v = getenv(name);
    return (v && *v) ? v : dflt;
}

/* disable=0, monitor=1, enforce=2 --- matching enum ls_mode. Accepts the words
 * because a pod spec is written by a person, not by the enum. */
static int
env_mode(const char *name, int dflt)
{
    const char *v = getenv(name);
    if (v == NULL || *v == '\0')
        return dflt;
    if (!strcasecmp(v, "disable") || !strcmp(v, "0")) return 0;
    if (!strcasecmp(v, "monitor") || !strcmp(v, "1")) return 1;
    if (!strcasecmp(v, "enforce") || !strcmp(v, "2")) return 2;
    return dflt;
}

void
ls_vm_config_load(struct ls_vm_config *c)
{
    if (c == NULL)
        return;
    memset(c, 0, sizeof *c);
    c->enable       = env_bool("LS_SHIELD_ENABLE", true);
    c->builtin      = env_bool("LS_SHIELD_BUILTIN", false);  /* compiled-in blob OFF by default */
    c->mode         = env_mode("LS_SHIELD_MODE", 2 /* enforce */);
    c->path         = env_str ("LS_SHIELD_PATH", NULL);
    c->section      = env_str ("LS_SHIELD_SECTION", NULL);
    c->function     = env_str ("LS_SHIELD_FUNCTION", NULL);
    c->fuel         = env_u32 ("LS_VM_FUEL", 0);
    c->jit          = env_bool("LS_VM_JIT", false);
    c->bench        = env_u32 ("LS_VM_BENCH", 0);
    c->timing       = env_bool("LS_VM_TIMING", false);
    c->report_every = env_u32 ("LS_VM_REPORT_EVERY", 0);
    c->samples      = env_bool("LS_VM_SAMPLES", false);
    c->selftest     = env_u32 ("LS_VM_SELFTEST", 0);
    c->verbose      = env_bool("LS_VM_VERBOSE", false);
    /*
     * SIGNATURE ENFORCEMENT, AND WHY THIS ONE IS NOT env_bool.
     *
     * A toggle on a security gate is the thing that ends up left off, so this one is
     * deliberately awkward in three ways that the other options are not:
     *
     *   1. It DEFAULTS ON. Absent, empty, misspelled, or set to anything this does not
     *      recognise all mean ENFORCE. env_bool would treat a typo as false for some inputs;
     *      here every value that is not the exact opt-out string enforces. A fat-fingered pod
     *      spec must not disable verification.
     *   2. The opt-out is a WORD, not "0" or "false". "LS_SIG_ENFORCE=i-am-debugging" cannot be
     *      arrived at by accident and cannot be mistaken for a tidy production setting when
     *      someone reads the manifest six months from now.
     *   3. It is read at STARTUP ONLY, never over the loader socket. An op that disables
     *      verification would hand the gate's own key to anyone who can reach the socket ---
     *      which is precisely the population the gate exists to constrain.
     *
     * ls_vm_load.c shouts on every load when this is off, for the same reason the pre-signature
     * loader shouted `unverified=yes`: a debugging session must not quietly become a demo.
     */
    {
        const char *v = getenv("LS_SIG_ENFORCE");
        c->sig_enforce = !(v != NULL && !strcmp(v, "i-am-debugging"));
    }
}

ls_vm_load.c.text:
/*
 * ls_vm_load.c --- load a program into a RUNNING TMM.
 *
 * This is the step that separates the demonstration from a patch. Rungs:
 *
 *   1. compiled in                 -> rebuild, repackage, redeploy
 *   2. LS_SHIELD_PATH at startup   -> no rebuild, but a restart
 *   3. THIS FILE                   -> no rebuild, no restart, no window
 *
 * =====================================================================
 *  WHAT THIS DELIBERATELY DOES NOT DO --- read before enabling it
 * =====================================================================
 *
 *  LOAD verifies the signed binding and program hash on a TMM prepare thread.
 *  The program carries a build-resolved .ls.target record; ARM is constrained to
 *  that authenticated entry. Socket caller authentication remains separate work.
 *
 *  NO RECLAMATION. A swapped-out VM is never freed. Freeing it requires knowing
 *  that no core is still executing it, which is the cross-core rendezvous of
 *  development-scope.md items 0b/0c and is not written. Leaking is the honest
 *  choice here: bounded by the number of loads, and it cannot corrupt anything.
 *  A load loop would eventually exhaust memory --- that is a real limit, stated
 *  rather than hidden.
 *
 *  NO SAFE POINT. The swap is a single atomic pointer store, which is why it is
 *  safe *enough* without one: a call in flight keeps using the VM it loaded at
 *  entry, and the next call picks up the new one. That gives atomic-per-call
 *  replacement, NOT the ordered cross-core publish item 0 specifies. For one
 *  hook and one program it is sufficient; for a multi-hook coordinated update it
 *  is not, and the difference is exactly item 0.
 *
 * The thread is a real design choice, not laziness: preparation --- create the
 * VM, read the ELF, check the O14 identity, JIT if asked --- is unbounded work
 * that must never happen on the poll loop. It happens here, and the poll loop
 * only ever sees a pointer that is either the old program or the new one.
 */

#include "ls_vm.h"
#include "ls_sig.h"
#include "ls_audit.h"
#include "ls_build_gate.h"
#include "ls_target.h"
#include <time.h>
#include "ls_map.h"
/* This file OWNS the map glue's state --- see ls_map_glue.h. Exactly one TU may
 * define this; a second one fails the link on a duplicate symbol. */
#define LS_MAP_GLUE_IMPL 1
#include "ls_map_glue.h"
#include "ls_arm.h"
#include "ls_shield_blob.h"
#include <stdlib.h>

extern void ls_trampoline_entry(void);
#include "ls_vm_config.h"
#include "shield_abi.h"

#include <errno.h>
#include <stdarg.h>
#include <pthread.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/random.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <sys/un.h>
#include <unistd.h>

/* Bounded so a malformed length field cannot make us allocate arbitrarily.
 * prog_len arrives from outside and is read before anything authenticates it,
 * which is the exact shape finding O8 was filed about --- so it is checked
 * against the bytes actually received, not trusted. */
#define LS_LOAD_MAX (1u << 20)

/* ------------------------------------------------------------------------
 * Preparation handoff: loader thread -> TMM thread.
 *
 * ubpf_create/ubpf_load_elf/ubpf_compile all allocate, and allocation on a
 * thread we created hangs forever inside TMM's allocator (kern/malloc.c:48 ->
 * init_thread_cache -> spin_lock on a lock nothing ever spin_init'd, because
 * sthread_handler_register is only called by if_xnet.c and BNK has no xnet).
 * Measured, not inferred: the loader goes on-CPU and never returns.
 *
 * So the loader does no preparation. It parks a request here and a TMM thread
 * --- where umalloc works --- performs it.
 * --------------------------------------------------------------------- */
#define LS_PREP_IDLE     0
#define LS_PREP_PENDING  1
#define LS_PREP_DONE     2

/* B6: bound what one request may ask a poll iteration to do. Prepare cost is
 * dominated by program size once the scratch is right-sized, so an unbounded
 * length is an unbounded stall. 256 KB is far above any real shield (the
 * built-in one is 4320 bytes) and far below anything that would matter. */
#define LS_PREP_MAX_PROG (256u * 1024u)


/* How long the loader waits before giving up. A prepare that never completes
 * means the owning TMM thread is not running its timers; say so rather than
 * hanging the way this code used to. */
#define LS_PREP_WAIT_MS  5000

/*
 * WHICH PIECE OF WORK THE TMM THREAD IS BEING ASKED TO DO.
 *
 * ONE request struct and ONE state machine for both, rather than a second copy of the
 * handoff. The socket is serial, so "one outstanding at a time" is already the model, and
 * the subtle parts here --- the IDLE/PENDING/DONE transitions, the timeout that deliberately
 * leaves a late request PENDING, the refusal when one is already outstanding --- are exactly
 * what a parallel implementation would get subtly wrong.
 */
#define LS_PREP_OP_RELOAD 0
#define LS_PREP_OP_BENCH  1

/*
 * BENCH RUNS N ITERATIONS INSIDE A POLL ITERATION, which RELOAD does not, so it needs its own
 * bound. ls_vm_bench_program creates a VM, JITs, executes `iters` times and destroys it, all
 * on the TMM thread that picks the request up --- because that is the only thread where
 * umalloc works. Every one of those iterations is time that thread is not polling.
 *
 * At a plausible tens-of-nanoseconds per call, 10,000 iterations is well under a millisecond;
 * the prepare timer's own period is 10 ms. But "plausible" is doing the work in that sentence
 * --- the per-call cost is the number this op exists to establish, so the stall cannot be
 * computed in advance from anything but a guess. The cap is therefore set where a pessimistic
 * 1 us per call would still stall one thread for 20 ms rather than seconds.
 *
 * This is a DEVELOPMENT op. It briefly stalls one TMM thread on purpose, and it must not
 * appear in a control plane. The header above this switch says the same about all the 0x100x
 * ops; this one now has a reason beyond taste.
 */
#define LS_PREP_BENCH_MAX_ITERS 20000u

struct ls_prep {
    volatile int state;          /* LS_PREP_* --- the only cross-thread word    */
    int          op;             /* LS_PREP_OP_*                                */
    int          slot;
    const void  *prog;           /* into the loader's mmap scratch; alive until DONE */
    unsigned int prog_len;
    unsigned char mode;
    char         section[80];
    char         function[64];
    unsigned int iters;          /* bench only                                  */
    uint64_t     bmin, bmean, bmax;   /* bench results                          */
    /* Copied into the request because the wire buffer belongs to the loader thread and is
     * reused; the TMM thread must not read from it after the loader has moved on. */
    unsigned char binding[112];
    unsigned char sig[64];
    int          verify;         /* 0 for ops that carry no signature (bench)   */
    int          bjitted;        /* 1 = the JIT was measured, 0 = the interpreter.
                                  * Reported to the client, because a number from
                                  * the interpreter is not a hook cost and nothing
                                  * else in the reply would say so. */
    int          rc;             /* slot on success, negative on refusal        */
    /* Control-path only, serialized by the loader/prepare handoff. Kept here so
     * target authorization needs no additional mutable TMM linker global. */
    struct {
        struct ls_target target;
        char hook[SHIELD_HOOK_NAME_MAX];
        unsigned char ceiling;
        int valid, attached;
    } targets[SHIELD_MAX_SHIELDS];
};

/* What the loader reads back. COPIED OUT before the slot returns to IDLE, so a caller can
 * never read results that a subsequent request has begun overwriting. The socket is serial
 * today and this costs three words. */
struct ls_prep_result {
    int      rc;
    uint64_t bmin, bmean, bmax;
    int      jitted;
};

/* The copied buffers must be exactly the ABI's sizes, or a signature is computed over
 * different bytes than were signed. Asserted rather than commented, because the two
 * declarations sit 400 lines apart. */
_Static_assert(sizeof(((struct ls_prep *)0)->binding) == sizeof(struct shield_binding),
               "ls_prep's binding copy has drifted from struct shield_binding");
_Static_assert(sizeof(((struct ls_prep *)0)->sig) == SHIELD_SIG_MAX,
               "ls_prep's signature copy has drifted from SHIELD_SIG_MAX");

static struct ls_prep g_prep;

/* Set by ls_prep.c once a TMM thread owns the timer. Read here only to refuse a
 * load that could never be serviced. */
int ls_prep_timer_on;

/* Provided by ls_prep.c, which is compiled in TMM's include world because the
 * timer and `tid` live there. Kept to a void(void) so no TMM type crosses into
 * this file --- it is built STDINC and syntax-checked standalone. */
extern void ls_prep_timer_start(void);

/* Called from ls_prep.c on a TMM thread. Declared because it is not static. */
void ls_prep_run_pending(void);

/* THE WORK. Called from ls_prep.c's timer callback, so it runs on a TMM thread
 * where umalloc works. Short by construction: it is inside a poll iteration.
 * Lives here rather than there so everything touching the request state stays
 * in one file. */
void
ls_prep_run_pending(void)
{
    if (__atomic_load_n(&g_prep.state, __ATOMIC_ACQUIRE) != LS_PREP_PENDING)
        return;

    /* Everything below allocates. That is the entire point of being here. */

    /* SIGNATURE BEFORE ANYTHING ELSE TOUCHES THE PROGRAM. EVP allocates, which is why this is
     * here and not on the loader thread --- see the note at SHIELD_OP_LOAD. A refusal returns
     * a negative rc, which the loader reports exactly as it reports any other refusal, so the
     * caller cannot distinguish "bad signature" from "bad ELF" and cannot probe which half of
     * a forgery to fix. */
    if (g_prep.op == LS_PREP_OP_RELOAD && g_prep.verify) {
        enum ls_sig_result sr = ls_sig_verify(g_prep.binding, sizeof g_prep.binding,
                                             g_prep.sig, 64u,
                                             g_prep.prog, g_prep.prog_len);
        if (sr != LS_SIG_OK && !ls_vm_sig_enforce()) {
            fprintf(stderr, "ls_vm: *** SIGNATURE CHECK FAILED (%s) AND ADMITTED ANYWAY --- "
                            "LS_SIG_ENFORCE is off. This build trusts whatever reaches the "
                            "socket.\n", ls_sig_strerror(sr));
            sr = LS_SIG_OK;
        }
        if (sr != LS_SIG_OK) {
            fprintf(stderr, "ls_vm: LOAD REFUSED --- %s\n", ls_sig_strerror(sr));
            g_prep.rc = -1;
            __atomic_store_n(&g_prep.state, LS_PREP_DONE, __ATOMIC_RELEASE);
            return;
        }
    }

    if (g_prep.op == LS_PREP_OP_BENCH) {
        /* THE FIX THIS STRUCTURE EXISTED FOR ALREADY. ls_vm_bench_program used to be called
         * straight from the loader thread, which hits the identical allocator freeze that
         * this handoff was built to avoid for loads --- the dev ops were simply never
         * converted. Running it wedged the loader (tid RUNNING, on-CPU) while the proxy kept
         * serving, and it is why no per-call shield cost has been quotable from a live TMM:
         * the counter mean measures the scheduler, and the clean number is this op's min. */
        g_prep.rc = ls_vm_bench_program(g_prep.prog, g_prep.prog_len,
                                        g_prep.section, g_prep.function, g_prep.iters,
                                        &g_prep.bmin, &g_prep.bmean, &g_prep.bmax,
                                        &g_prep.bjitted);
    } else {
        struct ls_target target;
        struct shield_binding binding_copy;
        memcpy(&binding_copy, g_prep.binding, sizeof binding_copy);
        const struct shield_binding *binding = &binding_copy;
        int slot = g_prep.slot;
        /* A signed name alone cannot authorize an independently supplied ARM
         * address. Resolve on the build box, sign the record with the program,
         * and validate it before publishing anything into a live slot. */
        if (slot < 0 || (unsigned)slot >= SHIELD_MAX_SHIELDS ||
            !memchr(binding->hook, 0, sizeof binding->hook) ||
            binding->mode_ceiling > MODE_ENFORCE || g_prep.mode > binding->mode_ceiling ||
            ls_target_parse(g_prep.prog, g_prep.prog_len, g_prep.section,
                            ls_audit_build_id(), &target) != 0 ||
             ls_target_check_file("/proc/self/exe", &target) != 0) {
            fprintf(stderr, "ls_vm: LOAD REFUSED --- signed target/build/mode contract\n");
            g_prep.rc = -1;
            __atomic_store_n(&g_prep.state, LS_PREP_DONE, __ATOMIC_RELEASE);
            return;
        }
        if (!memcmp(target.magic, LS_TARGET_SNAPSHOT_MAGIC, 8) &&
            (binding->mode_ceiling > MODE_MONITOR ||
             g_prep.mode > MODE_MONITOR)) {
            fprintf(stderr, "ls_vm: LOAD REFUSED --- snapshot is observe-only\n");
            g_prep.rc = -1;
            __atomic_store_n(&g_prep.state, LS_PREP_DONE, __ATOMIC_RELEASE);
            return;
        }
        if (g_prep.targets[slot].attached &&
            (memcmp(&target, &g_prep.targets[slot].target, sizeof target) ||
             strcmp(binding->hook, g_prep.targets[slot].hook))) {
            fprintf(stderr, "ls_vm: LOAD REFUSED --- disarm before changing target or kind\n");
            g_prep.rc = -1;
            __atomic_store_n(&g_prep.state, LS_PREP_DONE, __ATOMIC_RELEASE);
            return;
        }
        uint64_t instance = ls_config_new_instance(&g_ls_config, (unsigned)slot);
        if (!instance || atomic_load(&g_ls_config.slots[slot].sequence) > UINT64_MAX - 2) {
            g_prep.rc = -1;
            __atomic_store_n(&g_prep.state, LS_PREP_DONE, __ATOMIC_RELEASE);
            return;
        }
        g_ls_config.loading = instance;
        g_prep.rc = ls_vm_reload(g_prep.slot, g_prep.prog, g_prep.prog_len,
                                  g_prep.section, g_prep.function,
                                   (enum ls_mode)g_prep.mode);
        g_ls_config.loading = 0;
        if (g_prep.rc >= 0) {
            /* New VM may briefly see unavailable input before this publication;
             * it can never see the previous instance's configuration. */
            if (ls_config_bind(&g_ls_config, (unsigned)slot, instance,
                               binding->prog_sha256) != 0) {
                ls_vm_set_mode(slot, LS_MODE_DISABLE);
                g_prep.rc = -1;
                __atomic_store_n(&g_prep.state, LS_PREP_DONE, __ATOMIC_RELEASE);
                return;
            }
            g_prep.targets[slot].target = target;
            memcpy(g_prep.targets[slot].hook, binding->hook, sizeof binding->hook);
            g_prep.targets[slot].ceiling = binding->mode_ceiling;
            g_prep.targets[slot].valid = 1;
        }
    }

    __atomic_store_n(&g_prep.state, LS_PREP_DONE, __ATOMIC_RELEASE);
}

/* Loader side. Parks the request, waits for a TMM thread to do it, returns the
 * slot or negative. Allocates nothing --- nanosleep is a syscall, which is the
 * one thing this thread can safely do. */
static int
ls_prep_submit(int op, int slot, const void *prog, unsigned int prog_len,
               const char *section, const char *function, unsigned char mode,
               unsigned int iters, const void *binding, const void *sig,
               struct ls_prep_result *out, const char **why)
{
    if (!ls_prep_timer_on) {
        *why = "prepare handoff not armed (no TMM thread owns the timer)";
        return -1;
    }
    if (prog_len > LS_PREP_MAX_PROG) {
        *why = "program exceeds the accepted size ceiling";
        return -1;
    }
    /* One request at a time. The socket is serial, so this only trips if a
     * previous prepare never completed. */
    if (__atomic_load_n(&g_prep.state, __ATOMIC_ACQUIRE) != LS_PREP_IDLE) {
        *why = "a previous prepare is still outstanding";
        return -1;
    }

    g_prep.op       = op;
    g_prep.slot     = slot;
    g_prep.prog     = prog;
    g_prep.prog_len = prog_len;
    g_prep.mode     = mode;
    g_prep.iters    = iters;
    /* COPY the signature material now, on this thread. The wire buffer is the loader's and is
     * reused for the next request; the TMM thread reads these after this function has returned. */
    g_prep.verify   = 0;
    if (binding != NULL && sig != NULL) {
        memcpy(g_prep.binding, binding, sizeof g_prep.binding);
        memcpy(g_prep.sig,     sig,     sizeof g_prep.sig);
        g_prep.verify = 1;
    }
    g_prep.bmin = g_prep.bmean = g_prep.bmax = 0;
    /* snprintf, not strlcpy: this file is STDINC and strlcpy is not in the
     * standard C library it gets. Both truncate safely and NUL-terminate. */
    snprintf(g_prep.section,  sizeof g_prep.section,  "%s", section);
    snprintf(g_prep.function, sizeof g_prep.function, "%s", function);
    g_prep.rc = -1;

    __atomic_store_n(&g_prep.state, LS_PREP_PENDING, __ATOMIC_RELEASE);

    for (int waited = 0; waited < LS_PREP_WAIT_MS; waited++) {
        if (__atomic_load_n(&g_prep.state, __ATOMIC_ACQUIRE) == LS_PREP_DONE) {
            int rc = g_prep.rc;
            /* COPY BEFORE RELEASING. Once state is IDLE the struct belongs to whoever
             * submits next, so reading g_prep afterwards is a race that the serial socket
             * happens to hide today. Three words is not a price worth paying for that. */
            if (out != NULL) {
                out->rc    = rc;
                out->bmin   = g_prep.bmin;
                out->bmean  = g_prep.bmean;
                out->bmax   = g_prep.bmax;
                out->jitted = g_prep.bjitted;
            }
            __atomic_store_n(&g_prep.state, LS_PREP_IDLE, __ATOMIC_RELEASE);
            if (rc < 0)
                *why = "identity mismatch, malformed ELF, or uBPF rejected it";
            return rc;
        }
        {
            struct timespec ms = { 0, 1000000 };   /* 1 ms */
            nanosleep(&ms, NULL);
        }
    }

    /* Left PENDING deliberately: if the TMM thread is merely late it will still
     * complete, and the next submit is refused rather than racing this one. */
    *why = "timed out waiting for a TMM thread to prepare it";
    return -1;
}

static pthread_t g_loader;
static int       g_loader_running;
static char      g_sock_path[108];

/* Provided by ls_vm.c: prepare a program into a spare slot and publish it over
 * an existing one with a single atomic store. */
extern int  ls_vm_reload(int slot, const void *elf, size_t elf_len,
                         const char *section, const char *function, enum ls_mode m);
extern void ls_vm_set_mode(int slot, enum ls_mode m);

/* WHAT WAS SAID TO THE CALLER is handed to ls_audit so the record can quote it verbatim instead
 * of deriving a second verdict from the same inputs. Two independently computed answers to "was
 * this allowed" is how an audit trail comes to disagree with what happened, and a trail that
 * disagrees is worse than none: it will be believed.
 *
 * THE BUFFER LIVES IN ls_audit.c, not here, and that is a build constraint rather than a
 * preference. TMM's link gate (bin/diff-globals) keeps an exact manifest of every mutable
 * global, so a static buffer here would be a second permanent entry for one feature. It belongs
 * to the audit trail, so it lives with the audit trail's single state struct.
 *
 * One static is correct only because the loader is single-threaded: one accept loop, one
 * connection at a time, so exactly one request is in flight. If that ever changes this must
 * become per-connection state, and no assertion here can catch it --- hence the sentence. */
static void
reply(int fd, const char *fmt, ...)
{
    char buf[512];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof buf, fmt, ap);
    va_end(ap);
    if (n > 0) {
        ls_audit_note_reply(buf);
        (void)!write(fd, buf, (size_t)n);
    }
}

/* Scratch for one control message, from the kernel rather than from malloc.
 *
 * malloc() is NOT usable on this thread. TMM aliases it to __wrap_malloc
 * (kern/malloc.c:48), which routes every allocation through per-thread or
 * per-core state --- sthread_malloc's stats row, umalloc's per-core arena, or a
 * raw spin_lock on the bootstrap heap. The loader is a plain pthread we
 * created: it is neither a TMM poll thread nor a registered DPDK service
 * thread, so it has none of that state, and the allocator spins. Measured as
 * 20/20 samples of /proc/<tid>/syscall reading "running" --- on-CPU, never in a
 * syscall --- with the arm op wedged before its first line of output.
 *
 * sthread_handler_register() is the supported way to register a foreign thread
 * and is deliberately not used: init_thread_row() (kern/sthread_memory.c:66)
 * leaks thread_stats_lock on both error paths and leaves thread_stats NULL for
 * _sthread_malloc() to dereference. Not a trade worth making for scratch space.
 *
 * mmap keeps the property the previous comment was protecting --- a 1 MB static
 * buffer is 1 MB of resident .bss in EVERY instance, one per core, for a
 * message that arrives approximately never (measured: +15.6% .bss). This
 * mapping is per-connection and released on every exit path. */
static unsigned char *
ls_load_buf_alloc(void)
{
    void *p = mmap(NULL, LS_LOAD_MAX, PROT_READ | PROT_WRITE,
                   MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    return (p == MAP_FAILED) ? NULL : (unsigned char *)p;
}

static void
ls_load_buf_free(unsigned char *p)
{
    if (p != NULL)
        (void)munmap(p, LS_LOAD_MAX);
}

/* Shared framing for all operations; also exercised through real Unix sockets
 * by check_config_socket.c without booting a TMM. */
static int
ls_load_receive(int fd, unsigned char *g_load_buf, struct shield_msg **seen,
                struct shield_msg *copy)
{
    /* SOCK_STREAM has no message boundaries. Read the fixed header, then its
     * bounded payload; a fragmented send is not a short-message refusal. */
    struct timeval timeout = {5, 0};
    if (setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof timeout) != 0) {
        reply(fd, "ERR receive timeout setup failed\n");
        return -1;
    }
    ssize_t n = recv(fd, g_load_buf, sizeof(struct shield_msg), MSG_WAITALL);

    if (n < (ssize_t)sizeof(struct shield_msg)) {
        reply(fd, "ERR short message (%ld bytes)\n", (long)n);
        return -1;
    }

    struct shield_msg *m = (struct shield_msg *)g_load_buf;

    /* COPY THE HEADER FOR THE AUDIT RECORD NOW. The scratch mapping is released on every exit
     * path below, so the wrapper cannot read from it afterwards --- pointing the record at freed
     * memory would produce an audit trail that is occasionally, silently, wrong. Only the fixed
     * header is copied; the program body is identified by the hash in the binding. */
    memcpy(copy, m, sizeof *copy);
    *seen = copy;

    /* O8: prog_len is attacker-influenced and is read before authentication.
     * There is no authentication here at all, so the length check is the only
     * thing standing between a bad field and a bad read. Check it against what
     * actually arrived. */
    size_t hdr = sizeof(struct shield_msg);
    if (m->prog_len > LS_LOAD_MAX - hdr) {
        reply(fd, "ERR payload exceeds loader ceiling\n");
        return -1;
    }
    if (m->prog_len) {
        ssize_t body = recv(fd, m->prog, m->prog_len, MSG_WAITALL);
        if (body > 0) n += body;
    }
    if (m->prog_len > (size_t)n - hdr) {
        reply(fd, "ERR prog_len %u exceeds received payload %lu\n",
              m->prog_len, (unsigned long)((size_t)n - hdr));
        return -1;
    }
    return 0;
}

/* The same configuration handler is used by the socket harness and TMM. */
static void
ls_handle_config(int fd, const struct shield_msg *m)
{
        unsigned char extra;
        /* New operations require exact framing and the client's write EOF. */
        if (recv(fd, &extra, 1, 0) != 0) {
            reply(fd, "ERR config trailing bytes or missing write EOF\n");
            return;
        }
        /* Config is authorized by the local socket owner's UID, not by the
         * code-signing key. Do not label unsigned policy bytes as signed. */
        struct { pid_t pid; uid_t uid; gid_t gid; } peer;
        socklen_t peer_len = sizeof peer;
        if (getsockopt(fd, SOL_SOCKET, SO_PEERCRED, &peer, &peer_len) != 0 ||
            peer_len != sizeof peer || peer.uid != geteuid()) {
            reply(fd, "ERR config peer must be loader owner\n");
        } else if (__atomic_load_n(&g_prep.state, __ATOMIC_ACQUIRE) != LS_PREP_IDLE) {
            reply(fd, "ERR config: prepare outstanding\n");
        } else if (m->epoch >= LS_CONFIG_SLOTS || !g_ls_config.session ||
                   !g_ls_config.slots[m->epoch].current.instance) {
            reply(fd, "ERR config: no loaded instance or session unavailable\n");
        } else if (m->op == SHIELD_OP_CONFIG_STATUS) {
            struct ls_config_slot *cs = &g_ls_config.slots[m->epoch];
            char sha[65];
            for (unsigned i = 0; i < 32; i++)
                snprintf(sha + i * 2, 3, "%02x", cs->program_sha256[i]);
            if (m->prog_len) {
                reply(fd, "ERR config-status takes no payload\n");
            } else {
                reply(fd, "OK config {\"abi\":1,\"session\":\"%016llx\","
                          "\"instance\":\"%016llx\",\"revision\":%llu,"
                          "\"schema\":%u,\"entries\":%u,\"program_sha256\":\"%s\"}\n",
                      (unsigned long long)g_ls_config.session,
                      (unsigned long long)cs->current.instance,
                      (unsigned long long)cs->current.revision,
                      cs->current.schema, cs->current.entries, sha);
            }
        } else {
            const char *why = ls_config_publish(&g_ls_config, m->epoch, m->prog, m->prog_len);
            if (why) reply(fd, "ERR %s\n", why);
            else reply(fd, "OK config published slot=%u revision=%llu\n", m->epoch,
                       (unsigned long long)g_ls_config.slots[m->epoch].current.revision);
        }
}

/* Every exit is audited by handle(); copied header survives scratch release. */
static void
handle_msg(int fd, struct shield_msg **seen, struct shield_msg *copy)
{
    unsigned char *g_load_buf = ls_load_buf_alloc();
    if (!g_load_buf) {
        reply(fd, "ERR scratch mmap failed\n");
        return;
    }
    if (ls_load_receive(fd, g_load_buf, seen, copy) != 0) {
        ls_load_buf_free(g_load_buf);
        return;
    }
    struct shield_msg *m = (struct shield_msg *)g_load_buf;
    if (m->op == SHIELD_OP_CONFIG_STATUS || m->op == SHIELD_OP_CONFIG_PUBLISH) {
        ls_handle_config(fd, m);
        ls_load_buf_free(g_load_buf);
        return;
    }

    /* O14, on real code: the binding carries ONE identity --- `hook` --- and the
     * loader needs two, because PREVAIL proved a SECTION and uBPF runs a SYMBOL.
     * Both are synthesised here by convention (section = "fentry/<hook>",
     * function = "shield"), and a convention is exactly what O14 says is not good
     * enough: nothing signed commits to either name, so the identity check in
     * ls_vm_arm is verifying the program against names this loader made up
     * rather than against names an authority asserted. The binding needs both
     * fields. Until it has them, this is the gap, not a detail. */
    /* The hook name comes from the binding; the KIND (entry vs exit) comes from
     * the OBJECT --- a program compiled for fexit/<fn> carries that section, and
     * the .o's SHA-256 (which the signature commits to) includes it, so the kind
     * cannot be re-pointed without invalidating the signature. Probe the object
     * for fexit/<hook> first; fall back to fentry/<hook>. (For ops with no program
     * attached --- ARM/STATUS/REVOKE --- this reads fentry/ and is unused; those
     * paths read the slot's recorded kind instead.) */
    char section[96];
    {
        char probe[96], tmp[64];
        snprintf(probe, sizeof probe, "fexit/%.63s", m->binding.hook);
        int is_exit = (m->prog_len > 0 &&
                       ls_function_in_section(m->prog, m->prog_len, probe, tmp, sizeof tmp) > 0);
        snprintf(section, sizeof section, "%s/%.63s",
                 is_exit ? "fexit" : "fentry", m->binding.hook);
        snprintf(probe, sizeof probe, LS_SNAPSHOT_SECTION "%.63s",
                 m->binding.hook);
        if (m->prog_len > 0 &&
            ls_function_in_section(m->prog, m->prog_len, probe,
                                   tmp, sizeof tmp) > 0)
            snprintf(section, sizeof section, "%s", probe);
    }

    /*
     * THE CTX ABI GATE. Checked for every op that loads or arms, before anything
     * else is looked at.
     *
     * A program is verified by PREVAIL against a ctx STRUCT it was compiled with.
     * The running TMM's builders produce a struct of their own shape. Nothing
     * connected those two facts until now, so a program built against a different
     * layout loaded cleanly, verified cleanly, and read adjacent fields as its own.
     * That is not hypothetical: ls_ctx_rst went 64 -> 92 bytes and gained a flow
     * cookie on 2026-08-17, and the mismatch is silent in both directions.
     *
     * ZERO IS ACCEPTED, DELIBERATELY, AND IT IS A TRANSITION MEASURE. Every client
     * written before this field existed sends a zeroed binding, and refusing those
     * would break the loader the moment this ships while proving nothing --- the
     * problem it guards is a layout mismatch, not an old client. It is logged so the
     * silence is visible, and the acceptance should be removed once ls-load.py and
     * the control plane both set it. TODO(f5): make 0 a refusal.
     *
     * Unsigned, and that is correct for this check. Refusing a forged target needs
     * signature verification (item 4); refusing a mismatched layout does not, because
     * both parties are us and the failure is an honest mistake.
     */
    if (m->binding.ctx_abi_version != 0 &&
        m->binding.ctx_abi_version != SHIELD_CTX_ABI_VERSION) {
        reply(fd, "ERR ctx abi mismatch: program built for %u, this TMM builds %u. "
                  "Recompile the program against this build's headers.\n",
              (unsigned)m->binding.ctx_abi_version,
              (unsigned)SHIELD_CTX_ABI_VERSION);
        fprintf(stderr, "ls_vm: REFUSED --- ctx abi %u, expected %u\n",
                (unsigned)m->binding.ctx_abi_version,
                (unsigned)SHIELD_CTX_ABI_VERSION);
        return;
    }
    if (m->binding.ctx_abi_version == 0)
        fprintf(stderr, "ls_vm: ctx abi UNDECLARED (0) --- accepted, but this TMM "
                        "builds %u and a mismatch would be silent\n",
                (unsigned)SHIELD_CTX_ABI_VERSION);

    switch (m->op) {
    case SHIELD_OP_LOAD: {
        /* THE SIGNED BUILD RANGE, compared to something for the first time.
         *
         * It has been in the binding since the ABI was written, covered by the
         * signature, and printed into every audit record --- and until 2026-09-04
         * nothing read it. Three trails that all looked like enforcement, and no
         * enforcement. CONTESTED-PREMISES.md 15; the decision itself, and why a
         * "range" over a SHA-1 is almost always meaningless, are in
         * ls_build_gate.h.
         *
         * INSIDE case SHIELD_OP_LOAD, DELIBERATELY, AND THE FIRST VERSION HAD IT
         * OUTSIDE. Placed before `switch (m->op)` --- which is where the ctx-abi
         * check sits --- an admission gate also answers for STATUS, DISARM and
         * REVOKE. REVOKE is the kill switch. A gate that can refuse the kill
         * switch is strictly worse than one that admits a stale program: the
         * failure it creates (cannot disarm a misbehaving shield on a live data
         * plane) is more serious than the one it prevents. LOAD is the only
         * operation that admits new code, so LOAD is the only one gated.
         * SET_MODE is left alone because it introduces no code and is already
         * bounded by the signed mode_ceiling.
         *
         * THE WILDCARD AND THE ALL-ZERO RANGE ARE BOTH ACCEPTED, for different
         * reasons, both transitional. sign_shield.py has defaulted to
         * 0..0xffffffff since it was written, so every signed artifact carries the
         * wildcard; and ls_client.py never sets the field at all, so every
         * message carries 0..0. Refusing either would break every existing client
         * and artifact on the day this shipped while proving nothing. Neither is
         * an attacker escape --- the range is inside the signature, so only our
         * own key can assert a wildcard, and an undeclared range is refused as
         * soon as the clients set it. Both are logged loudly so the breadth is
         * visible rather than assumed. */
        {
            uint32_t running = 0;
            enum ls_build_verdict bv = ls_build_gate(ls_audit_build_id(),
                                                     m->binding.build_min,
                                                     m->binding.build_max, &running);
            if (bv == LS_BUILD_MISMATCH || bv == LS_BUILD_BAD_RANGE ||
                bv == LS_BUILD_NO_ID) {
                reply(fd, "ERR build gate: %s (signed 0x%08x..0x%08x, running "
                          "0x%08x). Re-sign this program for this build.\n",
                      ls_build_strerror(bv), (unsigned)m->binding.build_min,
                      (unsigned)m->binding.build_max, (unsigned)running);
                fprintf(stderr, "ls_vm: REFUSED --- %s: signed 0x%08x..0x%08x, "
                                "running 0x%08x\n", ls_build_strerror(bv),
                        (unsigned)m->binding.build_min,
                        (unsigned)m->binding.build_max, (unsigned)running);
                return;
            }
            if (bv == LS_BUILD_WILDCARD)
                fprintf(stderr, "ls_vm: build range is the WILDCARD "
                                "(0..0xffffffff) --- accepted, but this program is "
                                "vouched for on EVERY build, including ones its "
                                "field offsets do not fit. Sign with "
                                "--build-min/--build-max 0x%08x.\n",
                        (unsigned)running);
            else if (bv == LS_BUILD_UNDECLARED)
                fprintf(stderr, "ls_vm: build range UNDECLARED (0..0) --- accepted, "
                                "but nothing constrains this program to build "
                                "0x%08x. The client did not set it.\n",
                        (unsigned)running);
            else
                fprintf(stderr, "ls_vm: build gate OK --- signed for 0x%08x, "
                                "running 0x%08x\n",
                        (unsigned)m->binding.build_min, (unsigned)running);
        }

        /* EXPIRY. Defined 2026-09-05 as a uint32 Unix epoch and checked here; it
         * spent its whole life signed, logged, and compared to nothing, which is
         * the same shape as build_min/build_max before yesterday.
         *
         * IT FAILS **OPEN** ON A CLOCK IT CANNOT TRUST, unlike the build gate
         * directly above, and the asymmetry is deliberate. A shield exists to stop
         * a crash: refusing one because this container started before NTP ran turns
         * a clock problem into the outage the shield was preventing. A wrong build
         * is a correctness error and must refuse; a wrong clock is an environment
         * error and must not. ls_build_gate.h carries the argument and
         * check_build_gate.c asserts the branch, so it does not get "fixed" later
         * by someone reading it as a bug. */
        {
            enum ls_expiry_verdict ev =
                ls_expiry_gate(m->binding.expires_with, (uint64_t)time(NULL));
            if (ev == LS_EXPIRY_EXPIRED) {
                reply(fd, "ERR %s (expired at %u, now %u). Re-sign it.\n",
                      ls_expiry_strerror(ev), (unsigned)m->binding.expires_with,
                      (unsigned)time(NULL));
                fprintf(stderr, "ls_vm: REFUSED --- %s: expires_with=%u, now=%u\n",
                        ls_expiry_strerror(ev), (unsigned)m->binding.expires_with,
                        (unsigned)time(NULL));
                return;
            }
            if (ev == LS_EXPIRY_UNKNOWN)
                fprintf(stderr, "ls_vm: expiry NOT JUDGED --- this box's clock reads "
                                "%u, which is before 2020. Accepting rather than "
                                "refusing: a wrong clock must not block a shield.\n",
                        (unsigned)time(NULL));
            else if (ev == LS_EXPIRY_OK)
                fprintf(stderr, "ls_vm: expiry OK --- valid until %u\n",
                        (unsigned)m->binding.expires_with);
        }

        /* SIGNATURE IS VERIFIED ON THE TMM THREAD, not here. See ls_prep_run_pending.
         *
         * FALSIFIED 2026-08-20, and the correct answer was 350 lines above this one. The first
         * version called ls_sig_verify() right here, on the loader thread, with a comment
         * arguing that OpenSSL allocates through glibc rather than TMM's allocator. That is
         * wrong: TMM overrides malloc globally, so EVP's allocations go through
         * kern/malloc.c -> init_thread_cache -> a spin_lock on a lock nothing ever spin_init'd,
         * exactly as the handoff comment above already documented for ubpf_create. The loader
         * went on-CPU and never returned; `status` on that pod timed out afterwards while the
         * proxy kept serving, and NO log line was produced --- the hang was inside verify,
         * before the verdict could be printed.
         *
         * Registered as falsifier F6e in 02-RESEARCH-PARAMETERS.md before the work, which is
         * the only reason this was tested rather than assumed. CONTESTED-PREMISES.md #10.
         *
         * So verification joins the prepare work behind ls_prep, which exists for precisely
         * this class of call. The security property is unchanged --- nothing is loaded until the
         * signature checks out --- and the check simply happens on the thread where allocation
         * is legal. */
        /* "RECEIVED", not "verified". This line prints on the loader thread, BEFORE the TMM
         * thread has looked at the signature --- so the word "verified" here was a claim about
         * something that had not happened yet. In an ordinary log that is sloppy; in a security
         * log it is a false statement that a reader would reasonably believe, and the verdict
         * arrives a few lines later under `ls_sig:` and `LOAD REFUSED`. */
        fprintf(stderr,
                "ls_vm: LOAD received on %s --- hook=%.63s bytes=%u (signature checked on the "
                "prepare thread; see the ls_sig: line that follows)\n",
                g_sock_path, m->binding.hook, m->prog_len);
        /* Handed to a TMM thread: preparing here would hang this thread in
         * TMM's allocator. See ls_prep above. */
        const char *why = "unknown";
        /* The slot comes from the request. Hardcoding 0 here meant every LOAD
         * landed on slot 0 no matter what was asked for, so a program written
         * for a tracepoint on another slot loaded "successfully" and then never
         * ran --- the call site emits to its own slot, which stayed empty. The
         * comment under STATUS below already claimed LOAD did this; it did not.
         * Same reasoning for SET_MODE and REVOKE. */
        /* Take the entry function FROM the object --- the single STT_FUNC in
         * fentry/<hook> --- rather than assuming a fixed name. Falls back to
         * "shield" for older objects, so nothing that worked stops working. */
        char fnbuf[64];
        const char *fn = "shield";
        if (ls_function_in_section(m->prog, m->prog_len, section, fnbuf, sizeof fnbuf) > 0)
            fn = fnbuf;
        int slot = ls_prep_submit(LS_PREP_OP_RELOAD, (int)m->epoch, m->prog, m->prog_len,
                                  section, fn,
                                  m->mode, 0u, &m->binding, m->sig, NULL, &why);
        if (slot < 0)
            reply(fd, "ERR load refused (%s)\n", why);
        else
            /* The reply said `unverified=yes` for as long as nothing verified anything, which
             * was honest then and is false now --- reaching this line means the signature
             * verified. It says which state it is in rather than being silent, because a reader
             * who sees no mention of signatures cannot tell an enforcing build from one with
             * LS_SIG_ENFORCE off. */
            reply(fd, "OK loaded slot=%d mode=%d signature=%s\n", slot, m->mode,
                  ls_vm_sig_enforce() ? "verified" : "NOT ENFORCED");
        break;
    }
    case SHIELD_OP_SET_MODE:
        if (m->mode != MODE_DISABLE &&
            (m->epoch >= SHIELD_MAX_SHIELDS || !g_prep.targets[m->epoch].valid ||
             m->mode > g_prep.targets[m->epoch].ceiling)) {
            reply(fd, "ERR mode exceeds signed ceiling or slot has no signed target\n");
            break;
        }
        ls_vm_set_mode((int)m->epoch, (enum ls_mode)m->mode);
        reply(fd, "OK mode=%d\n", m->mode);
        break;

    case SHIELD_OP_STATUS: {
        struct ls_stats st;
        /* slot comes from epoch, as it does for LOAD and ARM. Hardcoding 0
         * made every slot but one invisible, which is a poor property for a
         * mechanism whose whole point is arming several things at once. */
        int qslot = (int)m->epoch;
        if (!ls_vm_stats(qslot, &st)) { reply(fd, "ERR no such slot %d\n", qslot); break; }
        reply(fd, "OK armed=%d mode=%d gen=%u fired=%llu safe_returns=%llu errors=%llu "
                  "cycles=%llu cycles_max=%llu cycles_min=%llu "
                  "snapshot_entry_errors=%llu snapshot_return_errors=%llu\n",
              (int)st.armed, st.mode, st.gen,
              (unsigned long long)st.fired, (unsigned long long)st.safe_returns,
              (unsigned long long)st.errors, (unsigned long long)st.cycles,
              (unsigned long long)st.cycles_max, (unsigned long long)st.cycles_min,
              (unsigned long long)st.snapshot_entry_errors,
              (unsigned long long)st.snapshot_return_errors);
        break;
    }
    /* Ops beyond the ABI's four. shield_msg.op is a uint32 and the enum uses the
     * low values, so these sit well clear --- and they are DEVELOPMENT ops, not
     * proposed additions to the protocol. A real control plane would not expose
     * "benchmark this" or "show me recent inputs" on the load path. */
    case 0x1001: {   /* BENCH: load, measure, discard --- never touches a live slot */
        /* HANDED TO A TMM THREAD, like a load. This called ls_vm_bench_program() directly
         * until 2026-08-19, on the loader thread, where TMM's allocator freezes --- the same
         * failure ls_prep exists to avoid, in the one op that was never converted. It wedged
         * the loader on-CPU, and because the clean per-call figure is this op's MIN, that
         * left the shield's per-invocation cost unquotable from a live TMM: the armed-hook
         * counter mean is dominated by rdtsc pairs spanning context switches (a single call
         * reading 1.09M then 3.14M cycles), so it measures the scheduler and not the hook. */
        struct ls_prep_result r = { -1, 0, 0, 0, 0 };
        const char *why = "?";
        char section[96];
        uint32_t iters;

        snprintf(section, sizeof section, "fentry/%.63s", m->binding.hook);
        iters = m->epoch ? m->epoch : 10000;            /* epoch reused as count */
        if (iters > LS_PREP_BENCH_MAX_ITERS) {
            /* REFUSE rather than clamp. A clamped run reports a smaller sample than was
             * asked for under the same "OK" line, and whoever reads the number will not
             * know. Every other ceiling in this file refuses for the same reason. */
            reply(fd, "ERR bench iters=%u exceeds the ceiling of %u.\n"
                      "    This runs on a TMM thread inside a poll iteration, so the "
                      "iteration count is a stall budget, not a preference.\n",
                  iters, LS_PREP_BENCH_MAX_ITERS);
            break;
        }
        /* Bench carries no signature: it loads into no slot and arms nothing, so there is
         * nothing to authorise. It is a development op and says so in the log. */
        if (ls_prep_submit(LS_PREP_OP_BENCH, -1, m->prog, m->prog_len,
                           section, "shield", 0, iters, NULL, NULL, &r, &why) != 0) {
            reply(fd, "ERR bench refused (%s)\n", why);
        } else {
            /* `path` in the reply, first, because it changes what the number MEANS. A reader
             * who sees only cycles will read an interpreter figure as a hook cost. */
            reply(fd, "OK bench path=%s iters=%u min=%llu mean=%llu max=%llu cycles bytes=%u\n"
                      "   quote the MIN; the mean is 2-3x it and measures the scheduler\n",
                  r.jitted ? "jit" : "interp",
                  iters, (unsigned long long)r.bmin, (unsigned long long)r.bmean,
                  (unsigned long long)r.bmax, m->prog_len);
        }
        break;
    }
    case 0x1002: {   /* SAMPLES: the last few ctx values the hook actually saw */
        struct ls_ctx_sample sm[LS_CTX_SAMPLES];
        unsigned n2 = ls_vm_samples((int)m->epoch, sm, LS_CTX_SAMPLES);
        if (n2 == 0) { reply(fd, "OK no samples (hook not fired, or LS_VM_SAMPLES unset)\n"); break; }
        for (unsigned i = 0; i < n2; i++) {
            char hex[2 * LS_CTX_SAMPLE_BYTES + 1];
            unsigned k = sm[i].len < LS_CTX_SAMPLE_BYTES ? sm[i].len : LS_CTX_SAMPLE_BYTES;
            for (unsigned j = 0; j < k; j++)
                snprintf(hex + 2 * j, 3, "%02x", sm[i].bytes[j]);
            hex[2 * k] = 0;
            reply(fd, "OK sample seq=%llu len=%u verdict=%u ctx=%s\n",
                  (unsigned long long)sm[i].seq, sm[i].len, sm[i].verdict, hex);
        }
        break;
    }

    case 0x1003: {   /* ARM LIVE --- hook a real function while TMM is RUNNING */
        char a[65];
        memcpy(a, m->binding.hook, 64); a[64] = 0;
        int slot = (int)m->epoch;
        if (slot < 0 || (unsigned)slot >= SHIELD_MAX_SHIELDS || !g_prep.targets[slot].valid) {
            reply(fd, "ERR arm: slot has no authenticated target; load a bound program\n");
            break;
        }
        unsigned long long addr = g_prep.targets[slot].target.entry;
        char *end = NULL;
        unsigned long long requested = strtoull(a, &end, 0);
        if (a[0] && strcmp(a, g_prep.targets[slot].hook) &&
            (!end || *end || requested != addr)) {
            reply(fd, "ERR arm: requested target differs from signed target\n");
            break;
        }
        if (g_prep.targets[slot].attached) {
            reply(fd, "ERR arm: slot is already attached\n");
            break;
        }
        /*
         * REFUSE TO ARM A SLOT WITH NO PROGRAM. Observed 2026-08-18: a load was
         * correctly refused (the object's section was fentry/rst_why while the request
         * named a different hook --- finding O14 working), and the ARM that followed
         * still reported "OK ARMED LIVE" with armed=0. Live .text on two pods was
         * patched to call a trampoline whose slot held nothing.
         *
         * It is not a crash --- ls_vm_call falls through on an empty slot --- but it is
         * a patch into a running data plane that buys nothing, reported as success. And
         * it is the shape of a worse bug: whoever reads "ARMED LIVE" believes a program
         * is running, so a later "why did nothing fire" hunt looks at traffic instead of
         * at the load that failed a minute earlier.
         *
         * Checked here rather than in ls_arm_live because ls_arm.c knows about pads and
         * trampolines, not about slots holding programs. Structurally it belongs where
         * the two are joined.
         */
        int is_exit = 0;
        {
            struct ls_stats st;
            if (!ls_vm_stats(slot, &st)) {
                reply(fd, "ERR arm: slot %d out of range\n", slot);
                break;
            }
            if (!st.armed) {
                reply(fd, "ERR arm: slot %d holds NO PROGRAM --- refusing to patch "
                          ".text for a hook that cannot run. Load first; if a load was "
                          "refused, fix that rather than arming over it.\n", slot);
                break;
            }
            is_exit = st.is_exit;   /* fexit -> arm at the RETURN via ls_fexit_table */
        }
        /* ls_arm_live rewrites the five pad bytes with the kernel's text_poke_bp
         * protocol, so the poll threads may be executing this function right now.
         * is_exit selects the entry vs exit trampoline for this slot's program. */
        if (ls_arm_live((void *)(uintptr_t)addr, (void *)ls_trampoline_entry, slot, is_exit) != 0)
            reply(fd, "ERR arm 0x%llx failed (no pad, out of rel32 range, or swap refused)\n", addr);
        else {
            g_prep.targets[slot].attached = 1;
            reply(fd, "OK ARMED LIVE entry=0x%llx slot=%d kind=%s (no restart)\n",
                   addr, slot, is_exit ? "fexit" : "fentry");
        }
        break;
    }
    case 0x1004: {   /* DISARM LIVE --- restore the nops, equally live */
        char a[65];
        memcpy(a, m->binding.hook, 64); a[64] = 0;
        char *end = NULL;
        unsigned long long requested = strtoull(a, &end, 0);
        int found = -1;
        for (unsigned i = 0; i < SHIELD_MAX_SHIELDS; i++) {
            if (!g_prep.targets[i].attached) continue;
            if ((!a[0] && m->epoch == i) || !strcmp(a, g_prep.targets[i].hook) ||
                (a[0] && end && !*end && requested == g_prep.targets[i].target.entry)) {
                found = (int)i;
                break;
            }
        }
        if (found < 0) { reply(fd, "ERR disarm: no matching attached target\n"); break; }
        unsigned long long addr = g_prep.targets[found].target.entry;
        if (ls_disarm_live((void *)(uintptr_t)addr) != 0)
            reply(fd, "ERR disarm 0x%llx failed (not armed?)\n", addr);
        else {
            g_prep.targets[found].attached = 0;
            reply(fd, "OK DISARMED LIVE entry=0x%llx\n", addr);
        }
        break;
    }

    case SHIELD_OP_REVOKE:
        /* Disarm is the honest half of revocation. The other half --- reclaiming
         * the program's memory --- needs item 0c. Mode DISABLE stops it running;
         * it does not remove it. */
        ls_vm_set_mode((int)m->epoch, LS_MODE_DISABLE);
        /* Do not race a late prepare after a loader timeout. Mode disable still
         * runs; a pending handoff is already reported by CONFIG_* as busy. */
        if (__atomic_load_n(&g_prep.state, __ATOMIC_ACQUIRE) == LS_PREP_IDLE)
            (void)ls_config_revoke(&g_ls_config, m->epoch);
        /* The registry is shared. Reclaim only when every slot is disabled;
         * another loaded program must retain its map references and contents.
         * The reset also refuses an in-flight VM call without waiting. */
        if (__atomic_load_n(&g_prep.state, __ATOMIC_ACQUIRE) == LS_PREP_IDLE) {
            int active = 0;
            for (unsigned i = 0; i < SHIELD_MAX_SHIELDS; i++) {
                struct ls_stats st;
                if (ls_vm_stats((int)i, &st) && st.armed && st.mode != LS_MODE_DISABLE)
                    active = 1;
            }
            if (!active)
                (void)ls_map_reset_shapes();
        }
        reply(fd, "OK disabled (not reclaimed --- see item 0c)\n");
        break;

    default:
        reply(fd, "ERR unknown op %d\n", m->op);
    }
    ls_load_buf_free(g_load_buf);
}

/* ONE RECORD PER CONNECTION, whatever happened on it. The wrapper exists because handle_msg has
 * a dozen exits and an audit call at each one is an audit call that will be forgotten at the
 * thirteenth --- which is the specific way this kind of instrumentation rots. */
static void
handle(int fd)
{
    struct shield_msg  copy;
    struct shield_msg *seen = NULL;

    ls_audit_clear_reply();
    handle_msg(fd, &seen, &copy);
    /* A missing reply means a path returned without answering the caller. That is a bug rather
     * than an outcome, and it is recorded as one instead of producing a record whose verdict
     * field is blank and therefore reads as "allowed". */
    const char *said = ls_audit_last_reply();
    ls_audit_op(fd, seen, said != NULL ? said
                                       : "NO REPLY SENT --- handler returned silently");
}

void ls_vm_loader_start(void);
void ls_vm_bootstrap(void);

/* Startup, once per TMM thread. Registered by ls_prep.c through TMM's INIT_FUNC
 * linker set, so no F5 source calls it --- see the note there.
 *
 * Lives on this side of the include-world split because ls_vm_init() returns
 * bool and ls_vm_arm_configured() takes size_t. Redeclaring those in TMM's
 * -nostdinc world would risk a genuine ABI mismatch (bool returns in al; reading
 * eax as int does not guarantee the upper bits), so only a void(void) crosses. */
void
ls_vm_bootstrap(void)
{
    if (!ls_vm_init())
        return;   /* VM down; TMM behaves exactly as shipped */

    /* SAY WHETHER THIS BUILD CAN VERIFY, at startup, before anything tries to load.
     * A keyless build refuses every load --- correct, and confusing to meet for the first time
     * as a refusal. An operator should learn it from the boot log. */
    if (!ls_vm_sig_enforce())
        fprintf(stderr, "ls_vm: *** SIGNATURE ENFORCEMENT IS OFF (LS_SIG_ENFORCE) --- every "
                        "program is admitted regardless of signature. Debugging only.\n");
    else if (ls_sig_have_pubkey())
        fprintf(stderr, "ls_vm: signature verification ARMED --- unsigned programs are refused\n");
    else
        fprintf(stderr, "ls_vm: NO SIGNING KEY in this build --- EVERY load will be refused. "
                        "Generate one with substrate/gen_sig_pubkey.py and rebuild.\n");

    /* Both identities: PREVAIL proved the SECTION, uBPF runs the SYMBOL, and
     * ls_vm_arm refuses unless they are the same program (O14). The _configured
     * form applies the environment overrides --- program source, names, mode ---
     * so changing any of them is a restart rather than a rebuild. */
    (void)ls_vm_arm_configured(ls_shield_blob, sizeof ls_shield_blob,
                               LS_SHIELD_SECTION, LS_SHIELD_FUNCTION);

    /* Runtime load path. Does nothing unless LS_LOAD_SOCKET is set. Programs arriving on it
     * are signature-checked (ls_sig.c); the SOCKET itself is not authenticated, so what the
     * env gate and the 0600 mode contain is who may ASK, not what may run. */
    ls_vm_loader_start();
}

static void *
loader_thread(void *arg)
{
    (void)arg;

    /* Block signals on this thread. TMM is timer-driven, and an unblocked helper
     * thread has accept() interrupted (EINTR) continuously -- measured as a
     * spinning thread that never accepts a queued connection. Signal handling
     * belongs to the poll threads and crashagent, not here.
     *
     * SIGTRAP is deliberately left UNBLOCKED: the safe swap's breakpoint is a
     * synchronous, thread-directed signal, and blocking it would convert a
     * mid-patch trap into the kernel's fatal default action. */
    sigset_t block;
    sigfillset(&block);
    sigdelset(&block, SIGTRAP);
    sigdelset(&block, SIGSEGV);
    sigdelset(&block, SIGBUS);
    sigdelset(&block, SIGILL);
    sigdelset(&block, SIGFPE);
    pthread_sigmask(SIG_SETMASK, &block, NULL);

    int srv = socket(AF_UNIX, SOCK_STREAM, 0);
    if (srv < 0) {
        fprintf(stderr, "ls_vm: loader socket(): %s\n", strerror(errno));
        return NULL;
    }

    struct sockaddr_un sa;
    memset(&sa, 0, sizeof sa);
    sa.sun_family = AF_UNIX;
    snprintf(sa.sun_path, sizeof sa.sun_path, "%s", g_sock_path);
    unlink(g_sock_path);

    /* 0600 before anyone can connect: the bind inherits the umask, so set it
     * rather than assume it. This is containment, not authentication --- it
     * limits who can reach an unauthenticated load path to whoever shares the
     * uid, which in this container is root. */
    mode_t old = umask(0177);
    int rc = bind(srv, (struct sockaddr *)&sa, sizeof sa);
    umask(old);
    if (rc < 0 || listen(srv, 4) < 0) {
        fprintf(stderr, "ls_vm: loader bind/listen %s: %s\n", g_sock_path, strerror(errno));
        close(srv);
        return NULL;
    }

    /* THE THIRD FALSE STRING FOUND IN ONE SWEEP, 2026-08-20, and the one that would have
     * mattered most: it is the FIRST thing the loader says, so a reader who saw it and stopped
     * would carry away exactly the wrong belief about a security property. It was written when
     * it was true and not revisited when it stopped being true --- which is the whole failure
     * mode, not a typo. What is stated instead is the property that still holds: the program
     * is authenticated, the caller is not. */
    /* Before the first accept, so the sink and the build ID are known for record 1 rather than
     * being filled in lazily by whichever request happens to arrive first. */
    ls_audit_init();

    /* A fresh process/fork session makes captured controller requests stale.
     * Failure leaves configuration unavailable; never invent a weak nonce. */
    uint64_t session = 0;
    if (getrandom(&session, sizeof session, GRND_NONBLOCK) != sizeof session || !session) {
        session = 0;
        fprintf(stderr, "ls_vm: configuration session unavailable (getrandom)\n");
    }
    g_ls_config.session = session;

    fprintf(stderr,
            "ls_vm: LOADER LISTENING on %s --- programs are signature-checked, the PEER is "
            "not, and every operation is recorded (ls_audit:). Lab builds only.\n",
            g_sock_path);

    for (;;) {
        int fd = accept(srv, NULL, NULL);
        if (fd < 0) {
            if (errno == EINTR) continue;
            break;
        }
        handle(fd);
        close(fd);
    }
    close(srv);
    return NULL;
}


/* pthreads do not survive fork(): a child keeps the listening socket but loses
 * the thread that was accepting on it, which looks exactly like a hang. Restart
 * it in the child. */
static void
ls_loader_after_fork(void)
{
    g_loader_running = 0;
    ls_vm_loader_start();
}

/* Called from init, off the data path. No socket unless asked for. */
void
ls_vm_loader_start(void)
{
    const char *p = getenv("LS_LOAD_SOCKET");
    if (p == NULL || *p == '\0')
        return;                      /* default: no load path at all */

    /* Every TMM thread reaches here (http_psm_init is per-thread); tid 0 takes
     * the timer. Done before the g_loader_running check so the owner registers
     * even when it is not the thread that created the loader. */
    ls_prep_timer_start();

    if (g_loader_running)
        return;
    /* PER-INSTANCE path. BNK runs one TMM instance per core, each its own
     * process with its own address space, so a single shared path lets only the
     * first instance bind --- the rest fail bind() and their loader thread
     * exits, leaving a socket nobody accepts on. Arming is per-address-space
     * too, so one socket could only ever arm one core. */
    snprintf(g_sock_path, sizeof g_sock_path, "%s.%d", p, (int)getpid());
    if (pthread_create(&g_loader, NULL, loader_thread, NULL) != 0) {
        fprintf(stderr, "ls_vm: could not start loader thread\n");
        return;
    }
    pthread_detach(g_loader);
    g_loader_running = 1;
    static int atfork_done;
    if (!atfork_done) {
        pthread_atfork(NULL, NULL, ls_loader_after_fork);
        atfork_done = 1;
    }
}

vm_stack_policy.h.text:
/*
 * vm_stack_policy.h --- item 6a, resolved the way uBPF actually supports.
 *
 * The problem: PREVAIL proves memory safety against a *declared* per-subprogram
 * stack frame (its `subprogram_stack_size`, default 512). uBPF then executes the
 * program with a frame size of its own. If those disagree the proof is valid and
 * about different hardware, which is the one failure a signing gate cannot catch.
 *
 * The fix is NOT to pick 256 or 512 and hope both sides keep it. uBPF exposes
 *
 *     ubpf_register_stack_usage_calculator(vm, calculator, cookie)
 *
 * and calls it during load for every local function, using the result to adjust
 * r10 on entry (vm/ubpf_vm.c:872 in the interpreter, ubpf_jit_x86_64.c:1827 and
 * ubpf_jit_arm64.c:1260 in the JITs). So the host can make the runtime allocate
 * *exactly what the verifier proved against*, by construction rather than by two
 * constants coincidentally agreeing.
 *
 * Two things in uBPF's contract to know before relying on it. Both are the
 * permissive direction, and both are the opposite of what its own header says:
 *
 *   ubpf.h --- "If the callback returns 0 or there is no callback registered,
 *   the eBPF interpreter/JITer assume that the local function uses the maximum
 *   stack available according to the spec (512K)."
 *
 *   (1) With no calculator registered, ubpf_stack_usage_for_local_func() returns
 *       UBPF_EBPF_LOCAL_FUNCTION_STACK_SIZE --- 256, not a maximum.
 *   (2) A calculator returning 0 is recorded as UBPF_STACK_USAGE_CUSTOM with value
 *       0, so the accessor returns 0 and the function gets a ZERO-BYTE frame. The
 *       16-byte alignment guard passes it (0 % 16 == 0) and nothing else rejects
 *       it, in the interpreter or either JIT.
 *
 * So a calculator must never return 0 to mean "I don't know" --- that is the value
 * the documentation calls safest and the code treats as smallest.
 *
 * Status: candidate artifact. It compiles and asserts its own invariants. It is
 * not wired into a VM here --- nothing in this repo instantiates or runs a shield.
 */

#ifndef VM_STACK_POLICY_H
#define VM_STACK_POLICY_H

#include <stdint.h>

/* uBPF requires every frame size to be 16-byte aligned (vm/ubpf_vm.c:2384) and
 * fails the load otherwise, so the policy rounds UP rather than discovering this
 * at load time. */
#define VM_STACK_ALIGN 16u

/* uBPF's own ceiling: UBPF_EBPF_STACK_SIZE is UBPF_MAX_CALL_DEPTH * 512 = 4096,
 * so a frame can never usefully exceed 4096 / depth. Named rather than inlined so
 * the relationship survives an upstream change. */
#define VM_STACK_TOTAL      4096u
#define VM_STACK_MAX_DEPTH     8u

/* What PREVAIL was actually told. This must be the value passed to
 * `prevail --stack-size N`, not a guess about its default --- the default is 512
 * and the runtime fallback is 256, which is exactly the divergence this removes. */
struct vm_stack_policy {
    uint16_t proven_frame;   /* bytes per subprogram, as verified   */
    uint16_t max_depth;      /* call frames, as verified            */
};

static inline uint16_t
vm_stack_align_up(uint16_t n)
{
    return (uint16_t)((n + (VM_STACK_ALIGN - 1u)) & (uint16_t)~(VM_STACK_ALIGN - 1u));
}

/* Is this a policy uBPF can honour? Checked at admission, not at load: a policy
 * that fails here means the verify step and the runtime disagree, and the program
 * must be refused rather than run under whichever bound happens to win. */
static inline int
vm_stack_policy_valid(const struct vm_stack_policy *p)
{
    if (p == 0)
        return 0;
    if (p->proven_frame == 0)               /* the zero-frame trap above */
        return 0;
    if (p->max_depth == 0 || p->max_depth > VM_STACK_MAX_DEPTH)
        return 0;
    if (vm_stack_align_up(p->proven_frame) != p->proven_frame)
        return 0;
    if ((uint32_t)p->proven_frame * (uint32_t)p->max_depth > VM_STACK_TOTAL)
        return 0;
    return 1;
}

/*
 * The calculator. uBPF's typedef is:
 *
 *     typedef int (*stack_usage_calculator_t)(const struct ubpf_vm *vm,
 *                                            uint16_t pc, void *cookie);
 *
 * This one takes `const void *` for the first parameter, because this header
 * must stay checkable without uBPF's headers present. That makes it a DIFFERENT
 * function pointer type, NOT assignable to the typedef --- the host writes a
 * one-line forwarding function (see ls_vm.c). Do not convert the pointer to fit:
 * calling through a converted incompatible function pointer is undefined
 * behaviour, and gcc will warn about exactly this if you try.
 *
 * Deliberately uniform: every local function gets the frame the verifier proved
 * against, because that is the only bound the proof covers. Per-function
 * refinement would need per-function evidence, and PREVAIL reports one bound for
 * the program.
 *
 * NEVER returns 0. Given no valid policy it returns the largest frame uBPF can
 * give at max depth --- the conservative direction the header wrongly attributes
 * to 0. A load that cannot be handed a valid policy should be refused upstream;
 * this is the backstop, not the gate.
 */
static inline int
vm_stack_usage(const void *vm_unused, uint16_t pc_unused, void *cookie)
{
    const struct vm_stack_policy *p = (const struct vm_stack_policy *)cookie;

    (void)vm_unused;
    (void)pc_unused;

    if (!vm_stack_policy_valid(p))
        return (int)(VM_STACK_TOTAL / VM_STACK_MAX_DEPTH);

    return (int)p->proven_frame;
}

/* Pinned so a change to the constants fails the build rather than silently
 * widening what is admitted. */
_Static_assert(VM_STACK_TOTAL % VM_STACK_MAX_DEPTH == 0,
               "total stack must divide evenly by max depth");
_Static_assert((VM_STACK_TOTAL / VM_STACK_MAX_DEPTH) % VM_STACK_ALIGN == 0,
               "the fallback frame must satisfy uBPF's 16-byte alignment");
_Static_assert(VM_STACK_ALIGN != 0u && (VM_STACK_ALIGN & (VM_STACK_ALIGN - 1u)) == 0u,
               "alignment must be a power of two for the round-up to be correct");

#endif /* VM_STACK_POLICY_H */
